-- 218: longer explanations for the high-relevance Basiskonzept ratings of the AI-drafted grade 5/6 goals.
--
-- Susan Hanisch, 2026-11-02: the explanations drafted by migration 214 are too short where the relevance is high; they should be about as long as
-- in her own goals (median 54 words at rating 3 and 48 at rating 2, against 21 in the drafts). 115 goals, 165 explanations (ratings 2 and 3)
-- are rewritten in the live space and in the sandbox copy. The new texts are AI drafts that nobody has checked; content.ki_entwurf stays on every
-- goal and gets begruendungen_erweitert = 2026-11-02.
-- A Hermes (GWDG) review of the new texts found 7 entries whose own explanation admits that the goal does not contain the concept. Those
-- ratings are corrected here (to 1, no link, or from 3 to 2 with a rewritten text), together with the main and secondary concept lists of the goal.
-- Tags, methods and everything else are untouched.
-- Each UPDATE only changes a goal whose explanations still have the exact old text, so a later human edit is never overwritten and running this
-- twice changes nothing. Generated by scripts/generate_basiskonzept_expansion_migration.py.
SET search_path = public, extensions;

-- ===== evomentor-thuringia =====
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel nennt die Lunge als das Organ, über das Sauerstoff in das Blut gelangt, und verbindet damit ein Organ mit einer Aufgabe. Das passt zum Gedanken des Konzepts, dass Bau und Funktion oft zusammenhängen. Wie die Lunge gebaut ist und warum dieser Bau den Übertritt erleichtert, steht im Lernziel aber nicht im Mittelpunkt.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Sauerstoff wird über die Lunge in das Blut aufgenommen. Das ist ein Stoffaustausch mit der Umwelt, wie ihn das Konzept für offene biologische Systeme beschreibt: Lebewesen nehmen Stoffe auf und geben andere wieder ab. Der aufgenommene Sauerstoff ist zugleich die Voraussetzung dafür, dass der Körper Energie gewinnen kann. Lernende bauen so die Vorstellung auf, dass ein Lebewesen mit seiner Umgebung im ständigen Austausch steht.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '2860014e-a8b1-4dc5-9e3e-03cce7f7da8d' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Lunge ist das Organ, in dem Sauerstoff ins Blut übertritt; ihr Bau steht im Lernziel aber nicht im Mittelpunkt.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Die Aufnahme von Sauerstoff in das Blut ist ein Stoffaustausch mit der Umwelt und die Voraussetzung für die Energiegewinnung im Körper.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Das Lernziel erläutert, wie der Grasfrosch als Larve im Wasser und als erwachsenes Tier an Land lebt, und spricht dabei von Angepasstheit an beide Lebensräume. Angepasstheit gilt im Konzept als Ergebnis evolutiver Prozesse, das über Generationen durch natürliche Selektion entstanden ist. Wie sie entstanden ist, spricht das Lernziel jedoch nicht an. Der stammesgeschichtliche Bezug ist nur angedeutet.$t$::text)), '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Das Lernziel zeichnet den gesamten Entwicklungsweg des Grasfroschs nach: vom Laich über die im Wasser lebende Larve mit Kiemen und Ruderschwanz bis zum erwachsenen Tier an Land mit Lunge und Gliedmaßen. Das entspricht einer indirekten Entwicklung mit Metamorphose, bei der sich Larve und erwachsenes Tier in Gestalt und Lebensweise deutlich unterscheiden. Lernende erfassen Entwicklung so als Abfolge von Phasen mit tiefgreifendem Umbau des Körpers.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel ordnet jedem Lebensraum eigene Körpermerkmale zu: Kiemen und Ruderschwanz der Larve im Wasser, feuchte Haut, Lunge und Gliedmaßen des erwachsenen Tiers an Land. Damit wird der Bau eines Körperteils ausdrücklich mit seiner Leistung in der jeweiligen Umwelt verknüpft, wie es das Konzept über Gestalt und inneren Bau beschreibt. Lernende üben, von Merkmalen des Körpers auf deren Funktion im Lebensraum zu schließen.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Der Gasaustausch ist ein Stoffaustausch mit der Umwelt: Die Larve tauscht Gase über Kiemen aus, das erwachsene Tier über feuchte Haut und Lunge. Das passt zum Konzept, wonach Lebewesen mit ihrer Umgebung Stoffe austauschen. Der Austausch bleibt ein Teilaspekt, denn das Lernziel gilt vor allem Entwicklung und Körperbau. Umwandlung von Stoffen oder Energie kommt nicht vor.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '60661c98-dc41-4416-958a-ae9c35341cdb' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Die Angepasstheit an Wasser und Land ist ein Ergebnis der Stammesgeschichte; das Lernziel spricht diese aber nicht an.$t$ AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Vom Laich über die Larve bis zum erwachsenen Tier wird ein ganzer Entwicklungsweg mit Verwandlung beschrieben.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Kiemen und Ruderschwanz im Wasser, Lunge, feuchte Haut und Gliedmaßen an Land: Bau und Lebensraum werden ausdrücklich verknüpft.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Der Gasaustausch wechselt von Kiemen zu Haut und Lunge. Der Stoffaustausch mit der Umwelt ist ein Teilaspekt des Lernziels.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Das Lernziel beschreibt, wie Nahrungsbausteine und Sauerstoff im Körper in alle Teile gelangen, damit sie dort genutzt werden können. Dieser Stofftransport verbindet die Aufnahme von Stoffen aus der Umwelt mit ihrer Verwendung im Körper und trifft damit die Idee des Konzepts, dass Lebewesen Stoffe aufnehmen, umwandeln und nutzen. Der Stofftransport im Körper ist der Kern des Lernziels. Lernende verstehen den Körper dabei als System, das ständig mit Stoffen versorgt werden muss.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '0a41c0d9-62f3-4269-9496-5666ebcd62ca' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Nahrungsbausteine und Sauerstoff werden in alle Körperteile gebracht, damit sie dort genutzt werden können. Der Stofftransport im Körper ist der Kern des Lernziels.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Das Lernziel führt in die Stoffebene ein: Reinstoffe werden an Farbe, Aggregatzustand, Geruch und Oberflächenbeschaffenheit erkannt und unterschieden. Der Aggregatzustand verweist zudem auf den Energiezustand der Teilchen. Damit entsteht eine Grundlage, um später Stoffe und ihre Umwandlungen zu betrachten. Stoff- und Energieumwandlung selbst werden hier noch nicht behandelt, der Bezug bleibt mittelbar.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '495fd4e5-0e00-469a-aad2-5012d7e6b979' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Das Beschreiben von Farbe, Aggregatzustand, Geruch und Oberflächenbeschaffenheit führt in die Stoffebene ein: Reinstoffe werden an ihren Eigenschaften erkannt und unterschieden, der Aggregatzustand verweist auf den Energiezustand der Teilchen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Beim Vergleich von biologischem Vorbild und technischer Umsetzung, hier am Nebeltrinkerkäfer, steht das gemeinsame Prinzip im Mittelpunkt: Eine bestimmte Oberflächengestalt ermöglicht eine bestimmte Funktion, im Lebewesen wie in der Technik. Das ist der Kern des Konzepts, wonach zwischen der Gestalt einer Struktur und ihrer Funktion ein Zusammenhang besteht. Lernende üben, Funktionen auf Merkmale des Baus zurückzuführen und dieses Muster auf andere Gegenstände zu übertragen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'f2096fa9-2a38-45fd-a2f9-7c7296042628' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Der Vergleich arbeitet das gemeinsame Prinzip heraus: Eine bestimmte Oberflächengestalt ermöglicht eine bestimmte Funktion, im Lebewesen wie in der Technik.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Wer ein Skelettmodell gestaltet, muss entscheiden, wie Knochen und Gelenke zusammengesetzt werden, und sieht dabei, dass sie gemeinsam Stütze und Beweglichkeit ermöglichen. Der Bau des Skeletts wird so handelnd mit seiner Funktion verbunden, wie es das Konzept beschreibt. Das Modell macht Strukturen sichtbar, die im Körper verborgen liegen. Lernende bauen die Denkweise auf, aus der Anordnung der Teile auf ihre Aufgabe zu schließen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '839d5d28-ca73-42a0-8d82-f784cbcda369' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Beim Gestalten eines Skelettmodells wird sichtbar, wie Knochen und Gelenke zusammen Stütze und Beweglichkeit ermöglichen, also wie der Bau die Funktion bestimmt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Beim Abmessen von Flüssigkeiten werden Stoffe als messbare Größen behandelt, am Rand auch das Arbeiten mit Stoffmengen. Das berührt das Konzept nur schwach, denn dessen Kern sind Austausch, Umwandlung und Energiebedarf von Stoffen in Lebewesen. Das Lernziel betrifft die Messtechnik. Stoffumwandlung und Energie kommen darin nicht vor, die Zuordnung ist daher nur vorsichtig.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'ea8f0941-e324-4054-adc3-164f7b87da3c' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Das Abmessen von Flüssigkeitsmengen berührt Stoffe als messbare Größen, am Rand auch das Arbeiten mit Stoffmengen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Wildwachsende Samenpflanzen sind Nahrungsgrundlage für Tiere und stellen Sauerstoff bereit. Damit sind Stoff- und Energiefluss in Lebensgemeinschaften unmittelbar angesprochen: Energie gelangt von den Pflanzen als Produzenten über die Nahrung zu den Tieren, und Sauerstoff ist ein Stoff, den Pflanzen an die Umwelt abgeben. Lernende erkennen, dass Lebensgemeinschaften über Stoffe und Energie miteinander verbunden sind.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '6421c82e-5e45-4f71-9e91-f0a3b30b44a0' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Pflanzen sind Nahrungsgrundlage für Tiere und stellen Sauerstoff bereit. Damit sind Stoff- und Energiefluss in Lebensgemeinschaften unmittelbar angesprochen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel verlangt, Gelenke als Voraussetzung für Beweglichkeit zu beschreiben. Der Bau eines Gelenks, etwa Gelenkkopf und Gelenkpfanne, wird damit mit seiner Funktion verbunden. Das ist ein klares Beispiel für den Zusammenhang von Struktur und Funktion: Die Form der Gelenkteile hängt mit der möglichen Bewegung zusammen. Lernende erfahren, dass die Gestalt eines Körperteils mit erklärt, was es leisten kann.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'cdb43ae5-86da-4114-93b9-b9f856e9267f' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Der Bau eines Gelenks (z. B. Gelenkkopf, Gelenkpfanne) wird mit der Funktion Beweglichkeit verbunden.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Skelett ist ein zentrales Beispiel für den Bau des Körpers. Die Gliederung in Schädel, Wirbelsäule, Schulter- und Beckengürtel, Gliedmaßen und Brustkorb benennt die Strukturen, an denen sich später Funktionen wie Stütze und Bewegung erklären lassen. Das Lernziel beschreibt zunächst den Bau. Lernende erwerben damit die Begriffe, die sie brauchen, um Bau und Funktion des Körpers später aufeinander zu beziehen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '16b57533-6fb5-4c10-965f-8ac390baa407' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Skelett ist ein zentrales Beispiel für den Bau des Körpers. Die Gliederung in Schädel, Wirbelsäule, Gürtel, Gliedmaßen und Brustkorb legt die Grundlage für die Funktionen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel verbindet zwei Strukturen, Muskulatur und Skelett, zu einer gemeinsamen Funktion: Muskeln und Knochen wirken zusammen, damit Bewegung entsteht, etwa wenn ein Muskel über ein Gelenk an einem Knochen zieht. Am Beispiel lässt sich zeigen, dass Muskelpaare mit entgegengesetzter Wirkung ein Gelenk in beide Richtungen bewegen und seine Stellung steuern. Lernende erkennen, dass eine Leistung des Körpers erst durch das Zusammenspiel mehrerer Strukturen entsteht.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '67912053-96bf-4aa8-9c7d-e99c706435f5' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Muskeln und Knochen wirken zusammen, damit Bewegung entsteht, etwa wenn ein Muskel über ein Gelenk an einem Knochen zieht.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Das Lernziel nennt den Aufbau körpereigener Stoffe, zum Beispiel für das Wachstum. Wachstum, also die Zunahme von Zellzahl oder Zellgröße, ist ein Teilprozess der individuellen Entwicklung. Der Bezug besteht, doch das Lernziel gilt der Bedeutung von Ernährung und Atmung. Der Lebenslauf eines Organismus wird nicht behandelt, daher steht Wachstum hier nicht im Kern.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Das Lernziel beschreibt, dass Nahrung zum Aufbau körpereigener Stoffe genutzt wird und über die Atmung Energie bereitstellt. Aufgenommene Stoffe werden dabei im Körper in andere Stoffe umgewandelt, und die in der Nahrung gebundene Energie wird für Lebensvorgänge nutzbar. Beides berührt Stoffumwandlung und Energieumwandlung unmittelbar. Lernende bauen die Vorstellung auf, dass Lebewesen Stoffe und Energie aus der Umwelt nutzen müssen, um zu wachsen und zu leben.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '97d2df63-0c68-4059-b86e-7efb55ee9d28' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Nährstoffe dienen dem Wachstum; Wachstum ist ein Teil der Individualentwicklung, steht hier aber nicht im Kern.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Nahrung wird zum Aufbau körpereigener Stoffe genutzt und liefert über die Atmung Energie. Das berührt Stoffumwandlung und Energieumwandlung unmittelbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Das Säugen mit Muttermilch gehört zur Entwicklung der Jungen nach der Geburt und zur Brutpflege bei Säugetieren. Es ist ein fester Abschnitt im Lebenszyklus und Teil der Fortpflanzung, die einen neuen Entwicklungszyklus beginnen lässt. Lernende ordnen das Säugen als Phase der Entwicklung eines Individuums ein, das nach der Geburt zunächst von der Mutter versorgt wird und erst allmählich selbstständig wird.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Die Muttermilch liefert dem Neugeborenen Nährstoffe und Energie und ist damit Stoffübertragung von der Mutter auf das Jungtier. Das passt zum Konzept, wonach Lebewesen Stoffe aufnehmen und als Energiequelle nutzen. Im Lernziel steht jedoch das Säugen als Teil von Fortpflanzung und Entwicklung im Vordergrund. Die Umwandlung der Nährstoffe wird nicht angesprochen, der Bezug ist nur am Rand gegeben.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'd5f16e34-2307-4198-9a59-bece6cb7a9fa' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Das Säugen mit Muttermilch gehört zur Entwicklung der Jungen nach der Geburt und zur Brutpflege bei Säugetieren.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Die Muttermilch liefert dem Neugeborenen Nährstoffe und Energie und ist damit Stoffübertragung von der Mutter auf das Jungtier.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Nesthocker und Nestflüchter unterscheiden sich in der Entwicklung bei und nach der Geburt: Die Jungtiere sind unterschiedlich weit entwickelt und brauchen unterschiedlich lange Pflege. Damit geht es um die Entwicklungsphasen im Lebenszyklus und um die Fortpflanzung, mit der ein neuer Entwicklungszyklus beginnt. Der Vergleich beider Formen zeigt Lernenden, dass der Entwicklungsstand zur Geburt je nach Art verschieden ist und die Individualentwicklung entsprechend unterschiedlich verläuft.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '73c74eb7-65d6-4ee3-8168-4eede002575f' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Nesthocker und Nestflüchter unterscheiden sich in der Entwicklung bei und nach der Geburt, also darin, wie weit Jungtiere entwickelt sind und wie lange sie Pflege brauchen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Oberflächenvergrößerung ist ein eigenes Strukturprinzip des Konzepts. Eine Grenzfläche wird durch Falten, Ausstülpungen oder Verzweigungen vergrößert, wie bei Darmzotten und Lungenbläschen, und kann dadurch Austauschvorgänge beschleunigen. So ermöglicht der Bau eines Organs seine Funktion. Lernende bauen die Denkweise auf, dass die Größe und Gestalt einer Fläche die Leistung eines Organs mitbestimmt, und können sie auf weitere Organe übertragen.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Eine große Fläche erleichtert die Aufnahme von Nährstoffen und Sauerstoff und damit den Stoffaustausch mit der Umgebung, den das Konzept für offene Systeme beschreibt. Im Lernziel steht jedoch die Darstellung des Bauprinzips im Mittelpunkt. Was mit den aufgenommenen Stoffen im Körper geschieht, wird nicht angesprochen. Die Zuordnung bleibt deshalb eine Ergänzung zum Kern des Lernziels.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'f3783335-62b1-4984-8c84-f1ac0d4c2a82' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Prinzip der Oberflächenvergrößerung (z. B. Darmzotten, Lungenbläschen) zeigt, wie der Bau eines Organs seine Funktion ermöglicht.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Eine große Fläche erleichtert die Aufnahme von Nährstoffen und Sauerstoff, also den Stoffaustausch mit der Umgebung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Der Versuch zeigt, dass die Laubblätter das Organ sind, über das Wasserdampf abgegeben wird. Einem Organ wird so eine Aufgabe zugeordnet, wie es das Konzept beschreibt. Wie das Blatt dafür gebaut ist und warum sein Bau die Abgabe ermöglicht, bleibt im Lernziel jedoch offen. Im Zentrum steht der Vorgang selbst, daher ist der Bezug nur teilweise gegeben.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Die Pflanze gibt Wasserdampf über die Laubblätter an die Umgebung ab, und die Wassertropfen an der übergestülpten Folie machen diesen Stoffaustausch mit der Umwelt direkt sichtbar. Der Versuch zeigt, dass eine Pflanze als offenes System im ständigen Austausch mit ihrer Umgebung steht und Stoffe an sie abgibt. Lernende beobachten selbst, dass der Austausch von Stoffen mit der Umwelt auch bei Pflanzen stattfindet.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'a5af7d6d-c079-435a-b39f-00f0a66f4077' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Laubblätter sind das Organ, über das Wasserdampf abgegeben wird; der Versuch lenkt den Blick auf diese Aufgabe des Blattes.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Die Pflanze gibt Wasser an die Umgebung ab, und die Wassertropfen an der Folie machen diesen Stoffaustausch mit der Umwelt direkt sichtbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,5,begruendung}', to_jsonb($t$Beobachten mit einer Lupe dient dem Gewinnen von Information über einen Gegenstand, denn die Lupe macht Einzelheiten erkennbar. Das Konzept beschreibt dagegen vor allem, wie Lebewesen selbst Information aufnehmen, weiterleiten und verarbeiten. Das Lernziel gilt dem sachgerechten Umgang mit dem Arbeitsmittel. Der Bezug ist methodisch und schwach, die Zuordnung daher nur vorsichtig.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '47fc703a-7984-4932-a7e4-6b148a26107b' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,5,begruendung}' = $t$Beobachten mit einer Lupe dient dem Gewinnen von Information über einen Gegenstand; der Bezug ist methodisch und schwach, die Zuordnung daher nur vorsichtig.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Reagenzglas, Becherglas und Pipette unterscheiden sich in Form und Zweck, und ihre Verwendung ergibt sich aus dem Bau des Geräts. Das ähnelt dem Gedanken des Konzepts, dass Gestalt und Funktion zusammenhängen. Das Konzept gilt jedoch Lebewesen und Lebensvorgängen, das Lernziel dem sachgerechten Umgang mit Laborgeräten. Der Bezug ist methodisch und schwach, die Zuordnung daher nur vorsichtig.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'a36ab3ec-5ed5-4f3e-bda0-f8526c98900e' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Reagenzglas, Becherglas und Pipette unterscheiden sich in Form und Zweck; die Verwendung ergibt sich aus dem Bau des Geräts. Der Bezug ist methodisch und schwach, die Zuordnung daher nur vorsichtig.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,5,begruendung}', to_jsonb($t$Messen mit Maßband, Waage oder Thermometer liefert Zahlenwerte als Information über einen Gegenstand. Das Konzept beschreibt aber vor allem, wie Lebewesen Information aufnehmen, weiterleiten und darauf reagieren, und das ist im Lernziel nicht angesprochen. Es geht um den sachgerechten Gebrauch der Messgeräte. Der Bezug ist methodisch und schwach, die Zuordnung daher nur vorsichtig.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '991c908e-995f-4975-9e58-c7000588412c' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,5,begruendung}' = $t$Messen liefert Zahlenwerte als Information über einen Gegenstand; der Bezug ist methodisch und schwach, die Zuordnung daher nur vorsichtig.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Die Kiemenatmung der Bachforelle wird als Angepasstheit an den Lebensraum Wasser erläutert. Angepasstheit gilt im Konzept als Ergebnis evolutiver Prozesse, das über viele Generationen durch natürliche Selektion entstanden ist. Als Ergebnis von Evolution wird die Kiemenatmung im Lernziel selbst aber nicht erklärt. Es beschreibt Bau und Ablauf der Atmung, die Frage nach ihrer Entstehung bleibt offen.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Kiemen mit ihren Kiemenblättchen und der dünnen Haut sind ein Bauplan, der den Gasaustausch im Wasser ermöglicht. Das Lernziel verknüpft Bau und Funktion unmittelbar. Die Kiemenblättchen vergrößern die Fläche, an der Sauerstoff aus dem Wasser ins Blut übertritt, und die dünne Haut ermöglicht diesen Übertritt. Lernende bauen die Denkweise auf, von der Gestalt eines Organs auf seine Leistung im Lebensraum zu schließen.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Die Bachforelle nimmt in Wasser gelösten Sauerstoff über die Kiemenblättchen in das Blut auf und gibt Kohlenstoffdioxid ab. Das ist ein Stoffaustausch mit der Umwelt, wie ihn das Konzept für offene Systeme beschreibt: Stoffe werden aufgenommen, genutzt und als Stoffwechselprodukte wieder abgegeben. Lernende erkennen, dass auch ein Lebewesen im Wasser auf den Austausch von Stoffen mit seiner Umwelt angewiesen ist.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '1f1ede45-159c-4bd0-847c-9c17eb3d2319' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Die Kiemenatmung wird als Angepasstheit an den Lebensraum Wasser betrachtet; als Ergebnis von Evolution wird sie im Lernziel selbst nicht erklärt.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Kiemenblättchen mit dünner Haut sind ein Bauplan, der den Gasaustausch im Wasser ermöglicht; das Lernziel verknüpft Bau und Funktion unmittelbar.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Aufnahme von gelöstem Sauerstoff und Abgabe von Kohlenstoffdioxid sind ein Stoffaustausch mit der Umwelt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die kleinen Öffnungen im Laubblatt sind ein Bauelement, das die Aufnahme von Gas ermöglicht. Das Lernziel verbindet damit eine Struktur mit ihrer Aufgabe, dem Eintritt des Kohlenstoffdioxids in das Blatt. Der Bau der Öffnungen und ihre Einbettung in den Blattaufbau werden nicht untersucht. Der Kern liegt daher eher beim Weg des Stoffes als beim Zusammenhang von Bau und Funktion.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Die Aufnahme von Kohlenstoffdioxid aus der Luft ist ein Stoffaustausch mit der Umwelt und liefert den Ausgangsstoff für den Aufbau energiereicher Stoffe. Das Lernziel beschreibt, wie ein Gas aus der Umgebung über die Laubblätter in die Pflanze gelangt, und legt damit den ersten Schritt der Stoffaufnahme offen. Lernende bauen die Vorstellung auf, dass auch Pflanzen offene Systeme sind, die fortlaufend Stoffe aus ihrer Umwelt aufnehmen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '2fc443f5-1ff1-445e-978f-064b80a037ce' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die kleinen Öffnungen im Laubblatt sind ein Bauelement, das die Aufnahme von Gas ermöglicht.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Die Aufnahme von Kohlenstoffdioxid aus der Luft ist ein Stoffaustausch mit der Umwelt und liefert den Ausgangsstoff für den Aufbau energiereicher Stoffe.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel verbindet ausdrücklich den Bau der Wurzel mit ihrer Aufgabe: Wurzelhaare vergrößern die Oberfläche und erleichtern so die Stoffaufnahme. Der Zusammenhang selbst ist Lerninhalt und entspricht dem Prinzip der Oberflächenvergrößerung, bei dem eine größere Grenzfläche den Austausch beschleunigt. Lernende bauen die Denkweise auf, von der Gestalt eines Organs auf seine Leistung zu schließen und umgekehrt.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Wasser und Mineralsalze werden aus dem Boden aufgenommen, das ist ein Stoffaustausch mit der Umwelt. Das Lernziel beschreibt damit, wie die Pflanze die Stoffe bezieht, die sie für ihren Stoffwechsel braucht, und setzt am Beginn der Stoffaufnahme an. Lernende erkennen, dass auch Pflanzen als offene Systeme fortlaufend Stoffe mit ihrer Umgebung austauschen und sich ihre Versorgung aus dem Boden erschließen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '14b20148-da88-4571-9b8c-6841249f3aab' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Lernziel verbindet ausdrücklich den Bau der Wurzel mit ihrer Aufgabe: Wurzelhaare vergrößern die Oberfläche und erleichtern so die Stoffaufnahme.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Wasser und Mineralsalze werden aus dem Boden aufgenommen, das ist ein Stoffaustausch mit der Umwelt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Färbung macht sichtbar, in welchen Bereichen der Sprossachse Wasser aufsteigt; der Aufbau der Leitungsbahnen wird dabei erkennbar. Der Versuch zeigt damit, dass bestimmte Bereiche der Sprossachse für den Wassertransport zuständig sind. Das Lernziel formuliert den Zusammenhang von Bau und Funktion jedoch nicht aus. Im Mittelpunkt steht der Nachweis des Wassertransports.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Der Versuch macht den Transport von Wasser durch die Pflanze sichtbar, also den Weg eines Stoffes im Organismus nach der Aufnahme aus der Umwelt. Das gefärbte Wasser zeigt, dass der aufgenommene Stoff die Sprossachse durchläuft und so zu den übrigen Pflanzenteilen gelangt. Lernende ergänzen ihre Vorstellung von der Stoffaufnahme um den Gedanken, dass Stoffe im Körper weitergeleitet werden.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'c56d1ad9-9f49-40ab-b2a2-359c1a6d07ad' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Färbung macht sichtbar, in welchen Bereichen der Sprossachse Wasser aufsteigt; der Aufbau der Leitungsbahnen wird dabei erkennbar.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Der Versuch macht den Transport von Wasser durch die Pflanze sichtbar, also den Weg eines Stoffes im Organismus nach der Aufnahme aus der Umwelt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Beim Untersuchen mit der Lupe wird der feine Bau der Feder mit ihren Eigenschaften (z. B. leicht, stabil, wärmend) verknüpft. Die Lupe macht Strukturen sichtbar, die Lernende den Leistungen der Feder zuordnen. Das entspricht dem Zusammenhang zwischen Gestalt und Funktion eines Merkmals in seiner Umwelt. Lernende üben, aus dem Bau eines Körperteils auf seine Eigenschaften zu schließen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '69f14dc0-4403-4cee-9711-b1aff3078dca' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Beim Untersuchen mit der Lupe wird der feine Bau der Feder mit ihren Eigenschaften (z. B. leicht, stabil, wärmend) verknüpft.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Körperliche Tätigkeit verbraucht Energie, die der Körper aus der Nahrung gewinnt; das Lernziel verknüpft Energiebedarf und Nahrungsaufnahme. Damit steht der Weg der Energie von der Nahrung bis zur Leistung des Körpers im Vordergrund, also die Umwandlung der in der Nahrung gebundenen Energie in Bewegung und Wärme. Lernende bauen die Denkweise auf, dass jede Tätigkeit Energie braucht und sich die Ernährung am Energieumsatz des Körpers ausrichten lässt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '63cf5098-698e-434d-adba-98e97cf830c7' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Körperliche Tätigkeit verbraucht Energie, die der Körper aus der Nahrung gewinnt; das Lernziel verknüpft Energiebedarf und Nahrungsaufnahme.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug}', $j$[{"begruendung":"Das Lernziel spricht keine Evolution an.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Es wird kein Wachstums- oder Entwicklungsprozess behandelt.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Der Bau von Organen ist hier nicht Thema.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Eine Regelung von Hunger oder Sättigung wird im Lernziel nicht angesprochen.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Mahlzeiten liefern Stoffe und Energie, und der Ernährungskreis hilft, sie in passenden Mengen zusammenzustellen. Das Lernziel berührt damit den Bedarf des Körpers an Stoffen und Energie. Der Bezug ist eher handlungsorientiert als fachlich vertieft. Dem Kern fehlt, was im Körper mit den aufgenommenen Stoffen geschieht.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Informationsweitergabe ist hier nicht Thema.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}]$j$::jsonb), '{basiskonzepte_primaer}', $j$["bk_stoff_energie_umwandlung"]$j$::jsonb), '{basiskonzepte_sekundaer}', $j$[]$j$::jsonb), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '545b6f70-09c2-48eb-90f9-fb09e204b645' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Mahlzeiten liefern Stoffe und Energie, und der Ernährungskreis hilft, sie in passenden Mengen zusammenzustellen; der Bezug ist eher handlungsorientiert als fachlich vertieft.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Beim Herstellen eines Beinmodells wird der Aufbau des Beins mit Knochen und Gelenken nachgebaut und damit seine Funktion der Bewegung verständlich. Im Nachbau wird greifbar, wie Knochen und Gelenke zusammenwirken, damit eine Bewegung entsteht. Lernende entwickeln die Denkweise, die Bauteile eines Körpers nach ihrer Aufgabe zu betrachten und die Funktion aus dem Zusammenspiel der Teile zu erklären.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '1954233c-86a6-4aa8-96b5-bfd0a0b959bf' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Beim Herstellen eines Beinmodells wird der Aufbau des Beins mit Knochen und Gelenken nachgebaut und damit seine Funktion der Bewegung verständlich.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Verhalten der Wassertropfen hängt von der Beschaffenheit der Materialien ab (z. B. glatt, gewachst, Laubblatt); der Versuch verknüpft Oberflächenbau und Verhalten. Lernende vergleichen Oberflächen und sehen, wie deren Eigenschaften das Benetzen oder Abrollen bestimmen. Biologische Strukturen kommen nur mit den Laubblättern vor, ihre Funktion für die Pflanze wird im Lernziel nicht angesprochen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'd72ff117-b16a-417f-96b0-105ed7de0ed3' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Verhalten der Wassertropfen hängt von der Beschaffenheit der Materialien ab (z. B. glatt, gewachst, Laubblatt); der Versuch verknüpft Oberflächenbau und Verhalten.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Ob Wasser eine Oberfläche benetzt, hängt von der Beschaffenheit (wasserliebend, glatt) und den Kräften zwischen den Teilchen ab; das Lernziel verbindet also Aufbau und Verhalten. Die Eigenschaft der Oberfläche entscheidet, ob Adhäsion oder Kohäsion überwiegt. Es bleibt aber eine physikalische Betrachtung ohne Bezug zu Lebewesen, deshalb berührt das Lernziel das Konzept nur am Rande.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '8fbc72bb-502c-4689-b9d4-f0b71dee3162' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Ob Wasser eine Oberfläche benetzt, hängt von der Beschaffenheit (wasserliebend, glatt) und den Kräften zwischen den Teilchen ab; das Lernziel verbindet also Aufbau und Verhalten.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Der Klassenvergleich macht die Vielfalt der Körperbedeckungen sichtbar, Evolutionsprozesse selbst werden aber nicht behandelt. Feuchte Haut, Hornschuppen, Federn und Haare sind Merkmale, die sich zwischen den Wirbeltierklassen unterscheiden, und diese Vielfalt ist ein Ausgangspunkt evolutiver Betrachtungen. Wie die Unterschiede entstanden sind, bleibt im Lernziel offen.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Schleimige Haut, Hornschuppen, Federn und Haare sind unterschiedlich gebaute Körperbedeckungen mit eigenen Aufgaben wie Schutz. Bau und Funktion werden direkt verglichen. Das Lernziel stellt die Klassen gegenüber und fragt nach Gemeinsamkeiten und Unterschieden. Lernende erkennen so, dass verschiedene Bauweisen derselben Körperregion unterschiedliche Leistungen erbringen, und üben, von der Gestalt eines Merkmals auf seine Aufgabe zu schließen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'e873d89d-661c-415a-b21a-e83039b8ff17' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Der Klassenvergleich macht die Vielfalt der Körperbedeckungen sichtbar, Evolutionsprozesse selbst werden aber nicht behandelt.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Schleimige Haut, Hornschuppen, Federn und Haare sind unterschiedlich gebaute Körperbedeckungen mit eigenen Aufgaben wie Schutz. Bau und Funktion werden direkt verglichen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Gleiche Grundbauteile in verschiedener Ausprägung verweisen auf Verwandtschaft und Vielfalt der Wirbeltiere. Das Lernziel führt diesen Gedanken aber nicht aus. Schädel, Wirbelsäule, Gürtel und Gliedmaßenskelett folgen bei allen Klassen demselben Grundmuster, das ist der Ansatz zu Homologie und zur Erhaltung von Bauplänen. Dass dieses Muster auf gemeinsame Vorfahren zurückgeht, wird nicht thematisiert.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Skelettabschnitte sind je nach Fortbewegung unterschiedlich ausgeprägt. Das Lernziel nennt den Zusammenhang von Bau und Funktion ausdrücklich. Schädel, Wirbelsäule, Gürtel sowie Arm- und Beinskelett werden der Fortbewegung der jeweiligen Klasse zugeordnet. Lernende erkennen, dass ein gleicher Grundbau in unterschiedlicher Ausprägung unterschiedliche Leistungen ermöglicht, und betrachten Bau und Funktion in der jeweiligen Umwelt gemeinsam.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '73506d1d-c107-4b7a-932f-65e15d0ca784' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Gleiche Grundbauteile in verschiedener Ausprägung verweisen auf Verwandtschaft und Vielfalt der Wirbeltiere. Das Lernziel führt diesen Gedanken aber nicht aus.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Skelettabschnitte sind je nach Fortbewegung unterschiedlich ausgeprägt. Das Lernziel nennt den Zusammenhang von Bau und Funktion ausdrücklich.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel führt das Verhalten von Wasser an einer Glasfläche auf die Kräfte zwischen den Teilchen zurück, also auf den Aufbau auf Teilchenebene. Die Adhäsion zwischen Wasser und Glas erklärt die Benetzung, damit wird eine Eigenschaft aus dem Bau der Stoffe abgeleitet. Es bleibt eine physikalische Betrachtung ohne Bezug zu Lebewesen oder biologischen Strukturen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '8ce5f422-c16b-4008-a982-81aa38bf62e5' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Lernziel führt das Verhalten von Wasser an einer Glasfläche auf die Kräfte zwischen den Teilchen zurück, also auf den Aufbau auf Teilchenebene.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Nahrung wird aufgenommen, in Bausteine zerlegt und ins Blut aufgenommen. Das ist Stoffumwandlung und Stoffaustausch mit der Umwelt. Das Lernziel verfolgt den Weg der Nahrung vom Aufnehmen über das Zerlegen bis zum Übertritt der Bausteine ins Blut, also eine Folge von Umwandlung und Weiterleitung von Materie. Lernende bauen die Vorstellung auf, dass Lebewesen die Stoffe aus der Nahrung umbauen, bevor der Körper sie nutzen kann.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '5a7909bf-473b-4fe7-9203-4db78d5185e1' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Nahrung wird aufgenommen, in Bausteine zerlegt und ins Blut aufgenommen. Das ist Stoffumwandlung und Stoffaustausch mit der Umwelt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Der Zusammenhang von Bauweise und Stabilität wird an Modellen und an Vorbildern aus der Natur (Knochenquerschnitt, Palmenblatt) untersucht. Das ist Struktur-Funktions-Denken. Lernende vermuten, wie die Bauweise die Stabilität beeinflusst, testen verschiedene Faltkonstruktionen und Materialien und übertragen das Prinzip aus der Natur auf ihr Modell. Sie erfahren, dass eine Eigenschaft wie Stabilität von der Form eines Bauteils abhängt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '456bf7fb-699e-4a6a-85d7-47f6a1695d41' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Der Zusammenhang von Bauweise und Stabilität wird an Modellen und an Vorbildern aus der Natur (Knochenquerschnitt, Palmenblatt) untersucht. Das ist Struktur-Funktions-Denken.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Das Nennen von Stoffen, aus denen Körper bestehen, ist der Einstieg in das Stoffverständnis, auf dem spätere Aussagen zu Stoffeigenschaften und Stoffumwandlungen aufbauen. Das Lernziel bleibt beim Benennen der Stoffe. Der Kern des Konzepts, nämlich dass Stoffe aufgenommen, umgewandelt oder abgegeben werden, kommt hier noch nicht vor.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '50eb3d71-7007-47d9-840e-7034a7bae44f' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Das Nennen von Stoffen, aus denen Körper bestehen, ist der Einstieg in das Stoffverständnis, auf dem spätere Aussagen zu Stoffeigenschaften und Stoffumwandlungen aufbauen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Das Lernziel veranschaulicht mit Kugeln, aus welchen Teilchen Stoffe bestehen und wie sie sich bewegen. Das Kugelmodell legt die Grundlage dafür, Stoffe und ihre Bewegung auf Teilchenebene zu denken, und darauf bauen spätere Überlegungen zu Stoff- und Energieumsätzen auf. Der Kern liegt allerdings in der Physik der Stoffe. Ein Umwandlungsvorgang wird hier nicht beschrieben.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '3ee0353a-78a1-4091-a10b-6f32884c98ef' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Das Kugelmodell legt die Grundlage dafür, Stoffe und ihre Bewegung auf Teilchenebene zu denken. Darauf bauen spätere Überlegungen zu Stoff- und Energieumsätzen auf. Der Kern liegt allerdings in der Physik der Stoffe und nicht bei einem Umwandlungsvorgang.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Anordnung der Teilchen bestimmt die Eigenschaften des Zustands. Das ist ein Struktur-Eigenschaft-Zusammenhang, aber im Bereich der Physik. Fest, flüssig und gasförmig unterscheiden sich durch Anordnung und Bewegung der Teilchen, das entspricht dem Gedanken, dass der Aufbau eines Systems sein Verhalten bestimmt. Biologische Strukturen und ihre Funktion für Lebewesen kommen im Lernziel nicht vor.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Anordnung und Bewegung der Teilchen werden mit den Aggregatzuständen verknüpft. Das ist die Grundlage für Stoff- und Energiebetrachtungen, bleibt aber bei einem physikalischen Vorgang. Lernende gewinnen ein Teilchenbild, auf dem spätere Überlegungen zu Stoffaufnahme, Umwandlung und Abgabe in Lebewesen aufbauen können. Aufnahme, Umwandlung oder Abgabe von Stoffen durch ein Lebewesen kommen im Lernziel selbst aber nicht vor.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '25159cae-ca12-4a91-82c0-54b999128ef8' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Anordnung der Teilchen bestimmt die Eigenschaften des Zustands. Das ist ein Struktur-Eigenschaft-Zusammenhang, aber im Bereich der Physik.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Anordnung und Bewegung der Teilchen werden mit den Aggregatzuständen verknüpft. Das ist die Grundlage für Stoff- und Energiebetrachtungen, bleibt aber bei einem physikalischen Vorgang.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Die Angepasstheit der Bachforelle an das Wasser ist ein Ergebnis der Stammesgeschichte; das Lernziel spricht diese aber nicht an. Körperform, Schuppen und Flossen sind Merkmale, die das Schwimmen erleichtern und im Lauf evolutiver Prozesse entstanden sind. Wie und warum sich solche Merkmale in Populationen verbreitet haben, bleibt im Lernziel offen.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Körperform, Haut, Schuppen, Flossen und Schwimmblase werden ausdrücklich mit Schwimmen und Schweben im Wasser verknüpft. Das ist Bau-Funktions-Denken im Kern. Das Lernziel ordnet jedem Merkmal der Bachforelle eine Leistung in ihrem Lebensraum zu, etwa der Spindelform das Schwimmen und der Schwimmblase das Schweben. Lernende üben, Merkmale eines Tieres über ihre Funktion in der Umwelt zu erklären.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'b7377fcd-5c9a-4483-bac2-31c96f41cac7' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Die Angepasstheit der Bachforelle an das Wasser ist ein Ergebnis der Stammesgeschichte; das Lernziel spricht diese aber nicht an.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Körperform, Haut, Schuppen, Flossen und Schwimmblase werden ausdrücklich mit Schwimmen und Schweben im Wasser verknüpft. Das ist Bau-Funktions-Denken im Kern.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Am Funktionsmodell der Hand wird untersucht, wie Bauteile zusammenwirken und welche Bewegung daraus entsteht. Das ist Struktur-Funktions-Denken. Das Lernziel nennt aber nur das Untersuchen des Modells. Welche Teile der Hand es abbildet und wie Bau und Bewegung zusammenhängen, wird nicht vorgegeben. Der Bezug zum Kern des Konzepts ist daher nur teilweise gegeben.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'a525b23e-8621-48a2-829a-119e3da61661' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Am Funktionsmodell der Hand wird untersucht, wie Bauteile zusammenwirken und welche Bewegung daraus entsteht. Das ist Struktur-Funktions-Denken.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Der von Pflanzen gebildete Sauerstoff wird von vielen Lebewesen für die Atmung gebraucht. Das verbindet Stoffbildung und Stoffaustausch zwischen Lebewesen. Der Sauerstoff, den die Pflanze bildet, dient Tieren und anderen Lebewesen als Ausgangsstoff für die Atmung und geht so von einem Lebewesen auf andere über. Lernende ordnen den Sauerstoff als einen Stoff ein, der von einem Lebewesen gebildet und von anderen gebraucht wird.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'd5574bb9-e827-401d-8b23-804ae25317ed' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Der von Pflanzen gebildete Sauerstoff wird von vielen Lebewesen für die Atmung gebraucht. Das verbindet Stoffbildung und Stoffaustausch zwischen Lebewesen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Das Lernziel beschreibt den gesamten Weg von der Bildung der Eizellen im Eierstock und der Samenzellen im Hoden über die innere Befruchtung und die Entwicklung des Embryos bis zur Geburt und zum erwachsenen Tier. Damit liegen Fortpflanzung und Lebenszyklus im Kern des Basiskonzepts. Lernende bauen die Denkweise auf, dass ein neues Lebewesen aus einer befruchteten Eizelle entsteht und aufeinanderfolgende Entwicklungsphasen durchläuft.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Eierstock und Hoden haben jeweils eine eigene Aufgabe bei der Bildung der Keimzellen, sodass Organ und Leistung hier zusammengehören. Dieser Zusammenhang von Bau und Funktion wird im Lernziel jedoch nur am Rand berührt. Im Mittelpunkt stehen der Ablauf der Fortpflanzung und die Entwicklung bis zum erwachsenen Tier, der Organbau selbst wird nicht genauer betrachtet.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '07e8774d-81cf-4a62-8875-103da637f23c' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Das Lernziel beschreibt den Weg von der Bildung der Keimzellen über die Befruchtung und die Entwicklung des Embryos bis zum erwachsenen Tier. Das ist Fortpflanzung und Individualentwicklung im Kern.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Eierstock und Hoden haben jeweils eine eigene Aufgabe bei der Bildung der Keimzellen, doch der Organbau steht nicht im Mittelpunkt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Die Geschlechtsorgane sind die Voraussetzung der Fortpflanzung, mit der ein neuer Entwicklungszyklus beginnt. Das Lernziel verlangt jedoch nur, Bau und Funktionen der weiblichen und männlichen Organe zu nennen. Auf Entwicklungsvorgänge wie die Entwicklung des Embryos geht es nicht im Einzelnen ein, deshalb bleibt der Bezug zur Individuellen Entwicklung am Rand.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel verlangt, den Bau der weiblichen und männlichen Geschlechtsorgane mit ihren jeweiligen Aufgaben zu verbinden. Damit steht der Zusammenhang zwischen dem Aufbau eines Organs und der Leistung, die es erbringt, unmittelbar im Zentrum. Lernende bauen die Denkweise auf, von der Struktur eines Organs auf seine Aufgabe zu schließen und umgekehrt zu fragen, welcher Bau eine bestimmte Funktion ermöglicht.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '3b6532c6-b5a6-4a4d-939b-d80ff08821cc' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Die Geschlechtsorgane sind Voraussetzung der Fortpflanzung; das Lernziel nennt jedoch nur Bau und Funktion und geht auf Entwicklungsvorgänge nicht im Einzelnen ein.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Lernziel verlangt, den Bau der Geschlechtsorgane mit ihren jeweiligen Aufgaben zu verbinden, also unmittelbar den Zusammenhang von Bau und Funktion.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Mit der Lupe werden Form und Anordnung der Haken und Schlaufen an Haft- und Klettband erkennbar, und genau diese Gestalt erklärt später das Haften. Das Betrachten liefert damit die Beobachtungsgrundlage für den Zusammenhang von Struktur und Funktion. Die Deutung dieses Zusammenhangs folgt jedoch erst in späteren Schritten und gehört noch nicht zu diesem Lernziel.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '5e98865a-63ba-4dae-b439-c37aa00786a2' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Mit der Lupe werden Form und Anordnung von Haken und Schlaufen erkennbar, die das Haften erklären; die Deutung des Zusammenhangs folgt erst in späteren Schritten.$t$;
