UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die biegsamen Widerhaken der Klettfrucht erklären, warum sie am Fell von Tieren haftet und sich dennoch immer wieder lösen lässt, ohne abzubrechen. Das Lernziel verknüpft die Gestalt der Haken damit unmittelbar mit ihrer Wirkung, wie es das Unterkonzept der morphologischen und anatomischen Angepasstheit beschreibt. Lernende bauen die Denkweise auf, aus der Form eines Merkmals auf seine Leistung zu schließen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'cb857393-3870-4356-a3ba-f41dce260ca2' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die biegsamen Widerhaken der Klettfrucht erklären, warum sie am Fell haftet und sich wieder lösen lässt: Das Lernziel verknüpft Form und Wirkung unmittelbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Klettfrucht und Klettverschluss haben das Prinzip gemeinsam, dass biegsame Haken sich verhaken und wieder lösen lassen. Der Vergleich zeigt, dass der Zusammenhang von Form und Wirkung bei einem Lebewesen und bei einem technischen Gegenstand derselbe ist, und trifft damit den Kern des Basiskonzepts. Lernende bauen die Denkweise auf, dass gleiche Strukturen gleiche Leistungen ermöglichen, in der Natur wie in der Technik.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'aa1d63e2-75a1-44cf-924e-8d26a29b4ae4' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Gemeinsam ist Klettfrucht und Klettverschluss das Prinzip verhakender, biegsamer Haken; der Vergleich macht den Zusammenhang von Form und Wirkung in zwei Bereichen sichtbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das erkannte Prinzip der biegsamen Haken wird auf Klettverschlüsse für Schuhe und Jacken angewandt, die sich leicht und beliebig häufig öffnen und schließen lassen. Dabei wird der Zusammenhang von Form und Funktion genutzt. Das Erkennen und Erklären dieses Zusammenhangs gehört zu einem früheren Schritt, hier steht die Anwendung auf technische Objekte im Vordergrund.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'a1757959-edb2-499a-ab6e-6ed187d9ec7d' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das erkannte Prinzip der biegsamen Haken wird auf neue Anwendungen wie Schuhe und Jacken angewandt; dabei steht die Nutzung des Zusammenhangs von Form und Funktion im Vordergrund.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Im Funktionsmodell aus einem Kunststoffstreifen mit flexiblen Widerhäkchen und einem Streifen mit Schlaufen wird geprüft, wie Form und Material das Haften bestimmen, unter anderem bei Zugbelastung. Damit kommt der Zusammenhang von Struktur und Funktion beim Erproben vor. Der Schwerpunkt liegt auf dem Bauen und Prüfen der technischen Umsetzbarkeit. Das Erklären des Zusammenhangs steht nicht im Mittelpunkt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '14ebf98b-92a5-416e-b9a9-3ec00458199a' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Im Funktionsmodell aus Streifen mit Widerhäkchen und Schlaufen wird geprüft, wie Form und Material das Haften bestimmen; der Schwerpunkt liegt auf dem Bauen und Prüfen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug}', $j$[{"begruendung":"Dieses physikalische Lernziel hat keinen Bezug zur Evolution.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Entwicklungsprozesse von Lebewesen kommen in diesem Lernziel nicht vor.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Lernziel selbst spricht dieses Basiskonzept nicht an.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Steuerungs- oder Regelungsvorgänge sind hier nicht Gegenstand.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Lernziel selbst spricht dieses Basiskonzept nicht an.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Informationsübertragung oder Kommunikation spielt hier keine Rolle.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}]$j$::jsonb), '{basiskonzepte_primaer}', $j$[]$j$::jsonb), '{basiskonzepte_sekundaer}', $j$[]$j$::jsonb), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'ab8e80c2-006e-4ad2-af31-235822cc64cc' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Eigenschaft Abperlen wird aus dem Verhalten der Teilchen und der Oberfläche begründet, ähnlich wie in der Biologie Eigenschaften aus dem Aufbau erklärt werden.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Bienenwaben, Knochen und Palmenblätter erreichen hohe Stabilität bei geringem Materialeinsatz durch ihre Bauweise, zum Beispiel durch Faltung. Das Lernziel verknüpft die Struktur dieser Vorbilder damit unmittelbar mit ihrer Wirkung, wie es das Unterkonzept der morphologischen und anatomischen Angepasstheit beschreibt. Lernende bauen die Denkweise auf, die Festigkeit eines Körpers auch aus seiner Form zu erklären.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'e3b1da59-af4b-4b86-a614-2a7798443afb' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Bienenwaben, Knochen und Palmenblätter erreichen Stabilität bei wenig Material durch ihre Bauweise, zum Beispiel Faltung; das Lernziel verknüpft Struktur und Wirkung unmittelbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Gemeinsam ist biologischem Vorbild und technischer Umsetzung das Prinzip hoher Stabilität bei geringem Materialeinsatz durch die Form. Der Vergleich macht sichtbar, dass der Zusammenhang von Struktur und Wirkung in der Natur und in der Technik derselbe ist, und trifft damit den Kern des Basiskonzepts. Lernende bauen die Denkweise auf, ein Strukturprinzip in verschiedenen Bereichen wiederzuerkennen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'e6b8d530-7d2f-4d05-a019-7ab2e219fc7b' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Gemeinsam ist Vorbild und Technik das Prinzip hoher Stabilität bei geringem Materialeinsatz durch die Form; der Vergleich macht den Zusammenhang von Struktur und Wirkung sichtbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das erkannte Prinzip stabiler, leichter Strukturen wird auf Brücken, Dächer und Verpackungsmaterialien übertragen. Dabei wird der Zusammenhang von Struktur und Festigkeit für neue technische Objekte genutzt. Das Erkennen und Erklären dieses Zusammenhangs am Vorbild gehört zu einem früheren Schritt, hier steht die Anwendung auf technische Objekte im Vordergrund.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '80ed1c35-4ee9-4faf-9980-5940dbcde75f' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das erkannte Prinzip stabiler, leichter Strukturen wird auf Brücken, Dächer und Verpackungen übertragen; dabei steht die Nutzung des Zusammenhangs von Struktur und Festigkeit im Vordergrund.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Beim Prüfen des Zusammenhangs zwischen Wölb- und Faltungsstrukturen und der Festigkeit unter Druckbelastung wird unmittelbar untersucht, wie die Struktur die Belastbarkeit bestimmt. Die selbstversteifende Wirkung am Funktionsmodell macht den Zusammenhang von Bau und Leistung überprüfbar. Lernende bauen die Denkweise auf, eine Vermutung über die Wirkung einer Form am Modell zu belegen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '8711c53e-c1ea-4d58-a5c0-8aa6aa8d0fd6' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Beim Prüfen des Zusammenhangs zwischen Wölb- und Faltungsstrukturen und Festigkeit wird unmittelbar untersucht, wie die Struktur die Belastbarkeit bestimmt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Stärke und Traubenzucker sind Nährstoffe, die Lebewesen aufnehmen und umwandeln. Ihre Löslichkeit ist eine Stoffeigenschaft, die später für das Verständnis von Verdauung und Stofftransport wichtig wird. Das Lernziel nennt jedoch nur das Experiment zur Löslichkeit. Aufnahme und Umwandlung der Stoffe im Organismus bleiben hier unberührt, der Bezug zum Basiskonzept ist vorbereitend.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '88744da7-3dd5-418d-841f-813fb89c2fee' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Stärke und Traubenzucker sind Nährstoffe; ihre Löslichkeit ist eine Stoffeigenschaft, die später für das Verständnis von Verdauung und Stofftransport wichtig wird, auch wenn das Lernziel nur das Experiment nennt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Wachsnoppen der Blattoberfläche erklären das Abperlen der Wassertropfen, die dabei Schmutzteilchen mitnehmen. Das Lernziel verknüpft die Oberflächenstruktur des Laubblatts damit unmittelbar mit dieser Wirkung, wie es das Unterkonzept der morphologischen und anatomischen Angepasstheit beschreibt. Lernende bauen die Denkweise auf, eine Eigenschaft wie die Selbstreinigung aus der Feinstruktur einer Oberfläche zu erklären.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'd9694d58-99cb-4781-90dd-54a539097888' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Wachsnoppen der Blattoberfläche erklären das Abperlen und die Selbstreinigung; das Lernziel verknüpft Oberflächenstruktur und Wirkung unmittelbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Gemeinsam ist Laubblatt und technischer Oberfläche das Prinzip der Noppenstruktur, die das Abperlen bewirkt. Der Vergleich macht sichtbar, dass der Zusammenhang von Struktur und Wirkung in der Natur und in der Technik derselbe ist, und trifft damit den Kern des Basiskonzepts. Lernende bauen die Denkweise auf, aus der Beschaffenheit einer Oberfläche auf ihre Leistung zu schließen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'f2fad735-635f-4080-9ddb-c1545249f8d8' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Gemeinsam ist Blatt und technischer Oberfläche das Prinzip der Noppenstruktur, die das Abperlen bewirkt; der Vergleich macht den Zusammenhang von Struktur und Wirkung sichtbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das erkannte Prinzip der genoppten Oberfläche wird auf Autolacke, wasserabweisende Zeltplanen, Wetterjacken und Schuhe übertragen. Dabei wird der Zusammenhang von Struktur und Wirkung genutzt. Das Erkennen und Erklären dieses Zusammenhangs am Vorbild gehört zu einem früheren Schritt, hier steht die Anwendung auf technische Objekte im Vordergrund.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'da155c13-2e1a-4a13-8278-7ad19b2119b8' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das erkannte Prinzip der genoppten Oberfläche wird auf Autolacke, Zeltplanen, Wetterjacken und Schuhe übertragen; dabei steht die Nutzung des Zusammenhangs von Struktur und Wirkung im Vordergrund.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Im Funktionsmodell wird das Verhalten von Wasser auf einer genoppten, wasserabweisenden Oberfläche geprüft, und verschiedene Materialien mit entsprechenden Oberflächen werden verglichen. Dabei zeigt sich, wie die Oberflächenstruktur die Wirkung bestimmt. Der Schwerpunkt liegt auf dem Bauen und Vergleichen der Materialien. Das Erklären des Zusammenhangs von Struktur und Wirkung steht hier nicht im Mittelpunkt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '1d042b21-bff9-4caf-a2d2-5aaf4ce765cd' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Im Funktionsmodell wird das Verhalten von Wasser auf einer genoppten, wasserabweisenden Oberfläche geprüft; der Schwerpunkt liegt auf dem Bauen und Vergleichen verschiedener Materialien.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Elektrische Leitfähigkeit, Löslichkeit, Wärmeleitfähigkeit sowie Schmelz- und Siedetemperatur kennzeichnen Reinstoffe auf der Stoffebene. Schmelzen und Sieden sind Aggregatzustandsänderungen, die Wärmezufuhr brauchen, und die Wärmeleitfähigkeit betrifft die Weitergabe von Energie. Damit berührt das Lernziel Stoff- und Energiezustände. Die Umwandlung von Stoffen im Stoffwechsel von Lebewesen kommt im Lernziel nicht vor.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'd58ccc23-012d-4526-9db5-de8e7950537e' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Leitfähigkeit, Löslichkeit, Wärmeleitfähigkeit sowie Schmelz- und Siedetemperatur beschreiben Stoffe auf der Stoffebene und berühren Aggregatzustandsänderungen und Wärmeübertragung, also Stoff- und Energiezustände.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Beim Variieren der Maschengröße erfahren Lernende, dass die Bauform eines Netzes bestimmt, wie viel Wasser es aus dem Nebel auffangen kann. Das ist der Kern des Konzepts: Eine Struktur, hier die Maschengröße, hängt mit ihrer Funktion zusammen. Weil das Modell verändert und auf Effizienz untersucht wird, bauen Lernende die Denkweise auf, vom Bau auf die Leistung zu schließen, wie in der Bionik nach biologischem Vorbild.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Das Auffangen von Wasser aus Nebel betrifft Kondensation und Wassertransport, also Stoffbewegung, die beim Untersuchen der Effizienz gemessen und verglichen wird. Damit berührt das Lernziel den Austausch von Stoffen zwischen Luft und Modell. Der Stoffwechsel von Lebewesen und die Umwandlung von Energie spielen beim Modellbau keine Rolle, sodass das Konzept nur am Rand getroffen wird.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '54238a78-3402-405d-b942-cefd5fae5f00' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Beim Variieren der Maschengröße erfahren Lernende, dass die Bauform eines Netzes seine Funktion (Wasser aus Nebel auffangen) bestimmt, ein Struktur-Funktion-Zusammenhang nach biologischem Vorbild.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Das Auffangen von Wasser aus Nebel betrifft Kondensation und Wassertransport, also Stoffbewegung, die gemessen und verglichen wird.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Das Modell zum Verdauungsvorgang macht sichtbar, dass Stärke bei der Verdauung in kleinere Bausteine zerlegt wird. Stärke wird damit in andere Stoffe umgewandelt. Das ist Stoffumwandlung im Sinne des Basiskonzepts, nach dem Lebewesen Stoffe aufnehmen und umwandeln. Lernende bauen die Denkweise auf, Ernährung als Umbau von Nahrungsstoffen im Körper zu verstehen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '04a1a1f6-e974-49be-be17-6d6b280abe6a' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Das Modell macht sichtbar, dass Stärke bei der Verdauung in kleinere Bausteine zerlegt wird, also in andere Stoffe umgewandelt wird, die der Körper aufnehmen kann.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$In den Modellversuchen zeigt sich, dass die Beschaffenheit und Form einer Oberfläche bestimmt, wie Wasser darauf reagiert: wasserliebend oder wasserabweisend, glatt oder genoppt, gewachst oder unbehandelt. Das ist ein Zusammenhang von Struktur und Funktion, wie ihn das Basiskonzept beschreibt. Lernende erfahren, dass sich aus dem Bau einer Oberfläche ihr Verhalten ableiten lässt. Diese Denkweise wird später am biologischen Vorbild genutzt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '282630d4-114a-433b-afdc-0c30dd452e9c' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Versuche zeigen, dass die Beschaffenheit und Form einer Oberfläche (glatt, genoppt, gewachst) bestimmt, wie Wasser darauf reagiert, ein Struktur-Funktion-Zusammenhang, der später am biologischen Vorbild genutzt wird.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Die Flügeldecken lassen sich als Angepasstheit des Käfers an seinen trockenen Lebensraum verstehen, also als Merkmal, das sich über viele Generationen in der Population durchgesetzt hat, weil seine Träger in dieser Umwelt häufiger überlebten und sich fortpflanzten. Das Lernziel behandelt den Käfer aber nur als biologisches Vorbild. Wie die Angepasstheit über Variation und Selektion in Populationen entstanden ist, wird nicht angesprochen.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Höcker und Rillen auf den Flügeldecken sind Bauelemente, deren Form und Oberflächeneigenschaft das Lernziel direkt mit einer Funktion verknüpft: Höcker mit vergrößerter Oberfläche lassen Wasserdampf kondensieren, Rillen leiten die Tröpfchen zum Mund. Das entspricht dem Zusammenhang von Gestalt und Leistung einer Struktur. Lernende bauen die Denkweise auf, aus dem Bau eines Merkmals auf seine Funktion zu schließen.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Der Käfer gewinnt Wasser, indem Wasserdampf aus der Luft an den Flügeldecken kondensiert und zum Mund geleitet wird. Das ist eine Stoffaufnahme aus der Umgebung und berührt damit den Stoffaustausch mit der Umwelt. Was der Käfer anschließend mit dem Wasser im Stoffwechsel macht, und welche Energie dafür nötig ist, bleibt im Lernziel offen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'a2ca11ef-daba-413e-8a9d-1da188ccb54e' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Die Flügeldecken lassen sich als Angepasstheit des Käfers an seinen trockenen Lebensraum verstehen, die das Lernziel aber nur als biologisches Vorbild behandelt.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Höcker und Rillen auf den Flügeldecken sind Bauelemente, deren Form und Oberflächeneigenschaft direkt mit der Funktion (Kondensieren und Transportieren von Wasser) verknüpft wird.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Der Käfer gewinnt Wasser durch Kondensation von Wasserdampf und leitet es zum Mund, also eine Stoffaufnahme aus der Umgebung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das am Käfer erkannte Prinzip, eine Fläche zum Kondensieren und Rillen zum Weiterleiten, wird in Netze und Auffangvorrichtungen für Nebelkollektoren übersetzt. Lernende übertragen damit einen Zusammenhang von Bau und Leistung vom Lebewesen auf ein technisches Objekt und nutzen Struktur und Funktion für einen Zweck. Sie bauen die Denkweise auf, dass sich eine Funktion über ihren Bau beschreiben und auf anderes Material übertragen lässt.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Nebelkollektoren gewinnen Trinkwasser durch Kondensation und Auffangen, also durch einen technischen Stofftransport aus der Luft. Das berührt den Austausch von Stoffen mit der Umgebung. Da es um ein technisches Objekt geht, fehlen der Bezug zu lebenden Systemen und die Umwandlung von Stoffen und Energie im Stoffwechsel, die den Kern des Basiskonzepts bilden.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '13580540-d296-4931-9f0b-eff88ac85d99' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das am Käfer erkannte Prinzip (Fläche zum Kondensieren, Rillen zum Weiterleiten) wird in Netze und Auffangvorrichtungen übersetzt, also Struktur und Funktion für einen Zweck genutzt.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Nebelkollektoren gewinnen Trinkwasser durch Kondensation und Auffangen, ein technischer Stofftransport aus der Luft.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Im Funktionsmodell wird geprüft, ob die Gestaltung von Netz und Ablaufrinne die gewünschte Funktion erfüllt, also Wasserdampf zu kondensieren und das Wasser aufzufangen. Die Menge des gewonnenen Wassers wird an verschiedenen Netzen verglichen. So prüfen Lernende, ob der vermutete Zusammenhang von Bau und Wirkung trägt, und bauen die Denkweise auf, Annahmen über Struktur und Funktion am Modell zu testen.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Kondensation von Wasserdampf, Ablaufen und Auffangen sowie das Messen der gewonnenen Wassermenge betreffen Stoffbewegung und Stoffgewinnung aus der Luft. Das Lernziel berührt damit den Stoffaustausch, bleibt aber bei einem technischen Funktionsmodell. Die Umwandlung von Stoffen und Energie in Lebewesen wird nicht thematisiert.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'c58acff7-5dcf-44d9-988f-cfd9d8da4b37' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Im Funktionsmodell wird geprüft, ob die Gestaltung von Netz und Rinne die gewünschte Funktion erfüllt, also ob der Zusammenhang von Bau und Wirkung trägt.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Kondensation von Wasserdampf, Ablaufen und Auffangen sowie das Messen der gewonnenen Wassermenge betreffen Stoffbewegung und Stoffgewinnung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Ob ein Material Flüssigkeit aufsaugt oder dies verhindert, hängt von seiner Struktur ab. Beim Schwamm ermöglichen feine Poren die Kapillarität, bei gebranntem Ton im Bauwesen wird sie verhindert. Das Lernziel verlangt, diesen Zusammenhang von Bau und Wirkung zu begründen. Lernende bauen die Denkweise auf, Eigenschaften und Leistungen eines Materials aus seinem inneren Aufbau abzuleiten.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Das Aufsteigen und Aufnehmen von Flüssigkeit in feinen Hohlräumen ist ein Stofftransport, der durch Kräfte zwischen den Teilchen erklärt wird. Das Lernziel berührt damit die Bewegung eines Stoffes, die hier physikalisch begründet wird. Die Aufnahme, Umwandlung und Abgabe von Stoffen durch Lebewesen und ihr Energieumsatz stehen im Lernziel nicht im Vordergrund.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '6bbabbc1-9a80-4577-912d-3aacc6dc9270' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Ob ein Material Flüssigkeit aufsaugt oder nicht, hängt von seiner Struktur (feine Poren, gebrannter Ton) ab, ein Zusammenhang von Bau und Wirkung.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Das Aufsteigen und Aufnehmen von Flüssigkeit in feinen Hohlräumen ist ein Stofftransport, der durch Kräfte zwischen den Teilchen erklärt wird.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Oberflächenspannung lässt sich auf die Anordnung und Anziehung der Wasserteilchen zurückführen. Das ist ein erster Hinweis darauf, dass der Aufbau eines Stoffes seine Eigenschaft bestimmt. Im Experiment geht es um eine Stoffeigenschaft. Biologische Strukturen und deren Funktion, etwa von Organen oder Körperbau, kommen im Lernziel nicht vor, daher wird der Kern des Konzepts nur angedeutet.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Der zugesetzte Stoff Spülmittel verändert eine Stoffeigenschaft des Wassers, die Oberflächenspannung, und der Tropfen auf der Glasplatte zeigt diese Wirkung sichtbar. Das Experiment macht sie auf der Ebene der Teilchen erklärbar und berührt damit die Stoffebene. Eine Stoffumwandlung oder der Energieumsatz von Lebewesen tritt hier nicht auf.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'b7438a8f-8bd4-408e-81a7-cabbc947ee0d' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Oberflächenspannung lässt sich auf die Anordnung und Anziehung der Wasserteilchen zurückführen, ein erster Hinweis auf den Zusammenhang von Aufbau und Eigenschaft.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Ein zugesetzter Stoff (Spülmittel) verändert eine Stoffeigenschaft des Wassers, hier die Oberflächenspannung, und das Experiment macht diese Wirkung auf der Ebene der Teilchen erklärbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Menstruation und Pollution sind Zeichen der einsetzenden Geschlechtsreife. Sie zeigen, dass sich der Mensch vom Kind zum fortpflanzungsfähigen Menschen entwickelt, und gehören damit zur Pubertät als dem Entwicklungsabschnitt, an dessen Ende die Fortpflanzungsfähigkeit steht. Lernende bauen die Denkweise auf, den eigenen Körper als Ergebnis einer fortlaufenden Entwicklung im Lebenslauf zu verstehen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'e2d2e94d-eb50-4fa2-9458-fd7bc95528b5' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Menstruation und Pollution sind Zeichen der einsetzenden Geschlechtsreife und damit der Entwicklung vom Kind zum fortpflanzungsfähigen Menschen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug}', $j$[{"begruendung":"Vielfalt wird hier gesellschaftlich und persönlich behandelt. Das Lernziel hat keinen Evolutionsbezug.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Lernziel gehört zur Pubertät, in der Jugendliche sich auch in ihrer Identität und Orientierung unterscheiden. Im Mittelpunkt steht die Akzeptanz unterschiedlicher sexueller Orientierungen und Identitäten, also ein Aspekt der Entwicklung im Lebenslauf. Dem Kern fehlt der biologische Entwicklungsvorgang selbst, etwa die körperliche Reifung. Das Unterkonzept Pubertät und Geschlechtsreife wird nur am Rand berührt.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Pubertät und Geschlechtsreife"],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[{"value":"Pubertät und Geschlechtsreife","taxonomyElementId":"6173fdb3-eb7b-4f23-a49d-586b760416f3"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Bau und Funktion von Organen sind nicht Gegenstand dieses Lernziels.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Steuerung oder Regelung wird hier nicht behandelt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoff- oder Energieumwandlung hat keinen Bezug zum Lernziel.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Informationsverarbeitung im biologischen Sinn ist hier nicht Thema.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}]$j$::jsonb), '{basiskonzepte_primaer}', $j$["bk_individuelle_entwicklung"]$j$::jsonb), '{basiskonzepte_sekundaer}', $j$[]$j$::jsonb), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '1f911a33-2a20-405d-b355-285a6728cd33' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Das Lernziel gehört in die Entwicklung in der Pubertät, in der Jugendliche auch ihre eigene Identität und ihre Orientierung entdecken, und stellt die Akzeptanz von Vielfalt in den Mittelpunkt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Veränderungen des Körperbaus und die Ausbildung sekundärer Geschlechtsmerkmale sind der sichtbare Teil der körperlichen Reifung in der Pubertät. Sie verbinden Wachstum, das auf Körperregionen ungleichmäßig verteilt sein kann, mit der Reifung zur Geschlechtsreife. Lernende bauen die Denkweise auf, dass sich ein Mensch über die Lebensphasen hinweg fortlaufend verändert und die Pubertät ein Abschnitt davon ist.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'f287965b-e890-4e65-971e-2227a65b20da' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Veränderungen des Körperbaus und die Ausbildung sekundärer Geschlechtsmerkmale sind der sichtbare Teil der körperlichen Reifung in der Pubertät.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Beim Betrachten des Querschnitts mit der Lupe erkennen Lernende die Leitgefäße als besondere Bauelemente der Sprossachse. Anordnung und Form der Leitgefäße passen zu ihrer Funktion, Wasser und gelöste Stoffe zu transportieren. So üben Lernende, vom beobachtbaren Bau auf die Leistung eines Organs zu schließen, und verbinden Strukturen kriteriengeleitet mit Funktionen.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Leitgefäße transportieren Wasser und gelöste Stoffe durch die Pflanze, das Lernziel berührt also den Stofftransport. Beobachtet wird jedoch der Bau, die Stoffbewegung selbst wird vorausgesetzt. Die Umwandlung von Stoffen und Energie in der Pflanze ist im Lernziel nicht angesprochen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '39b76409-4e7c-42bf-bc64-d8abc32ae62d' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Beim Betrachten des Querschnitts werden Leitgefäße als besondere Bauelemente erkannt, deren Anordnung und Form zur Funktion des Transports passt.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Leitgefäße transportieren Wasser und gelöste Stoffe durch die Pflanze, das Lernziel berührt also den Stofftransport.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Luft als Gemisch aus Stickstoff, Sauerstoff und Kohlenstoffdioxid mit dem Kugelteilchenmodell zu erklären, ist Arbeit auf der Stoffebene. Sie legt die Grundlage für spätere Themen wie Atmung und Stoffaustausch, bei denen Lebewesen Gase aus der Umgebung aufnehmen und abgeben. Im Lernziel selbst geht es nur um die Zusammensetzung eines Gemischs ohne Umwandlung der Stoffe und ohne Energieumsatz.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '86364d9d-91d8-490c-8e48-7236088b5832' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Luft als Gemisch aus Stickstoff, Sauerstoff und Kohlenstoffdioxid zu erklären, ist Arbeit auf der Stoffebene und legt die Grundlage für spätere Themen wie Atmung und Stoffaustausch.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Eine Ethanol-Wasser-Lösung zeigt als Stoffgemisch, dass sich zwei Reinstoffe vermischen können, ohne dass ein neuer Stoff entsteht. Das Kugelteilchenmodell erklärt diese Verteilung der Teilchen. Das Lernziel arbeitet damit auf der Stoffebene und liefert eine Grundlage für spätere Betrachtungen von Stoffen in Lebewesen. Eine Stoffumwandlung, die zum Kern des Basiskonzepts gehört, findet hier nicht statt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '79baf6b7-737c-459a-982c-ad269707dd15' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Eine Ethanol-Wasser-Lösung zeigt als Stoffgemisch, dass sich zwei Reinstoffe vermischen können, ohne dass ein neuer Stoff entsteht, und das Teilchenmodell erklärt diese Verteilung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Die Lernenden erklären mit dem Kugelteilchenmodell, wie sich Zucker und Wasser als zwei Reinstoffe zu einem Gemisch verbinden. Das ist die stoffliche Grundlage für spätere Betrachtungen von Lösungsvorgängen in Lebewesen, etwa wenn gelöste Stoffe aufgenommen und transportiert werden. Es ist allerdings ein physikalischer Vorgang ohne Stoffumwandlung, sodass der Kern des Konzepts nur vorbereitet wird.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'a868f6c8-9909-4503-b35f-76cd38607997' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Die Lernenden erklären, wie sich Zucker und Wasser als zwei Reinstoffe zu einem Gemisch verbinden. Das ist die stoffliche Grundlage für spätere Betrachtungen von Lösungsvorgängen in Lebewesen. Es ist allerdings ein physikalischer Vorgang ohne Stoffumwandlung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Leistung der Sprossachse, Wasser und gelöste Mineralsalze zu den Laubblättern zu transportieren, wird mit ihrem Bau aus dünnen Röhren und der Kapillarität erklärt. Das ist ein unmittelbares Beispiel für den Zusammenhang von innerem Bau und Funktion. Lernende bauen die Denkweise auf, aus dem Bau eines Pflanzenorgans zu begründen, warum es seine Leistung erbringen kann.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Wasser, Mineralsalze und Kohlenstoffdioxid gelangen aus der Umwelt in die Pflanze und zu den Laubblättern. Das Lernziel berührt damit den Stoffaustausch mit der Umwelt, der für offene biologische Systeme kennzeichnend ist. Er steht hier jedoch im Hintergrund, weil der Weg und die Erklärung des Transports in der Sprossachse im Mittelpunkt stehen. Eine Umwandlung der Stoffe kommt nicht vor.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '7c671821-9a90-46ce-b5e9-87a82741533e' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Leistung der Sprossachse, Wasser zu transportieren, wird mit ihrem Bau aus dünnen Röhren und der Kapillarität erklärt. Das ist ein unmittelbares Beispiel für den Zusammenhang von Struktur und Funktion.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Wasser, Mineralsalze und Kohlenstoffdioxid gelangen aus der Umwelt in die Pflanze und zu den Laubblättern. Der Stoffaustausch mit der Umwelt steht hier im Hintergrund.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Aus Traubenzucker bildet die Pflanze weitere Stoffe wie Stärke, Fette und Farbstoffe. Das ist eine Stoffumwandlung im Stoffwechsel der Pflanze und gehört zum Kern des Basiskonzepts, nach dem Lebewesen Stoffe aufnehmen und umwandeln. Die Denkweise dahinter: Pflanzen bauen aus einem Grundstoff viele verschiedene Stoffe auf, die sie für Speicherung, Aufbau und Färbung nutzen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'a0955d8a-2c95-491d-9a31-7ece1aad164c' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Aus Traubenzucker bildet die Pflanze weitere Stoffe wie Stärke, Fette und Farbstoffe. Das ist eine Stoffumwandlung im Stoffwechsel der Pflanze und gehört zum Kern des Basiskonzepts.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Kohlenstoffdioxid und Wasser werden im Chlorophyll der Laubblätter mithilfe von Lichtenergie zu Traubenzucker und Sauerstoff umgewandelt. Damit stehen Stoffumwandlung und Energieumwandlung unmittelbar im Kern: Aus Ausgangsstoffen entstehen neue Stoffe, und die aufgenommene Lichtenergie wird in eine andere Form überführt. Lernende bauen die Denkweise auf, Lebensprozesse als Umwandlung von Stoffen unter Energieaufnahme zu beschreiben.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '02b1cfae-8be3-4c33-8f3a-316c84f8f6ea' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Kohlenstoffdioxid und Wasser werden mithilfe von Lichtenergie zu Traubenzucker und Sauerstoff umgewandelt. Stoff- und Energieumwandlung stehen hier unmittelbar im Kern.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Zu- oder Abfuhr von Wärme verändert den Zustand des Wassers, das schmilzt, verdampft, kondensiert oder gefriert. Damit verbindet das Lernziel Stoff und Energie, denn Wärme wird aufgenommen oder abgegeben. Es bleibt aber bei einem physikalischen Vorgang ohne neuen Stoff. Der Austausch lebender Systeme mit der Umwelt und die chemische Stoffumwandlung, die den Kern des Basiskonzepts bilden, kommen nicht vor.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'b89c1f9d-f052-4ca0-bb70-17e8bb888293' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Zu- oder Abfuhr von Wärme verändert den Zustand des Wassers. Damit verbindet das Lernziel Stoff und Energie, bleibt aber bei einem physikalischen Vorgang ohne neuen Stoff.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Bei der Verbrennung entstehen unter Beteiligung von Sauerstoff neue Stoffe mit anderen Eigenschaften. Das ist die Stoffumwandlung in ihrer einfachsten, sichtbaren Form: Die Ausgangsstoffe werden verbraucht, und die entstandenen Stoffe unterscheiden sich in ihren Eigenschaften deutlich von ihnen. Das Lernziel liegt damit im Kern des Basiskonzepts. Lernende erkennen an veränderten Eigenschaften, dass ein Stoff umgewandelt wurde, und beschreiben Stoffveränderungen als Bildung neuer Stoffe.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '5cd154bd-b681-4f91-ae26-bf00c95d6b8c' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Bei der Verbrennung entstehen unter Beteiligung von Sauerstoff neue Stoffe mit anderen Eigenschaften. Das ist die Stoffumwandlung in ihrer einfachsten, sichtbaren Form.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Bei der Verbrennung wird die in den Stoffen gespeicherte chemische Energie in Wärme und Licht umgewandelt. Das Lernziel beschreibt damit eine Energieumwandlung, bei der Energie von einer Form in andere Formen übergeht und als Wärme und Licht wahrnehmbar wird. Die Energieumwandlung steht unmittelbar im Kern des Lernziels. Lernende bauen die Vorstellung auf, dass Stoffe Energie gespeichert haben und Reaktionen diese Energie in andere Formen überführen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'f6fab0ae-8172-46e7-bf16-b0eb68d6b169' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Chemische Energie der Stoffe wird in Wärme und Licht umgewandelt. Die Energieumwandlung steht unmittelbar im Kern des Lernziels.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Wie Wassertropfen auf einem Laubblatt aussehen, hängt von der Oberflächenbeschaffenheit des Blattes ab. Beim Vergleich etwa von Kohlrabi, Gartenkresse und Erdbeere beobachten die Lernenden unmittelbar, wie die Beschaffenheit einer Blattoberfläche ihr Verhalten gegenüber Wasser bestimmt. Das liegt im Kern des Basiskonzepts. Lernende bauen die Denkweise auf, vom sichtbaren Bau eines Pflanzenorgans auf seine Leistung zu schließen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '5323c8d8-8212-4c77-8f77-38d5cad719bf' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Wie Wassertropfen auf einem Laubblatt aussehen, hängt von der Oberflächenbeschaffenheit des Blattes ab. Die Lernenden beobachten damit unmittelbar einen Zusammenhang zwischen Struktur und Leistung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Beim Bestimmen des Volumens fester Körper durch Eintauchen in Wasser geht es um Stoffe und ihre messbaren Eigenschaften. Der Bezug zum Basiskonzept ist nur am Rand gegeben. Es findet keine Stoffumwandlung statt, denn die Körper und das Wasser bleiben unverändert. Dem Kern fehlt damit die Bildung neuer Stoffe oder die Umwandlung von Energie.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '7cec53e6-f253-42db-98bf-4b44dcdf357c' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Die Messung betrifft Stoffe und ihre Eigenschaften, jedoch ohne Umwandlung. Der Bezug zum Basiskonzept ist nur am Rand gegeben.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Der Nachweis, dass Wasser über die Wurzeln aufgenommen wird, verweist auf die Funktion des Organs Wurzel für die Pflanze. Das passt zum Gedanken des Basiskonzepts, dass Organe bestimmte Aufgaben erfüllen. Der Bau der Wurzel wird jedoch nicht untersucht. Dem Kern fehlt damit die Verbindung zwischen der Gestalt der Wurzel und ihrer Leistung bei der Wasseraufnahme.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Der Versuch weist nach, dass die Pflanze Wasser aus ihrer Umgebung aufnimmt. Das ist ein Stoffaustausch mit der Umwelt, wie er für offene biologische Systeme kennzeichnend ist. Der Schwerpunkt liegt auf Versuchsaufbau und Kontrollversuch, doch der Stoffaustausch ist der Sachverhalt, der damit belegt wird. Lernende bauen die Denkweise auf, dass Lebewesen Stoffe aus ihrer Umwelt aufnehmen, und prüfen dies mit einem Versuch.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'ae161e9e-2cf4-4dfe-9ec5-606d5ce80785' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Dass Wasser über die Wurzeln aufgenommen wird, verweist auf die Funktion des Organs Wurzel. Der Bau der Wurzel wird jedoch nicht untersucht.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Der Versuch weist nach, dass die Pflanze Wasser aus ihrer Umgebung aufnimmt. Das ist ein Stoffaustausch mit der Umwelt, hier mit Schwerpunkt auf Versuchsaufbau und Kontrollversuch.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Darm und Blut übernehmen unterschiedliche Aufgaben beim Aufnehmen und Verteilen der Nährstoffbausteine. Damit berührt das Lernziel den Gedanken des Basiskonzepts, dass Organe und Organsysteme von ihrer Funktion her zu verstehen sind. Der Zusammenhang von Bau und Leistung wird aber nicht ausdrücklich verlangt. Dem Kern fehlt, wie der Bau von Darm und Blutgefäßen ihre jeweilige Aufgabe möglich macht.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Nährstoffbausteine gehen aus dem Darm ins Blut über und werden im Körper verteilt. Das ist Stoffaustausch und Stofftransport: Stoffe aus der Nahrung treten in den Körper über und gelangen mit dem Blut zu seinen verschiedenen Teilen. Das Lernziel beschreibt damit den Weg der Stoffe durch den Körper und liegt im Kern des Basiskonzepts. Lernende bauen die Vorstellung auf, dass aufgenommene Stoffe im Körper weitergeleitet werden.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '1d60b2d6-b523-46ef-a334-cd8d7914a295' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Darm und Blutkreislauf übernehmen unterschiedliche Aufgaben beim Aufnehmen und Verteilen der Nährstoffbausteine. Der Zusammenhang von Bau und Leistung wird aber nicht ausdrücklich verlangt.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Nährstoffbausteine gehen aus dem Darm ins Blut über und werden im Körper verteilt. Das ist Stoffaustausch und Stofftransport, der den Weg der Stoffe durch den Körper beschreibt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die mechanische Zerkleinerung der Nahrung geschieht mit Organen wie Mund und Zähnen, deren Bau zu dieser Aufgabe passt. Hier liegt ein Beispiel für den Zusammenhang von Bau und Leistung, den das Basiskonzept beschreibt. Das Lernziel nennt diese Organe jedoch nicht ausdrücklich. Dem Kern fehlt damit der Blick darauf, wie der Bau von Mund und Zähnen das Zerkleinern möglich macht.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Die Aufnahme der Nahrung ist der erste Schritt des Stoffaustauschs mit der Umwelt, den das Basiskonzept für Lebewesen als offene Systeme beschreibt. Die mechanische Zerkleinerung bereitet die Verdauung vor und verändert die Nahrung dabei nur mechanisch. Dem Kern fehlt die Umwandlung der Nährstoffe, die erst in den weiteren Schritten auf dem Weg der Nährstoffe folgt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '299a2d6b-9f14-4f9e-9db9-959d2619cb23' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Zerkleinerung geschieht mit Organen wie Mund und Zähnen, deren Bau zur Aufgabe passt. Das Lernziel nennt diese Organe nicht ausdrücklich.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Die Aufnahme der Nahrung ist der erste Schritt des Stoffaustauschs mit der Umwelt. Die mechanische Zerkleinerung bereitet die Verdauung vor.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Bei der Verdauung wird Stärke in kleinere Bausteine zerlegt. Das ist eine chemische Stoffumwandlung im Körper: Aus dem Nährstoff entstehen kleinere Bausteine, die der Körper aufnehmen kann. Das Lernziel gehört damit zum Kern des Basiskonzepts. Lernende bauen die Vorstellung auf, dass Lebewesen aufgenommene Stoffe chemisch umbauen. Dieser Umbau unterscheidet sich vom mechanischen Zerkleinern, das den Stoff selbst unverändert lässt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'c42a0b85-72ac-4087-85cb-6e711b537826' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Stärke wird in kleinere Bausteine zerlegt. Das ist eine chemische Stoffumwandlung im Körper und gehört zum Kern des Basiskonzepts.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Als Baustoff dienen die Nährstoffbausteine dem Aufbau von Körpersubstanz. Das ist die stoffliche Grundlage für Wachstum, also für die Zunahme von Zellzahl und Zellgröße im Lauf der individuellen Entwicklung. Das Lernziel nennt Wachstum aber nicht ausdrücklich. Dem Kern fehlt damit die zeitliche Sicht auf einen Körper, der sich über sein Leben hinweg verändert.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Nährstoffbausteine werden in verschiedenen Körperteilen, etwa im Muskel, als Baustoff eingebaut oder zur Energiegewinnung genutzt. Damit stehen Stoff- und Energieumwandlung im Körper unmittelbar im Kern: Stoffe werden zu Körpersubstanz umgebaut, und die in Stoffen gebundene Energie wird für Leistungen des Körpers nutzbar. Lernende bauen die Denkweise auf, dass Nahrung zugleich Material und Energiequelle ist.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'f4f450eb-f8fa-4a69-8e42-8813e49122b3' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Als Baustoff dienen die Nährstoffbausteine dem Aufbau von Körpersubstanz und damit dem Wachstum. Das Lernziel nennt Wachstum aber nicht ausdrücklich.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Nährstoffbausteine werden als Baustoff eingebaut oder zur Energiegewinnung genutzt. Damit stehen Stoff- und Energieumwandlung im Körper unmittelbar im Kern.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Widerhaken der Klettfrucht werden mit der Lupe genau betrachtet. Sie gehören zum Zusammenhang von Bau und Haftfunktion, der im Thema Bionik das Naturvorbild liefert. Zunächst steht jedoch das kriteriengeleitete Betrachten im Vordergrund. Dem Kern fehlt, dass die Lernenden den beobachteten Bau der Widerhaken ausdrücklich mit der Haftfunktion verknüpfen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '8a32f38e-2934-48e7-ab44-ac0cddc43253' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Widerhaken der Klettfrucht werden genau betrachtet; sie gehören zum Zusammenhang von Bau und Haftfunktion, der im Thema Bionik das Naturvorbild liefert.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Am Modell wird untersucht, wie der Bau eines Gelenks bestimmte Bewegungen möglich macht. Das ist Struktur-Funktions-Denken, denn aus der Anordnung der Teile folgt, wie beweglich das Gelenk ist. Das Lernziel nennt die Bauteile des Gelenks aber nicht ausdrücklich. Dem Kern fehlt damit die gezielte Verknüpfung einzelner Bauteile mit den Bewegungen, die sie erlauben.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '3238384c-d321-4d47-aba0-677561200b76' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Am Modell wird untersucht, wie der Bau eines Gelenks bestimmte Bewegungen möglich macht. Das ist Struktur-Funktions-Denken.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Das Pflanzenwachstum der Kresse unter verschiedenen Bedingungen dient als Beobachtungsgröße des Versuchs. Wachstum ist ein Teilprozess der individuellen Entwicklung einer Pflanze, und seine Ausprägung hängt hier von Licht und Wasser ab. Die Entwicklung selbst wird jedoch nicht thematisiert. Dem Kern fehlt der Blick darauf, wie sich die Pflanze über die Zeit verändert.$t$::text)), '{basiskonzeptbezug,3,begruendung}', to_jsonb($t$Die Kressepflanzen reagieren je nach Licht und Wasser unterschiedlich. So kann zur Sprache kommen, dass Lebewesen auf äußere Zustände ihrer Umwelt mit einer angepassten Reaktion antworten. Das ist aber nicht der Kern des Lernziels. Dem Kern fehlt der Blick darauf, wie die Pflanze Veränderungen wahrnimmt und ihre Reaktion steuert.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Licht liefert der Pflanze Energie, und Wasser ist ein Stoff, den sie aufnehmen muss. Der Versuch prüft die Bedeutung beider für die Pflanze, und Kontrollversuche sichern die Aussage. Damit liegt der Austausch von Energie und Stoffen mit der Umwelt im Kern. Lernende bauen die Denkweise auf, dass Lebewesen von Energie und Stoffen aus ihrer Umgebung abhängen, und prüfen diese Abhängigkeit mit gezielt veränderten Bedingungen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '6409d7bb-f3fd-45f1-b367-6ec49c67f4aa' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Das Pflanzenwachstum unter verschiedenen Bedingungen dient als Beobachtungsgröße des Versuchs.$t$ AND content #>> '{basiskonzeptbezug,3,begruendung}' = $t$Die Kressepflanzen reagieren je nach Licht und Wasser unterschiedlich; so kann die Reaktion auf äußere Zustände zur Sprache kommen, auch wenn sie nicht Kern ist.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Licht liefert Energie und Wasser ist ein Stoff, den die Pflanze braucht; der Versuch prüft deren Bedeutung und Kontrollversuche sichern die Aussage.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Ob Wasser abperlt, hängt von der Beschaffenheit der Oberfläche (wasserabweisend, rau, genoppt) und von den Kräften zwischen den Teilchen ab. Das Lernziel verbindet damit den Aufbau einer Oberfläche mit ihrem Verhalten gegenüber Wasser und berührt so den Struktur-Funktions-Gedanken. Es bleibt ein physikalisches Beispiel. Dem Kern fehlt der Bezug zu Lebewesen, an denen sich Bau und Leistung biologisch zeigen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '1a03630f-ce25-41e5-b997-061414d4d3c3' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Ob Wasser abperlt, hängt von der Beschaffenheit der Oberfläche (wasserabweisend, rau, genoppt) und den Kräften zwischen den Teilchen ab; das Lernziel verbindet also Aufbau und Verhalten.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die fein genoppte Oberfläche und die Materialeigenschaft erklären, warum Outdoorkleidung oder mit Autowachs behandelte Flächen Wasser abweisen. Hier wird eine Struktur mit ihrer Wirkung verknüpft, was dem Gedanken des Basiskonzepts entspricht. Es geschieht allerdings am Beispiel von Gebrauchsgegenständen. Dem Kern fehlt der Bezug zu Lebewesen, an denen sich Bau und Leistung biologisch zeigen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '9218cc61-aaf4-4479-820e-91fecf5b3a58' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die fein genoppte Oberfläche und die Materialeigenschaft erklären, warum Kleidung oder Lack Wasser abweisen. Hier wird eine Struktur mit ihrer Wirkung verknüpft, allerdings am Beispiel von Gebrauchsgegenständen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Verhalten des Wassertropfens hängt davon ab, ob die Oberfläche wasserliebend oder wasserabweisend ist. Das übt den Gedanken ein, dass die Beschaffenheit einer Fläche ihre Eigenschaft bestimmt, und steht damit dem Struktur-Funktions-Denken nahe. Es bleibt aber ein physikalisches Beispiel. Dem Kern fehlt ein Lebewesen oder Organ, an dem dieser Zusammenhang biologisch gedeutet wird.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'a62b50cc-d865-4a87-85a7-09f7e11f7fa8' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Verhalten des Tropfens hängt von der Beschaffenheit der Oberfläche ab. Das übt den Gedanken ein, dass die Struktur einer Fläche ihre Eigenschaft bestimmt, bleibt aber ein physikalisches Beispiel.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,3,begruendung}', to_jsonb($t$Gleichwarme Tiere halten ihre Körpertemperatur weitgehend konstant, bei wechselwarmen Tieren folgt sie der Umgebung. Das entspricht dem Kern des Basiskonzepts: Ein innerer Zustand wird trotz wechselnder äußerer Bedingungen aufrechterhalten (Homöostase) oder bleibt von ihnen abhängig. Lernende bauen die Denkweise auf, Körpertemperatur als Zustandsgröße zu sehen, die ein Lebewesen in Grenzen hält oder die auf äußere Zustände reagiert.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Gleichwarme Tiere benötigen Energie, um ihre Körpertemperatur zu halten. Dieser Energiebedarf gehört zum Basiskonzept, nach dem alle Lebensprozesse Energie benötigen und Energie mit der Umwelt ausgetauscht wird. Das Lernziel nennt diesen Energieaspekt aber nicht ausdrücklich. Dem Kern fehlt damit der Energiebedarf als Teil des Vergleichs von wechselwarmen und gleichwarmen Tieren.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '3f5d448d-3446-4331-82b4-d22f3f144562' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,3,begruendung}' = $t$Gleichwarm bedeutet, dass die Körpertemperatur weitgehend konstant gehalten wird, wechselwarm bedeutet, dass sie von der Umgebung abhängt. Das berührt Regelung und Reaktion auf äußere Zustände unmittelbar.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Gleichwarme Tiere benötigen Energie, um ihre Körpertemperatur zu halten. Das Lernziel nennt diesen Energieaspekt aber nicht ausdrücklich.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Zur Abgrenzung von Nichtlebendem gehören üblicherweise Merkmale wie Wachstum und Fortpflanzung. Sie sind Teilprozesse der individuellen Entwicklung, die Steine und Gegenstände nicht zeigen. Das Lernziel nennt diese Merkmale allerdings nicht ausdrücklich. Dem Kern fehlt damit die Betrachtung eines Lebewesens als Individuum, das sich über seine Lebenszeit verändert und Nachkommen hervorbringt.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Auch der Stoffwechsel wird üblicherweise zur Abgrenzung von Nichtlebendem herangezogen: Lebewesen nehmen Stoffe aus der Umwelt auf, wandeln sie um und geben Stoffe wieder ab. Das Lernziel selbst nennt den Stoffwechsel jedoch nicht. Dem Kern fehlt damit der Blick auf den ständigen Stoff- und Energieaustausch als Merkmal des Lebendigen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '9b6309b5-643c-4fb0-b559-1174cc06a3da' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Zur Abgrenzung von Nichtlebendem gehören üblicherweise Merkmale wie Wachstum und Fortpflanzung, die das Lernziel allerdings nicht ausdrücklich nennt.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Auch Stoffwechsel wird üblicherweise zur Abgrenzung herangezogen, das Lernziel selbst nennt ihn nicht.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug}', $j$[{"begruendung":"Kein Evolutionsbezug.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Kein Bezug zu Entwicklung von Lebewesen.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stofftrennung nutzt unterschiedliche Stoffeigenschaften, bezieht sich aber nicht auf Bau und Leistung von Organen.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Steuerung oder Regelung ist in diesem Lernziel nicht angesprochen.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Lernziel selbst spricht dieses Basiskonzept nicht an.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Kein Bezug zu Information oder Kommunikation.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}]$j$::jsonb), '{basiskonzepte_primaer}', $j$[]$j$::jsonb), '{basiskonzepte_sekundaer}', $j$[]$j$::jsonb), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '148db929-57e0-43d2-9398-83ced9e55da2' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Gemische in Alltagsbeispielen zu trennen betrifft den Umgang mit Stoffen. Eine Stoffumwandlung findet dabei nicht statt, daher nur ein Bezug am Rand.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Chemische Reaktionen sind hier ausdrücklich als Stoff- und Energieumwandlungen gefasst. Die Lernenden sollen sie von Zustandsänderungen und Mischvorgängen abgrenzen, bei denen kein neuer Stoff entsteht. Das Lernziel liegt damit im Kern des Basiskonzepts. Lernende bauen die Denkweise auf, Vorgänge danach zu unterscheiden, ob neue Stoffe entstehen und Energie umgewandelt wird.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '649d5d41-9c4a-4314-afab-b3decb16acf2' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Chemische Reaktionen sind hier als Stoff- und Energieumwandlungen gefasst. Die Lernenden sollen sie von bloßen Zustandsänderungen und Mischvorgängen abgrenzen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Die unterschiedlichen Blütenformen bei Wind- und Insektenbestäubung sind ein Beispiel für Angepasstheit als Ergebnis von Evolution. Angepasstheit entsteht nach dem Basiskonzept durch evolutive Prozesse in Populationen über viele Generationen. Der Begriff Evolution fällt im Lernziel aber nicht. Dem Kern fehlt die Frage, wie solche Unterschiede in Populationen entstehen.$t$::text)), '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Die Bestäubung, bei der Pollen vom Staubblatt auf die Narbe des Fruchtblattes gelangt, ist ein Schritt der Fortpflanzung der Samenpflanzen und damit Teil ihrer Entwicklung. Sie bereitet die Entstehung neuer Individuen vor. Im Lernziel liegt der Schwerpunkt jedoch auf der Übertragung des Pollens und auf dem Blütenbau. Dem Kern fehlt der Blick auf die weitere Entwicklung nach der Bestäubung.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel verlangt ausdrücklich, den Bau von Blüten (Staubblatt, Narbe, Blütenform) mit der Funktion Bestäubung durch Wind oder Insekten zu verknüpfen. Damit steht der Zusammenhang von Bau und Leistung im Kern: Die Gestalt der Blüte hängt mit der Art der Bestäubung zusammen. Lernende bauen die Denkweise auf, von der Form eines Organs auf seine Aufgabe zu schließen und umgekehrt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '3f4e53a4-d510-433d-a308-c1f2b3465360' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Die unterschiedlichen Blütenformen sind ein Beispiel für Angepasstheit als Ergebnis von Evolution. Der Begriff selbst fällt im Lernziel aber nicht.$t$ AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Die Bestäubung ist ein Schritt der Fortpflanzung der Samenpflanzen und damit Teil ihrer Entwicklung.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Lernziel verlangt ausdrücklich, den Bau von Blüten (Staubblatt, Narbe, Blütenform) mit der Funktion Bestäubung durch Wind oder Insekten zu verknüpfen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Befruchtung und Fruchtbildung sind zentrale Schritte im Lebenslauf einer Samenpflanze. Mit der Verschmelzung von Samenzelle und Eizelle beginnt ein neues Individuum, und die Fruchtbildung führt weiter zur Frucht mit Samen. Das entspricht der geschlechtlichen Fortpflanzung und den aufeinanderfolgenden Entwicklungsphasen im Lebenszyklus. Lernende erfassen so Entwicklung als eine Abfolge von Stadien, die von der Blüte bis zur Frucht mit Samen reicht.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'a95d79eb-4ea6-482e-b16f-c45948c925e0' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Befruchtung und Fruchtbildung sind zentrale Schritte der Fortpflanzung und der Entwicklung einer Samenpflanze vom Blütenstadium zur Frucht mit Samen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel verknüpft die Form von Knochen mit ihrer Aufgabe: Röhrenknochen stehen für Stabilität, Plattenknochen für Schutz. Das ist der Zusammenhang zwischen Gestalt oder innerem Bau einer Struktur und ihrer Funktion, den das Unterkonzept morphologische und anatomische Angepasstheit beschreibt. Lernende üben dabei, von der Bauweise eines Körperteils auf seine Leistung zu schließen und umgekehrt. Das ist die Kernidee des Basiskonzepts.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '27d2384c-4773-42f4-899e-adb3493501e1' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Lernziel verknüpft Knochenform und Aufgabe, etwa Röhrenknochen mit Stabilität und Plattenknochen mit Schutz.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Schwangerschaftsverhütung greift in den Ablauf der menschlichen Fortpflanzung ein. Wer Möglichkeiten dazu nennt, setzt Wissen über Befruchtung und Schwangerschaft voraus. Damit liegt das Lernziel im Kern des Unterkonzepts Reproduktion und Fortpflanzung, bei dem durch die Verschmelzung von Keimzellen ein neuer Entwicklungszyklus beginnt. Das Lernziel selbst bleibt beim Nennen der Möglichkeiten und behandelt die Entwicklungsvorgänge nicht im Einzelnen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'ecee12a1-7638-4d84-a4a5-72f0e27c3ca0' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Schwangerschaftsverhütung greift in den Ablauf der menschlichen Fortpflanzung ein und setzt Wissen über Befruchtung und Schwangerschaft voraus.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Bei der Herstellung von Stoffen wie Glas oder Kunststoffen reagieren Ausgangsstoffe chemisch miteinander, und es entstehen neue Stoffe mit anderen Eigenschaften. Genau das beschreibt das Unterkonzept Stoffumwandlung: Ein Stoff wird chemisch umgewandelt und liegt danach als anderer Stoff vor. Lernende bauen die Denkweise auf, dass sich Stoffe nach einer Reaktion in ihren Eigenschaften unterscheiden und Reaktionen gezielt genutzt werden, um Gebrauchsstoffe herzustellen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'e779a2af-a6b0-456c-a7c7-de0779870da4' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Bei der Herstellung von Stoffen wie Glas oder Kunststoffen entstehen aus Ausgangsstoffen neue Stoffe mit anderen Eigenschaften. Das ist der Kern von Stoffumwandlung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Beim Verbrennen von Holzkohle im Grill wird gespeicherte Energie als Wärme frei, und diese Wärme wird genutzt. Damit liegen zwei Unterkonzepte zugleich vor: Energieumwandlung, weil Energie von einer Form in eine andere überführt wird, und Stoffumwandlung, weil aus der Kohle neue Stoffe entstehen. Lernende sehen an diesem Beispiel, dass sich die bei einer chemischen Reaktion freigesetzte Wärme nutzen lässt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '421fad98-41fe-40e4-9e0e-b8bf9dc1e9d5' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Bei der Verbrennung von Holzkohle wird gespeicherte Energie als Wärme frei und genutzt. Das ist unmittelbar Energieumwandlung und zugleich Stoffumwandlung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Die äußere Befruchtung des Grasfrosches wird als Angepasstheit an den Lebensraum Wasser betrachtet. Angepasstheit ist im Basiskonzept ein Ergebnis evolutiver Prozesse, daher gibt es einen Anknüpfungspunkt. Dem Kern fehlt die Frage, wie dieses Merkmal über viele Generationen entstanden ist. Das Lernziel erklärt die Angepasstheit nicht als Ergebnis von Evolution. Es beschreibt nur den Zusammenhang zwischen Fortpflanzung und Lebensraum.$t$::text)), '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Fortpflanzung und Entwicklung des Grasfrosches stehen im Mittelpunkt dieses Lernziels, die äußere Befruchtung ist dabei Teil der Fortpflanzung. Das entspricht dem Unterkonzept Reproduktion und Fortpflanzung: Bei geschlechtlicher Fortpflanzung verschmelzen Keimzellen, und damit beginnt ein neuer Entwicklungszyklus. Lernende erkennen, dass Fortpflanzung und Entwicklung eines Tieres zusammengehören und ein Lebewesen von der befruchteten Eizelle an einen eigenen Lebenslauf durchläuft.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'c397a119-d0cd-449a-acd1-457d5996c487' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Die äußere Befruchtung wird als Angepasstheit an den Lebensraum Wasser betrachtet; als Ergebnis von Evolution wird sie im Lernziel selbst nicht erklärt.$t$ AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Fortpflanzung und Entwicklung des Grasfrosches stehen im Mittelpunkt, hier mit äußerer Befruchtung als Teil der Fortpflanzung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Schwimmfüße und eingefettetes Gefieder der Graugans sind Angepasstheiten an das Schwimmen, und Angepasstheit ist im Basiskonzept ein Ergebnis der Stammesgeschichte. Damit besteht ein Bezug. Dem Kern fehlt die Frage, wie sich diese Merkmale über Generationen herausgebildet haben. Das Lernziel spricht die Stammesgeschichte nicht an und stellt nur den Zusammenhang zwischen Lebensweise und Körperbau her.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Schwimmfüße und eingefettetes Gefieder der Graugans werden im Lernziel ausdrücklich mit dem Schwimmen verknüpft. Das ist der Zusammenhang zwischen Gestalt eines Körperteils und seiner Funktion in der Umwelt, wie ihn das Unterkonzept morphologische und anatomische Angepasstheit beschreibt. Lernende bauen die Denkweise auf, vom Bau auf die Leistung zu schließen: Welche Funktion haben Schwimmfüße und Gefieder beim Schwimmen?$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'b23d99d7-c2a1-4550-8d7e-246c48e2298d' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Die Angepasstheit der Graugans an das Schwimmen ist ein Ergebnis der Stammesgeschichte; das Lernziel spricht diese aber nicht an.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Schwimmfüße und eingefettetes Gefieder werden ausdrücklich mit dem Schwimmen verknüpft. Bau und Funktion stehen im Kern.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Dass die Vordergliedmaßen der Graugans als Flügel ausgeprägt sind, berührt Abwandlung und Verwandtschaft der Wirbeltiere. Im Unterkonzept Homologie und Analogie gehen Strukturen auf ein gemeinsames Grundmuster zurück und erfüllen in verschiedenen Gruppen unterschiedliche Aufgaben. Dem Kern fehlt ein solcher Vergleich. Das Lernziel führt diesen Gedanken nicht aus und nennt den Flügel nur als Teil des Fliegens.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Flügel, stromlinienförmiger Körper, Federn und hohle Knochen werden im Lernziel ausdrücklich dem Fliegen zugeordnet. Mehrere Bauelemente sind also mit einer gemeinsamen Funktion verknüpft. Das entspricht dem Unterkonzept morphologische und anatomische Angepasstheit, bei dem von der Gestalt und dem inneren Bau auf die Funktion geschlossen wird. Lernende erkennen, dass ein Körper aus zusammenwirkenden Merkmalen besteht, die gemeinsam eine Leistung wie das Fliegen ermöglichen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '3a808a82-ca58-4adc-972c-9f5bfaa4d314' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Dass die Vordergliedmaßen als Flügel ausgeprägt sind, berührt Abwandlung und Verwandtschaft der Wirbeltiere. Das Lernziel führt diesen Gedanken aber nicht aus.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Flügel, stromlinienförmiger Körper, Federn und hohle Knochen werden ausdrücklich mit dem Fliegen verknüpft. Bau und Funktion stehen im Kern.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Die Fortbewegung der Ringelnatter an Land mit Bauchmuskeln und Bauchschuppen ist eine Angepasstheit, und Angepasstheit ist im Basiskonzept ein Ergebnis der Stammesgeschichte. Daraus ergibt sich ein Bezug. Dem Kern fehlt die Frage, wie solche Merkmale über Generationen entstanden sind. Das Lernziel spricht die Stammesgeschichte nicht an und bleibt beim Schlängeln als Leistung des Körperbaus.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Bauchmuskeln und Bauchschuppen der Ringelnatter werden im Lernziel unmittelbar mit dem Schlängeln an Land verknüpft. Das ist der Zusammenhang zwischen Körperbau und Fortbewegung, den das Unterkonzept morphologische und anatomische Angepasstheit beschreibt. Aus der Gestalt einer Struktur lässt sich ihre Funktion erschließen. Lernende erklären, welche Bauteile die Bewegung ermöglichen, und lernen damit eine Denkweise kennen, die sich auf andere Tiere anwenden lässt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '5fc47f15-304c-44e3-ae7f-ddbf87adbc69' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Die Angepasstheit der Ringelnatter an das Leben an Land ist ein Ergebnis der Stammesgeschichte; das Lernziel spricht diese aber nicht an.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Bauchmuskeln und Bauchschuppen ermöglichen das Schlängeln. Das Lernziel verknüpft Körperbau und Fortbewegung unmittelbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Trockene Haut mit Hornschuppen als Schutz vor Austrocknung ist eine Angepasstheit der Ringelnatter an das Leben an Land. Angepasstheit ist im Basiskonzept ein Ergebnis von Evolution, daher gibt es einen Bezug. Das Lernziel fragt aber nur nach dem Zusammenhang von Merkmal und Lebensraum. Dem Kern fehlt die Frage, wie das Merkmal über viele Generationen entstanden ist.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel verbindet die Körperbedeckung der Ringelnatter, trockene Haut mit Hornschuppen, mit ihrer Schutzfunktion vor Austrocknung. Gefragt ist damit der Zusammenhang zwischen Bau und Aufgabe einer Struktur, also die morphologische und anatomische Angepasstheit. Lernende üben, aus dem Bau einer Struktur ihre Funktion abzuleiten und zu erklären, wie ein Merkmal den Anforderungen des Lebens an Land entspricht.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Der Schutz vor Austrocknung betrifft den Wasserverlust des Körpers. Damit berührt das Lernziel den Stoffaustausch mit der Umwelt, also die Abgabe von Stoffen wie Wasser an die Umgebung. Dem Kern fehlt der Austausch selbst. Das Lernziel behandelt die Haut als Schutz und geht auf Aufnahme, Abgabe oder Umwandlung von Stoffen nicht weiter ein.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '694a9999-11b2-4d60-abc7-67d6583f014f' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Angepasstheit an einen Lebensraum ist Ergebnis von Evolution; das Lernziel fragt aber nur nach dem Zusammenhang von Merkmal und Lebensraum und geht auf dessen Entstehung nicht ein.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Lernziel verbindet die Körperbedeckung der Ringelnatter, trockene Haut mit Hornschuppen, mit ihrer Schutzfunktion und behandelt damit unmittelbar Bau und Funktion.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Der Schutz vor Austrocknung betrifft den Wasserverlust des Körpers und damit den Stoffaustausch mit der Umwelt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Das Lernziel nennt Wachstum als eine Verwendung der gebildeten energiereichen Stoffe. Wachstum bedeutet im Basiskonzept die Zunahme von Zellzahl oder Zellgröße über die Zeit, hier gestützt durch Baumaterial aus diesen Stoffen. Das ist jedoch nur ein Teil. Der Kern liegt bei der Bedeutung der Stoffe für Energie und Baumaterial. Die Entwicklung der Pflanze wird nicht weiter behandelt.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Energiereiche Stoffe dienen der Pflanze als Speicher und Lieferant von Energie und als Baumaterial. Das Lernziel behandelt diese Verwendung unmittelbar und verbindet damit Stoffumwandlung mit Energieumwandlung: Stoffe werden aufgenommen, umgewandelt und genutzt, wobei Energie von einer Form in eine andere überführt wird. Lernende bauen die Denkweise auf, Stoffe und Energie in der Pflanze gemeinsam zu betrachten.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'd017ac25-d5ed-4b8e-9af8-b09aa150cb64' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Das Lernziel nennt Wachstum als eine Verwendung der gebildeten Stoffe; Wachstum ist ein Teil, aber nicht der Kern.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Energiereiche Stoffe sind Speicher und Lieferanten von Energie und Baumaterial für die Pflanze; das Lernziel behandelt die Verwendung dieser Stoffe unmittelbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Der Vergleich der Wirbeltierklassen anhand von Kiemen, Haut und Lunge macht Vielfalt und Gemeinsamkeiten zwischen Tiergruppen sichtbar. Das berührt das Unterkonzept Variation und Diversität. Dem Kern fehlt die Behandlung von Evolutionsprozessen. Das Lernziel stellt die Atmungsorgane gegenüber und fragt nicht, wie die Unterschiede entstanden sind.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Kiemen, Haut und Lunge sind unterschiedlich gebaute Atmungsorgane. Das Lernziel lässt sie gegenüberstellen und Vertreter begründet zuordnen. So wird sichtbar, wie der Bau zum Gasaustausch in Wasser oder Luft passt. Das ist der Zusammenhang von Gestalt und Funktion im Sinne der morphologischen und anatomischen Angepasstheit. Lernende erfahren, dass verschiedene Strukturen dieselbe Aufgabe erfüllen können und der Bau jeweils zum Lebensraum gehört.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Atmung ist Gasaustausch mit der Umwelt: Sauerstoff wird aufgenommen, Kohlenstoffdioxid wird abgegeben. Das entspricht dem Unterkonzept Stoffaustausch mit der Umwelt. Im Lernziel steht aber der Vergleich der Atmungsorgane im Vordergrund. Dem Kern fehlt der Stoffaustausch als Vorgang, denn die Aufnahme und Abgabe von Gasen wird dort nicht ausgeführt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'b496d374-795f-4cac-ac3a-1c6e62408c24' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Der Vergleich der Klassen macht Vielfalt und Gemeinsamkeiten zwischen Tiergruppen sichtbar, Evolutionsprozesse selbst werden aber nicht behandelt.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Kiemen, Haut und Lunge sind unterschiedlich gebaute Atmungsorgane. Der Vergleich zeigt, wie der Bau zum Gasaustausch in Wasser oder Luft passt.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Atmung ist Gasaustausch mit der Umwelt (Sauerstoff aufnehmen, Kohlenstoffdioxid abgeben), steht hier aber nicht im Mittelpunkt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Der Klassenvergleich zeigt verschiedene Fortpflanzungsweisen als Vielfalt innerhalb der Wirbeltiere, etwa äußere und innere Befruchtung. Das berührt das Unterkonzept Variation und Diversität. Dem Kern fehlt die Behandlung von Evolutionsprozessen. Das Lernziel stellt die Unterschiede gegenüber und fragt nicht, wie sie entstanden sind.$t$::text)), '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Befruchtung und Entwicklung des Embryos gehören zur Fortpflanzung und zur Individualentwicklung. Verglichen wird, ob die Befruchtung außerhalb oder innerhalb des Körpers stattfindet und ob sich der Embryo innerhalb oder außerhalb des Körpers entwickelt. Das entspricht dem Unterkonzept Reproduktion und Fortpflanzung. Lernende erkennen, dass die frühe Entwicklung eines Lebewesens in den Wirbeltierklassen unter unterschiedlichen Bedingungen verläuft.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'd1ec0483-838d-49fe-932f-8fdfc8781f4e' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Der Klassenvergleich zeigt verschiedene Fortpflanzungsweisen als Vielfalt innerhalb der Wirbeltiere, Evolutionsprozesse werden aber nicht behandelt.$t$ AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Befruchtung und Entwicklung des Embryos sind Teil der Fortpflanzung und der Individualentwicklung. Verglichen wird die Entwicklung innerhalb und außerhalb des Körpers.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Flossen sind eine Angepasstheit der Fische, und Angepasstheit ist im Basiskonzept ein Ergebnis der Stammesgeschichte. Daher gibt es einen Bezug. Das Modellexperiment untersucht jedoch nur die Funktionsweise der Flossen. Dem Kern fehlt die Frage, wie solche Merkmale über viele Generationen entstanden sind. Evolution wird im Lernziel nicht angesprochen.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Am Modell wird untersucht, wie Flossen beim Schwimmen wirken. Das verbindet Gestalt und Leistung eines Körperteils und entspricht dem Unterkonzept morphologische und anatomische Angepasstheit. Das Modell erlaubt Lernenden, den Zusammenhang selbst zu erproben. Sie bauen dabei die Denkweise auf, aus dem Bau einer Struktur ihre Wirkung abzuleiten.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'a6e7fb66-1883-4601-bc90-c5402bdc3543' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Das Thema Angepasstheit der Fische berührt Ergebnisse der Stammesgeschichte, das Modellexperiment selbst spricht Evolution aber nicht an.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Am Modell wird untersucht, wie Flossen gebaut sind und wie sie beim Schwimmen wirken. Das ist Bau-Funktions-Denken im Kern.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Blutkreislauf oder Lunge mit der Modellmethode darzustellen macht die einzelnen Teile und ihr Zusammenwirken sichtbar. Bau und Anordnung der Teile hängen mit der Funktion des Ganzen zusammen, und dieser Zusammenhang von Struktur und Funktion wird im Modell greifbar. Lernende bauen die Denkweise auf, ein Organ oder ein Organsystem als Gefüge zusammenwirkender Teile zu verstehen, deren Aufbau seine Leistung erklärt.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Blutkreislauf und Lunge hängen mit dem Transport und Austausch von Stoffen wie Sauerstoff zusammen. Insofern besteht ein Bezug zum Stoffaustausch mit der Umwelt. Dem Kern fehlt, dass das Lernziel diese Vorgänge nicht ausdrücklich nennt. Verlangt wird die Darstellung des Aufbaus, und der Stofftransport selbst bleibt unbehandelt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '77c891fa-4d8b-4e8b-8cd7-084536fab670' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Darstellen von Blutkreislauf oder Lungenaufbau mit der Modellmethode macht die Teile und ihr Zusammenwirken sichtbar.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Beide Beispiele hängen mit dem Transport und Austausch von Stoffen wie Sauerstoff zusammen, doch das Lernziel nennt diese Vorgänge nicht ausdrücklich.$t$;
-- ===== evomentor-thuringia-sandbox =====
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel nennt die Lunge als das Organ, über das Sauerstoff in das Blut gelangt, und verbindet damit ein Organ mit einer Aufgabe. Das passt zum Gedanken des Konzepts, dass Bau und Funktion oft zusammenhängen. Wie die Lunge gebaut ist und warum dieser Bau den Übertritt erleichtert, steht im Lernziel aber nicht im Mittelpunkt.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Sauerstoff wird über die Lunge in das Blut aufgenommen. Das ist ein Stoffaustausch mit der Umwelt, wie ihn das Konzept für offene biologische Systeme beschreibt: Lebewesen nehmen Stoffe auf und geben andere wieder ab. Der aufgenommene Sauerstoff ist zugleich die Voraussetzung dafür, dass der Körper Energie gewinnen kann. Lernende bauen so die Vorstellung auf, dass ein Lebewesen mit seiner Umgebung im ständigen Austausch steht.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '766f9a38-ed8f-49fa-ad16-933afbef1607' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Lunge ist das Organ, in dem Sauerstoff ins Blut übertritt; ihr Bau steht im Lernziel aber nicht im Mittelpunkt.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Die Aufnahme von Sauerstoff in das Blut ist ein Stoffaustausch mit der Umwelt und die Voraussetzung für die Energiegewinnung im Körper.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Das Lernziel erläutert, wie der Grasfrosch als Larve im Wasser und als erwachsenes Tier an Land lebt, und spricht dabei von Angepasstheit an beide Lebensräume. Angepasstheit gilt im Konzept als Ergebnis evolutiver Prozesse, das über Generationen durch natürliche Selektion entstanden ist. Wie sie entstanden ist, spricht das Lernziel jedoch nicht an. Der stammesgeschichtliche Bezug ist nur angedeutet.$t$::text)), '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Das Lernziel zeichnet den gesamten Entwicklungsweg des Grasfroschs nach: vom Laich über die im Wasser lebende Larve mit Kiemen und Ruderschwanz bis zum erwachsenen Tier an Land mit Lunge und Gliedmaßen. Das entspricht einer indirekten Entwicklung mit Metamorphose, bei der sich Larve und erwachsenes Tier in Gestalt und Lebensweise deutlich unterscheiden. Lernende erfassen Entwicklung so als Abfolge von Phasen mit tiefgreifendem Umbau des Körpers.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel ordnet jedem Lebensraum eigene Körpermerkmale zu: Kiemen und Ruderschwanz der Larve im Wasser, feuchte Haut, Lunge und Gliedmaßen des erwachsenen Tiers an Land. Damit wird der Bau eines Körperteils ausdrücklich mit seiner Leistung in der jeweiligen Umwelt verknüpft, wie es das Konzept über Gestalt und inneren Bau beschreibt. Lernende üben, von Merkmalen des Körpers auf deren Funktion im Lebensraum zu schließen.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Der Gasaustausch ist ein Stoffaustausch mit der Umwelt: Die Larve tauscht Gase über Kiemen aus, das erwachsene Tier über feuchte Haut und Lunge. Das passt zum Konzept, wonach Lebewesen mit ihrer Umgebung Stoffe austauschen. Der Austausch bleibt ein Teilaspekt, denn das Lernziel gilt vor allem Entwicklung und Körperbau. Umwandlung von Stoffen oder Energie kommt nicht vor.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'c1d43347-122a-4c98-bc68-f1ae504dfeec' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Die Angepasstheit an Wasser und Land ist ein Ergebnis der Stammesgeschichte; das Lernziel spricht diese aber nicht an.$t$ AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Vom Laich über die Larve bis zum erwachsenen Tier wird ein ganzer Entwicklungsweg mit Verwandlung beschrieben.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Kiemen und Ruderschwanz im Wasser, Lunge, feuchte Haut und Gliedmaßen an Land: Bau und Lebensraum werden ausdrücklich verknüpft.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Der Gasaustausch wechselt von Kiemen zu Haut und Lunge. Der Stoffaustausch mit der Umwelt ist ein Teilaspekt des Lernziels.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Das Lernziel beschreibt, wie Nahrungsbausteine und Sauerstoff im Körper in alle Teile gelangen, damit sie dort genutzt werden können. Dieser Stofftransport verbindet die Aufnahme von Stoffen aus der Umwelt mit ihrer Verwendung im Körper und trifft damit die Idee des Konzepts, dass Lebewesen Stoffe aufnehmen, umwandeln und nutzen. Der Stofftransport im Körper ist der Kern des Lernziels. Lernende verstehen den Körper dabei als System, das ständig mit Stoffen versorgt werden muss.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '3b197585-8aaa-4f5f-a31b-66cfdd4a3e68' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Nahrungsbausteine und Sauerstoff werden in alle Körperteile gebracht, damit sie dort genutzt werden können. Der Stofftransport im Körper ist der Kern des Lernziels.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Das Lernziel führt in die Stoffebene ein: Reinstoffe werden an Farbe, Aggregatzustand, Geruch und Oberflächenbeschaffenheit erkannt und unterschieden. Der Aggregatzustand verweist zudem auf den Energiezustand der Teilchen. Damit entsteht eine Grundlage, um später Stoffe und ihre Umwandlungen zu betrachten. Stoff- und Energieumwandlung selbst werden hier noch nicht behandelt, der Bezug bleibt mittelbar.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '139602e4-18f7-4ccd-8ff1-a543ebfdcd2f' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Das Beschreiben von Farbe, Aggregatzustand, Geruch und Oberflächenbeschaffenheit führt in die Stoffebene ein: Reinstoffe werden an ihren Eigenschaften erkannt und unterschieden, der Aggregatzustand verweist auf den Energiezustand der Teilchen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Beim Vergleich von biologischem Vorbild und technischer Umsetzung, hier am Nebeltrinkerkäfer, steht das gemeinsame Prinzip im Mittelpunkt: Eine bestimmte Oberflächengestalt ermöglicht eine bestimmte Funktion, im Lebewesen wie in der Technik. Das ist der Kern des Konzepts, wonach zwischen der Gestalt einer Struktur und ihrer Funktion ein Zusammenhang besteht. Lernende üben, Funktionen auf Merkmale des Baus zurückzuführen und dieses Muster auf andere Gegenstände zu übertragen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'abcf27a7-c5be-4c67-bc54-30b046ffc53a' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Der Vergleich arbeitet das gemeinsame Prinzip heraus: Eine bestimmte Oberflächengestalt ermöglicht eine bestimmte Funktion, im Lebewesen wie in der Technik.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Wer ein Skelettmodell gestaltet, muss entscheiden, wie Knochen und Gelenke zusammengesetzt werden, und sieht dabei, dass sie gemeinsam Stütze und Beweglichkeit ermöglichen. Der Bau des Skeletts wird so handelnd mit seiner Funktion verbunden, wie es das Konzept beschreibt. Das Modell macht Strukturen sichtbar, die im Körper verborgen liegen. Lernende bauen die Denkweise auf, aus der Anordnung der Teile auf ihre Aufgabe zu schließen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '2c3fbc8c-6ec0-47c5-bd65-5ab9280a18a8' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Beim Gestalten eines Skelettmodells wird sichtbar, wie Knochen und Gelenke zusammen Stütze und Beweglichkeit ermöglichen, also wie der Bau die Funktion bestimmt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Beim Abmessen von Flüssigkeiten werden Stoffe als messbare Größen behandelt, am Rand auch das Arbeiten mit Stoffmengen. Das berührt das Konzept nur schwach, denn dessen Kern sind Austausch, Umwandlung und Energiebedarf von Stoffen in Lebewesen. Das Lernziel betrifft die Messtechnik. Stoffumwandlung und Energie kommen darin nicht vor, die Zuordnung ist daher nur vorsichtig.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'b886db49-8f8a-493b-a60b-57e0f582b1df' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Das Abmessen von Flüssigkeitsmengen berührt Stoffe als messbare Größen, am Rand auch das Arbeiten mit Stoffmengen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Wildwachsende Samenpflanzen sind Nahrungsgrundlage für Tiere und stellen Sauerstoff bereit. Damit sind Stoff- und Energiefluss in Lebensgemeinschaften unmittelbar angesprochen: Energie gelangt von den Pflanzen als Produzenten über die Nahrung zu den Tieren, und Sauerstoff ist ein Stoff, den Pflanzen an die Umwelt abgeben. Lernende erkennen, dass Lebensgemeinschaften über Stoffe und Energie miteinander verbunden sind.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '537c740c-96da-45c9-b7c4-12db2671f853' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Pflanzen sind Nahrungsgrundlage für Tiere und stellen Sauerstoff bereit. Damit sind Stoff- und Energiefluss in Lebensgemeinschaften unmittelbar angesprochen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel verlangt, Gelenke als Voraussetzung für Beweglichkeit zu beschreiben. Der Bau eines Gelenks, etwa Gelenkkopf und Gelenkpfanne, wird damit mit seiner Funktion verbunden. Das ist ein klares Beispiel für den Zusammenhang von Struktur und Funktion: Die Form der Gelenkteile hängt mit der möglichen Bewegung zusammen. Lernende erfahren, dass die Gestalt eines Körperteils mit erklärt, was es leisten kann.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '04776aa5-12e3-4a33-b616-a635a33c1155' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Der Bau eines Gelenks (z. B. Gelenkkopf, Gelenkpfanne) wird mit der Funktion Beweglichkeit verbunden.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Skelett ist ein zentrales Beispiel für den Bau des Körpers. Die Gliederung in Schädel, Wirbelsäule, Schulter- und Beckengürtel, Gliedmaßen und Brustkorb benennt die Strukturen, an denen sich später Funktionen wie Stütze und Bewegung erklären lassen. Das Lernziel beschreibt zunächst den Bau. Lernende erwerben damit die Begriffe, die sie brauchen, um Bau und Funktion des Körpers später aufeinander zu beziehen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'e16cbfbb-4340-4904-a459-7daf748d7b0c' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Skelett ist ein zentrales Beispiel für den Bau des Körpers. Die Gliederung in Schädel, Wirbelsäule, Gürtel, Gliedmaßen und Brustkorb legt die Grundlage für die Funktionen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel verbindet zwei Strukturen, Muskulatur und Skelett, zu einer gemeinsamen Funktion: Muskeln und Knochen wirken zusammen, damit Bewegung entsteht, etwa wenn ein Muskel über ein Gelenk an einem Knochen zieht. Am Beispiel lässt sich zeigen, dass Muskelpaare mit entgegengesetzter Wirkung ein Gelenk in beide Richtungen bewegen und seine Stellung steuern. Lernende erkennen, dass eine Leistung des Körpers erst durch das Zusammenspiel mehrerer Strukturen entsteht.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'fc9896eb-8094-45fb-a4c4-c1977620cb46' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Muskeln und Knochen wirken zusammen, damit Bewegung entsteht, etwa wenn ein Muskel über ein Gelenk an einem Knochen zieht.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Das Lernziel nennt den Aufbau körpereigener Stoffe, zum Beispiel für das Wachstum. Wachstum, also die Zunahme von Zellzahl oder Zellgröße, ist ein Teilprozess der individuellen Entwicklung. Der Bezug besteht, doch das Lernziel gilt der Bedeutung von Ernährung und Atmung. Der Lebenslauf eines Organismus wird nicht behandelt, daher steht Wachstum hier nicht im Kern.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Das Lernziel beschreibt, dass Nahrung zum Aufbau körpereigener Stoffe genutzt wird und über die Atmung Energie bereitstellt. Aufgenommene Stoffe werden dabei im Körper in andere Stoffe umgewandelt, und die in der Nahrung gebundene Energie wird für Lebensvorgänge nutzbar. Beides berührt Stoffumwandlung und Energieumwandlung unmittelbar. Lernende bauen die Vorstellung auf, dass Lebewesen Stoffe und Energie aus der Umwelt nutzen müssen, um zu wachsen und zu leben.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'a1461c87-1ac9-4f95-8f07-9ac102499ee7' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Nährstoffe dienen dem Wachstum; Wachstum ist ein Teil der Individualentwicklung, steht hier aber nicht im Kern.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Nahrung wird zum Aufbau körpereigener Stoffe genutzt und liefert über die Atmung Energie. Das berührt Stoffumwandlung und Energieumwandlung unmittelbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Das Säugen mit Muttermilch gehört zur Entwicklung der Jungen nach der Geburt und zur Brutpflege bei Säugetieren. Es ist ein fester Abschnitt im Lebenszyklus und Teil der Fortpflanzung, die einen neuen Entwicklungszyklus beginnen lässt. Lernende ordnen das Säugen als Phase der Entwicklung eines Individuums ein, das nach der Geburt zunächst von der Mutter versorgt wird und erst allmählich selbstständig wird.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Die Muttermilch liefert dem Neugeborenen Nährstoffe und Energie und ist damit Stoffübertragung von der Mutter auf das Jungtier. Das passt zum Konzept, wonach Lebewesen Stoffe aufnehmen und als Energiequelle nutzen. Im Lernziel steht jedoch das Säugen als Teil von Fortpflanzung und Entwicklung im Vordergrund. Die Umwandlung der Nährstoffe wird nicht angesprochen, der Bezug ist nur am Rand gegeben.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '4c148bd7-0ab3-4d5d-ba55-b07da5c69ba7' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Das Säugen mit Muttermilch gehört zur Entwicklung der Jungen nach der Geburt und zur Brutpflege bei Säugetieren.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Die Muttermilch liefert dem Neugeborenen Nährstoffe und Energie und ist damit Stoffübertragung von der Mutter auf das Jungtier.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Nesthocker und Nestflüchter unterscheiden sich in der Entwicklung bei und nach der Geburt: Die Jungtiere sind unterschiedlich weit entwickelt und brauchen unterschiedlich lange Pflege. Damit geht es um die Entwicklungsphasen im Lebenszyklus und um die Fortpflanzung, mit der ein neuer Entwicklungszyklus beginnt. Der Vergleich beider Formen zeigt Lernenden, dass der Entwicklungsstand zur Geburt je nach Art verschieden ist und die Individualentwicklung entsprechend unterschiedlich verläuft.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '00e944b5-2a15-4af3-8bfb-13ba0450c127' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Nesthocker und Nestflüchter unterscheiden sich in der Entwicklung bei und nach der Geburt, also darin, wie weit Jungtiere entwickelt sind und wie lange sie Pflege brauchen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Oberflächenvergrößerung ist ein eigenes Strukturprinzip des Konzepts. Eine Grenzfläche wird durch Falten, Ausstülpungen oder Verzweigungen vergrößert, wie bei Darmzotten und Lungenbläschen, und kann dadurch Austauschvorgänge beschleunigen. So ermöglicht der Bau eines Organs seine Funktion. Lernende bauen die Denkweise auf, dass die Größe und Gestalt einer Fläche die Leistung eines Organs mitbestimmt, und können sie auf weitere Organe übertragen.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Eine große Fläche erleichtert die Aufnahme von Nährstoffen und Sauerstoff und damit den Stoffaustausch mit der Umgebung, den das Konzept für offene Systeme beschreibt. Im Lernziel steht jedoch die Darstellung des Bauprinzips im Mittelpunkt. Was mit den aufgenommenen Stoffen im Körper geschieht, wird nicht angesprochen. Die Zuordnung bleibt deshalb eine Ergänzung zum Kern des Lernziels.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '3d9bfcf2-8df7-4633-b812-8ed9b632b5da' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Prinzip der Oberflächenvergrößerung (z. B. Darmzotten, Lungenbläschen) zeigt, wie der Bau eines Organs seine Funktion ermöglicht.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Eine große Fläche erleichtert die Aufnahme von Nährstoffen und Sauerstoff, also den Stoffaustausch mit der Umgebung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Der Versuch zeigt, dass die Laubblätter das Organ sind, über das Wasserdampf abgegeben wird. Einem Organ wird so eine Aufgabe zugeordnet, wie es das Konzept beschreibt. Wie das Blatt dafür gebaut ist und warum sein Bau die Abgabe ermöglicht, bleibt im Lernziel jedoch offen. Im Zentrum steht der Vorgang selbst, daher ist der Bezug nur teilweise gegeben.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Die Pflanze gibt Wasserdampf über die Laubblätter an die Umgebung ab, und die Wassertropfen an der übergestülpten Folie machen diesen Stoffaustausch mit der Umwelt direkt sichtbar. Der Versuch zeigt, dass eine Pflanze als offenes System im ständigen Austausch mit ihrer Umgebung steht und Stoffe an sie abgibt. Lernende beobachten selbst, dass der Austausch von Stoffen mit der Umwelt auch bei Pflanzen stattfindet.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'fcb140ff-2f5f-4ade-a1ef-05c7e6fe8822' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Laubblätter sind das Organ, über das Wasserdampf abgegeben wird; der Versuch lenkt den Blick auf diese Aufgabe des Blattes.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Die Pflanze gibt Wasser an die Umgebung ab, und die Wassertropfen an der Folie machen diesen Stoffaustausch mit der Umwelt direkt sichtbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,5,begruendung}', to_jsonb($t$Beobachten mit einer Lupe dient dem Gewinnen von Information über einen Gegenstand, denn die Lupe macht Einzelheiten erkennbar. Das Konzept beschreibt dagegen vor allem, wie Lebewesen selbst Information aufnehmen, weiterleiten und verarbeiten. Das Lernziel gilt dem sachgerechten Umgang mit dem Arbeitsmittel. Der Bezug ist methodisch und schwach, die Zuordnung daher nur vorsichtig.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '0d7ffd09-69cb-4138-a761-d4cde1ce19d9' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,5,begruendung}' = $t$Beobachten mit einer Lupe dient dem Gewinnen von Information über einen Gegenstand; der Bezug ist methodisch und schwach, die Zuordnung daher nur vorsichtig.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Reagenzglas, Becherglas und Pipette unterscheiden sich in Form und Zweck, und ihre Verwendung ergibt sich aus dem Bau des Geräts. Das ähnelt dem Gedanken des Konzepts, dass Gestalt und Funktion zusammenhängen. Das Konzept gilt jedoch Lebewesen und Lebensvorgängen, das Lernziel dem sachgerechten Umgang mit Laborgeräten. Der Bezug ist methodisch und schwach, die Zuordnung daher nur vorsichtig.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'c354c7ec-9d53-4815-9edd-f85491635992' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Reagenzglas, Becherglas und Pipette unterscheiden sich in Form und Zweck; die Verwendung ergibt sich aus dem Bau des Geräts. Der Bezug ist methodisch und schwach, die Zuordnung daher nur vorsichtig.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,5,begruendung}', to_jsonb($t$Messen mit Maßband, Waage oder Thermometer liefert Zahlenwerte als Information über einen Gegenstand. Das Konzept beschreibt aber vor allem, wie Lebewesen Information aufnehmen, weiterleiten und darauf reagieren, und das ist im Lernziel nicht angesprochen. Es geht um den sachgerechten Gebrauch der Messgeräte. Der Bezug ist methodisch und schwach, die Zuordnung daher nur vorsichtig.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '9853fe5c-0acf-4442-b312-0c12e7d9e502' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,5,begruendung}' = $t$Messen liefert Zahlenwerte als Information über einen Gegenstand; der Bezug ist methodisch und schwach, die Zuordnung daher nur vorsichtig.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Die Kiemenatmung der Bachforelle wird als Angepasstheit an den Lebensraum Wasser erläutert. Angepasstheit gilt im Konzept als Ergebnis evolutiver Prozesse, das über viele Generationen durch natürliche Selektion entstanden ist. Als Ergebnis von Evolution wird die Kiemenatmung im Lernziel selbst aber nicht erklärt. Es beschreibt Bau und Ablauf der Atmung, die Frage nach ihrer Entstehung bleibt offen.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Kiemen mit ihren Kiemenblättchen und der dünnen Haut sind ein Bauplan, der den Gasaustausch im Wasser ermöglicht. Das Lernziel verknüpft Bau und Funktion unmittelbar. Die Kiemenblättchen vergrößern die Fläche, an der Sauerstoff aus dem Wasser ins Blut übertritt, und die dünne Haut ermöglicht diesen Übertritt. Lernende bauen die Denkweise auf, von der Gestalt eines Organs auf seine Leistung im Lebensraum zu schließen.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Die Bachforelle nimmt in Wasser gelösten Sauerstoff über die Kiemenblättchen in das Blut auf und gibt Kohlenstoffdioxid ab. Das ist ein Stoffaustausch mit der Umwelt, wie ihn das Konzept für offene Systeme beschreibt: Stoffe werden aufgenommen, genutzt und als Stoffwechselprodukte wieder abgegeben. Lernende erkennen, dass auch ein Lebewesen im Wasser auf den Austausch von Stoffen mit seiner Umwelt angewiesen ist.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '27afe1e7-d609-4a04-90b8-86991b8a4364' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Die Kiemenatmung wird als Angepasstheit an den Lebensraum Wasser betrachtet; als Ergebnis von Evolution wird sie im Lernziel selbst nicht erklärt.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Kiemenblättchen mit dünner Haut sind ein Bauplan, der den Gasaustausch im Wasser ermöglicht; das Lernziel verknüpft Bau und Funktion unmittelbar.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Aufnahme von gelöstem Sauerstoff und Abgabe von Kohlenstoffdioxid sind ein Stoffaustausch mit der Umwelt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die kleinen Öffnungen im Laubblatt sind ein Bauelement, das die Aufnahme von Gas ermöglicht. Das Lernziel verbindet damit eine Struktur mit ihrer Aufgabe, dem Eintritt des Kohlenstoffdioxids in das Blatt. Der Bau der Öffnungen und ihre Einbettung in den Blattaufbau werden nicht untersucht. Der Kern liegt daher eher beim Weg des Stoffes als beim Zusammenhang von Bau und Funktion.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Die Aufnahme von Kohlenstoffdioxid aus der Luft ist ein Stoffaustausch mit der Umwelt und liefert den Ausgangsstoff für den Aufbau energiereicher Stoffe. Das Lernziel beschreibt, wie ein Gas aus der Umgebung über die Laubblätter in die Pflanze gelangt, und legt damit den ersten Schritt der Stoffaufnahme offen. Lernende bauen die Vorstellung auf, dass auch Pflanzen offene Systeme sind, die fortlaufend Stoffe aus ihrer Umwelt aufnehmen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'b168e6bf-f310-4981-b60b-bf77c2b6591a' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die kleinen Öffnungen im Laubblatt sind ein Bauelement, das die Aufnahme von Gas ermöglicht.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Die Aufnahme von Kohlenstoffdioxid aus der Luft ist ein Stoffaustausch mit der Umwelt und liefert den Ausgangsstoff für den Aufbau energiereicher Stoffe.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel verbindet ausdrücklich den Bau der Wurzel mit ihrer Aufgabe: Wurzelhaare vergrößern die Oberfläche und erleichtern so die Stoffaufnahme. Der Zusammenhang selbst ist Lerninhalt und entspricht dem Prinzip der Oberflächenvergrößerung, bei dem eine größere Grenzfläche den Austausch beschleunigt. Lernende bauen die Denkweise auf, von der Gestalt eines Organs auf seine Leistung zu schließen und umgekehrt.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Wasser und Mineralsalze werden aus dem Boden aufgenommen, das ist ein Stoffaustausch mit der Umwelt. Das Lernziel beschreibt damit, wie die Pflanze die Stoffe bezieht, die sie für ihren Stoffwechsel braucht, und setzt am Beginn der Stoffaufnahme an. Lernende erkennen, dass auch Pflanzen als offene Systeme fortlaufend Stoffe mit ihrer Umgebung austauschen und sich ihre Versorgung aus dem Boden erschließen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '1e44162a-d7bd-496f-9b6d-ffcb3c2d4004' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Lernziel verbindet ausdrücklich den Bau der Wurzel mit ihrer Aufgabe: Wurzelhaare vergrößern die Oberfläche und erleichtern so die Stoffaufnahme.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Wasser und Mineralsalze werden aus dem Boden aufgenommen, das ist ein Stoffaustausch mit der Umwelt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Färbung macht sichtbar, in welchen Bereichen der Sprossachse Wasser aufsteigt; der Aufbau der Leitungsbahnen wird dabei erkennbar. Der Versuch zeigt damit, dass bestimmte Bereiche der Sprossachse für den Wassertransport zuständig sind. Das Lernziel formuliert den Zusammenhang von Bau und Funktion jedoch nicht aus. Im Mittelpunkt steht der Nachweis des Wassertransports.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Der Versuch macht den Transport von Wasser durch die Pflanze sichtbar, also den Weg eines Stoffes im Organismus nach der Aufnahme aus der Umwelt. Das gefärbte Wasser zeigt, dass der aufgenommene Stoff die Sprossachse durchläuft und so zu den übrigen Pflanzenteilen gelangt. Lernende ergänzen ihre Vorstellung von der Stoffaufnahme um den Gedanken, dass Stoffe im Körper weitergeleitet werden.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'b9b7dffe-d103-4fd1-b708-38c9cbe192eb' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Färbung macht sichtbar, in welchen Bereichen der Sprossachse Wasser aufsteigt; der Aufbau der Leitungsbahnen wird dabei erkennbar.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Der Versuch macht den Transport von Wasser durch die Pflanze sichtbar, also den Weg eines Stoffes im Organismus nach der Aufnahme aus der Umwelt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Beim Untersuchen mit der Lupe wird der feine Bau der Feder mit ihren Eigenschaften (z. B. leicht, stabil, wärmend) verknüpft. Die Lupe macht Strukturen sichtbar, die Lernende den Leistungen der Feder zuordnen. Das entspricht dem Zusammenhang zwischen Gestalt und Funktion eines Merkmals in seiner Umwelt. Lernende üben, aus dem Bau eines Körperteils auf seine Eigenschaften zu schließen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'a43a1221-2c74-416f-b8c1-8042676f4e8a' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Beim Untersuchen mit der Lupe wird der feine Bau der Feder mit ihren Eigenschaften (z. B. leicht, stabil, wärmend) verknüpft.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Körperliche Tätigkeit verbraucht Energie, die der Körper aus der Nahrung gewinnt; das Lernziel verknüpft Energiebedarf und Nahrungsaufnahme. Damit steht der Weg der Energie von der Nahrung bis zur Leistung des Körpers im Vordergrund, also die Umwandlung der in der Nahrung gebundenen Energie in Bewegung und Wärme. Lernende bauen die Denkweise auf, dass jede Tätigkeit Energie braucht und sich die Ernährung am Energieumsatz des Körpers ausrichten lässt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '0882ce31-5534-4036-b4f2-30fcc3db051e' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Körperliche Tätigkeit verbraucht Energie, die der Körper aus der Nahrung gewinnt; das Lernziel verknüpft Energiebedarf und Nahrungsaufnahme.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug}', $j$[{"begruendung":"Das Lernziel spricht keine Evolution an.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Es wird kein Wachstums- oder Entwicklungsprozess behandelt.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Der Bau von Organen ist hier nicht Thema.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Eine Regelung von Hunger oder Sättigung wird im Lernziel nicht angesprochen.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Mahlzeiten liefern Stoffe und Energie, und der Ernährungskreis hilft, sie in passenden Mengen zusammenzustellen. Das Lernziel berührt damit den Bedarf des Körpers an Stoffen und Energie. Der Bezug ist eher handlungsorientiert als fachlich vertieft. Dem Kern fehlt, was im Körper mit den aufgenommenen Stoffen geschieht.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Informationsweitergabe ist hier nicht Thema.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}]$j$::jsonb), '{basiskonzepte_primaer}', $j$["bk_stoff_energie_umwandlung"]$j$::jsonb), '{basiskonzepte_sekundaer}', $j$[]$j$::jsonb), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'e6642cc4-3679-424f-a637-011e9fa380d8' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Mahlzeiten liefern Stoffe und Energie, und der Ernährungskreis hilft, sie in passenden Mengen zusammenzustellen; der Bezug ist eher handlungsorientiert als fachlich vertieft.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Beim Herstellen eines Beinmodells wird der Aufbau des Beins mit Knochen und Gelenken nachgebaut und damit seine Funktion der Bewegung verständlich. Im Nachbau wird greifbar, wie Knochen und Gelenke zusammenwirken, damit eine Bewegung entsteht. Lernende entwickeln die Denkweise, die Bauteile eines Körpers nach ihrer Aufgabe zu betrachten und die Funktion aus dem Zusammenspiel der Teile zu erklären.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'db52fdd4-6c57-4784-b748-67fe2356fd67' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Beim Herstellen eines Beinmodells wird der Aufbau des Beins mit Knochen und Gelenken nachgebaut und damit seine Funktion der Bewegung verständlich.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Verhalten der Wassertropfen hängt von der Beschaffenheit der Materialien ab (z. B. glatt, gewachst, Laubblatt); der Versuch verknüpft Oberflächenbau und Verhalten. Lernende vergleichen Oberflächen und sehen, wie deren Eigenschaften das Benetzen oder Abrollen bestimmen. Biologische Strukturen kommen nur mit den Laubblättern vor, ihre Funktion für die Pflanze wird im Lernziel nicht angesprochen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '8923ec54-73d4-49a3-9a60-3160a2ef3a3d' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Verhalten der Wassertropfen hängt von der Beschaffenheit der Materialien ab (z. B. glatt, gewachst, Laubblatt); der Versuch verknüpft Oberflächenbau und Verhalten.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Ob Wasser eine Oberfläche benetzt, hängt von der Beschaffenheit (wasserliebend, glatt) und den Kräften zwischen den Teilchen ab; das Lernziel verbindet also Aufbau und Verhalten. Die Eigenschaft der Oberfläche entscheidet, ob Adhäsion oder Kohäsion überwiegt. Es bleibt aber eine physikalische Betrachtung ohne Bezug zu Lebewesen, deshalb berührt das Lernziel das Konzept nur am Rande.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '1a1e4043-aaec-4be9-9c7c-aeb9fbb7ade2' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Ob Wasser eine Oberfläche benetzt, hängt von der Beschaffenheit (wasserliebend, glatt) und den Kräften zwischen den Teilchen ab; das Lernziel verbindet also Aufbau und Verhalten.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Der Klassenvergleich macht die Vielfalt der Körperbedeckungen sichtbar, Evolutionsprozesse selbst werden aber nicht behandelt. Feuchte Haut, Hornschuppen, Federn und Haare sind Merkmale, die sich zwischen den Wirbeltierklassen unterscheiden, und diese Vielfalt ist ein Ausgangspunkt evolutiver Betrachtungen. Wie die Unterschiede entstanden sind, bleibt im Lernziel offen.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Schleimige Haut, Hornschuppen, Federn und Haare sind unterschiedlich gebaute Körperbedeckungen mit eigenen Aufgaben wie Schutz. Bau und Funktion werden direkt verglichen. Das Lernziel stellt die Klassen gegenüber und fragt nach Gemeinsamkeiten und Unterschieden. Lernende erkennen so, dass verschiedene Bauweisen derselben Körperregion unterschiedliche Leistungen erbringen, und üben, von der Gestalt eines Merkmals auf seine Aufgabe zu schließen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '898da8bd-8e24-45e2-8c6d-297faa6d67c2' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Der Klassenvergleich macht die Vielfalt der Körperbedeckungen sichtbar, Evolutionsprozesse selbst werden aber nicht behandelt.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Schleimige Haut, Hornschuppen, Federn und Haare sind unterschiedlich gebaute Körperbedeckungen mit eigenen Aufgaben wie Schutz. Bau und Funktion werden direkt verglichen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Gleiche Grundbauteile in verschiedener Ausprägung verweisen auf Verwandtschaft und Vielfalt der Wirbeltiere. Das Lernziel führt diesen Gedanken aber nicht aus. Schädel, Wirbelsäule, Gürtel und Gliedmaßenskelett folgen bei allen Klassen demselben Grundmuster, das ist der Ansatz zu Homologie und zur Erhaltung von Bauplänen. Dass dieses Muster auf gemeinsame Vorfahren zurückgeht, wird nicht thematisiert.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Skelettabschnitte sind je nach Fortbewegung unterschiedlich ausgeprägt. Das Lernziel nennt den Zusammenhang von Bau und Funktion ausdrücklich. Schädel, Wirbelsäule, Gürtel sowie Arm- und Beinskelett werden der Fortbewegung der jeweiligen Klasse zugeordnet. Lernende erkennen, dass ein gleicher Grundbau in unterschiedlicher Ausprägung unterschiedliche Leistungen ermöglicht, und betrachten Bau und Funktion in der jeweiligen Umwelt gemeinsam.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '3551ae70-9ada-48ba-8f22-7c221efc42e0' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Gleiche Grundbauteile in verschiedener Ausprägung verweisen auf Verwandtschaft und Vielfalt der Wirbeltiere. Das Lernziel führt diesen Gedanken aber nicht aus.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Skelettabschnitte sind je nach Fortbewegung unterschiedlich ausgeprägt. Das Lernziel nennt den Zusammenhang von Bau und Funktion ausdrücklich.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel führt das Verhalten von Wasser an einer Glasfläche auf die Kräfte zwischen den Teilchen zurück, also auf den Aufbau auf Teilchenebene. Die Adhäsion zwischen Wasser und Glas erklärt die Benetzung, damit wird eine Eigenschaft aus dem Bau der Stoffe abgeleitet. Es bleibt eine physikalische Betrachtung ohne Bezug zu Lebewesen oder biologischen Strukturen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'a2e4828f-19e7-4a63-905f-ca077bb2b3bf' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Lernziel führt das Verhalten von Wasser an einer Glasfläche auf die Kräfte zwischen den Teilchen zurück, also auf den Aufbau auf Teilchenebene.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Nahrung wird aufgenommen, in Bausteine zerlegt und ins Blut aufgenommen. Das ist Stoffumwandlung und Stoffaustausch mit der Umwelt. Das Lernziel verfolgt den Weg der Nahrung vom Aufnehmen über das Zerlegen bis zum Übertritt der Bausteine ins Blut, also eine Folge von Umwandlung und Weiterleitung von Materie. Lernende bauen die Vorstellung auf, dass Lebewesen die Stoffe aus der Nahrung umbauen, bevor der Körper sie nutzen kann.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'd25ee4df-21a1-4a2f-95c7-fee510abbd63' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Nahrung wird aufgenommen, in Bausteine zerlegt und ins Blut aufgenommen. Das ist Stoffumwandlung und Stoffaustausch mit der Umwelt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Der Zusammenhang von Bauweise und Stabilität wird an Modellen und an Vorbildern aus der Natur (Knochenquerschnitt, Palmenblatt) untersucht. Das ist Struktur-Funktions-Denken. Lernende vermuten, wie die Bauweise die Stabilität beeinflusst, testen verschiedene Faltkonstruktionen und Materialien und übertragen das Prinzip aus der Natur auf ihr Modell. Sie erfahren, dass eine Eigenschaft wie Stabilität von der Form eines Bauteils abhängt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '32fc1d8b-ff0b-4596-9d8a-fd87daf1964e' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Der Zusammenhang von Bauweise und Stabilität wird an Modellen und an Vorbildern aus der Natur (Knochenquerschnitt, Palmenblatt) untersucht. Das ist Struktur-Funktions-Denken.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Das Nennen von Stoffen, aus denen Körper bestehen, ist der Einstieg in das Stoffverständnis, auf dem spätere Aussagen zu Stoffeigenschaften und Stoffumwandlungen aufbauen. Das Lernziel bleibt beim Benennen der Stoffe. Der Kern des Konzepts, nämlich dass Stoffe aufgenommen, umgewandelt oder abgegeben werden, kommt hier noch nicht vor.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'b67b597b-51a4-4ae7-a3ce-54b785d4cba9' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Das Nennen von Stoffen, aus denen Körper bestehen, ist der Einstieg in das Stoffverständnis, auf dem spätere Aussagen zu Stoffeigenschaften und Stoffumwandlungen aufbauen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Das Lernziel veranschaulicht mit Kugeln, aus welchen Teilchen Stoffe bestehen und wie sie sich bewegen. Das Kugelmodell legt die Grundlage dafür, Stoffe und ihre Bewegung auf Teilchenebene zu denken, und darauf bauen spätere Überlegungen zu Stoff- und Energieumsätzen auf. Der Kern liegt allerdings in der Physik der Stoffe. Ein Umwandlungsvorgang wird hier nicht beschrieben.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'bb13b551-26a3-453d-99df-a8916d49ca52' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Das Kugelmodell legt die Grundlage dafür, Stoffe und ihre Bewegung auf Teilchenebene zu denken. Darauf bauen spätere Überlegungen zu Stoff- und Energieumsätzen auf. Der Kern liegt allerdings in der Physik der Stoffe und nicht bei einem Umwandlungsvorgang.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Anordnung der Teilchen bestimmt die Eigenschaften des Zustands. Das ist ein Struktur-Eigenschaft-Zusammenhang, aber im Bereich der Physik. Fest, flüssig und gasförmig unterscheiden sich durch Anordnung und Bewegung der Teilchen, das entspricht dem Gedanken, dass der Aufbau eines Systems sein Verhalten bestimmt. Biologische Strukturen und ihre Funktion für Lebewesen kommen im Lernziel nicht vor.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Anordnung und Bewegung der Teilchen werden mit den Aggregatzuständen verknüpft. Das ist die Grundlage für Stoff- und Energiebetrachtungen, bleibt aber bei einem physikalischen Vorgang. Lernende gewinnen ein Teilchenbild, auf dem spätere Überlegungen zu Stoffaufnahme, Umwandlung und Abgabe in Lebewesen aufbauen können. Aufnahme, Umwandlung oder Abgabe von Stoffen durch ein Lebewesen kommen im Lernziel selbst aber nicht vor.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'e427a79b-2a17-4e87-8f44-7fcdc3a245f9' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Anordnung der Teilchen bestimmt die Eigenschaften des Zustands. Das ist ein Struktur-Eigenschaft-Zusammenhang, aber im Bereich der Physik.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Anordnung und Bewegung der Teilchen werden mit den Aggregatzuständen verknüpft. Das ist die Grundlage für Stoff- und Energiebetrachtungen, bleibt aber bei einem physikalischen Vorgang.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Die Angepasstheit der Bachforelle an das Wasser ist ein Ergebnis der Stammesgeschichte; das Lernziel spricht diese aber nicht an. Körperform, Schuppen und Flossen sind Merkmale, die das Schwimmen erleichtern und im Lauf evolutiver Prozesse entstanden sind. Wie und warum sich solche Merkmale in Populationen verbreitet haben, bleibt im Lernziel offen.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Körperform, Haut, Schuppen, Flossen und Schwimmblase werden ausdrücklich mit Schwimmen und Schweben im Wasser verknüpft. Das ist Bau-Funktions-Denken im Kern. Das Lernziel ordnet jedem Merkmal der Bachforelle eine Leistung in ihrem Lebensraum zu, etwa der Spindelform das Schwimmen und der Schwimmblase das Schweben. Lernende üben, Merkmale eines Tieres über ihre Funktion in der Umwelt zu erklären.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'e3c83b1a-d4c7-4e4c-9f66-5af03b4f8ecd' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Die Angepasstheit der Bachforelle an das Wasser ist ein Ergebnis der Stammesgeschichte; das Lernziel spricht diese aber nicht an.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Körperform, Haut, Schuppen, Flossen und Schwimmblase werden ausdrücklich mit Schwimmen und Schweben im Wasser verknüpft. Das ist Bau-Funktions-Denken im Kern.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Am Funktionsmodell der Hand wird untersucht, wie Bauteile zusammenwirken und welche Bewegung daraus entsteht. Das ist Struktur-Funktions-Denken. Das Lernziel nennt aber nur das Untersuchen des Modells. Welche Teile der Hand es abbildet und wie Bau und Bewegung zusammenhängen, wird nicht vorgegeben. Der Bezug zum Kern des Konzepts ist daher nur teilweise gegeben.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '28dcf59e-4f6d-47e7-a792-b5572e41a86b' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Am Funktionsmodell der Hand wird untersucht, wie Bauteile zusammenwirken und welche Bewegung daraus entsteht. Das ist Struktur-Funktions-Denken.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Der von Pflanzen gebildete Sauerstoff wird von vielen Lebewesen für die Atmung gebraucht. Das verbindet Stoffbildung und Stoffaustausch zwischen Lebewesen. Der Sauerstoff, den die Pflanze bildet, dient Tieren und anderen Lebewesen als Ausgangsstoff für die Atmung und geht so von einem Lebewesen auf andere über. Lernende ordnen den Sauerstoff als einen Stoff ein, der von einem Lebewesen gebildet und von anderen gebraucht wird.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '9362be8c-4be7-4a00-bb06-7a1c2eb93eee' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Der von Pflanzen gebildete Sauerstoff wird von vielen Lebewesen für die Atmung gebraucht. Das verbindet Stoffbildung und Stoffaustausch zwischen Lebewesen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Das Lernziel beschreibt den gesamten Weg von der Bildung der Eizellen im Eierstock und der Samenzellen im Hoden über die innere Befruchtung und die Entwicklung des Embryos bis zur Geburt und zum erwachsenen Tier. Damit liegen Fortpflanzung und Lebenszyklus im Kern des Basiskonzepts. Lernende bauen die Denkweise auf, dass ein neues Lebewesen aus einer befruchteten Eizelle entsteht und aufeinanderfolgende Entwicklungsphasen durchläuft.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Eierstock und Hoden haben jeweils eine eigene Aufgabe bei der Bildung der Keimzellen, sodass Organ und Leistung hier zusammengehören. Dieser Zusammenhang von Bau und Funktion wird im Lernziel jedoch nur am Rand berührt. Im Mittelpunkt stehen der Ablauf der Fortpflanzung und die Entwicklung bis zum erwachsenen Tier, der Organbau selbst wird nicht genauer betrachtet.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '4c61176b-121e-4efa-a9d6-c0cf100a1314' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Das Lernziel beschreibt den Weg von der Bildung der Keimzellen über die Befruchtung und die Entwicklung des Embryos bis zum erwachsenen Tier. Das ist Fortpflanzung und Individualentwicklung im Kern.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Eierstock und Hoden haben jeweils eine eigene Aufgabe bei der Bildung der Keimzellen, doch der Organbau steht nicht im Mittelpunkt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Die Geschlechtsorgane sind die Voraussetzung der Fortpflanzung, mit der ein neuer Entwicklungszyklus beginnt. Das Lernziel verlangt jedoch nur, Bau und Funktionen der weiblichen und männlichen Organe zu nennen. Auf Entwicklungsvorgänge wie die Entwicklung des Embryos geht es nicht im Einzelnen ein, deshalb bleibt der Bezug zur Individuellen Entwicklung am Rand.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel verlangt, den Bau der weiblichen und männlichen Geschlechtsorgane mit ihren jeweiligen Aufgaben zu verbinden. Damit steht der Zusammenhang zwischen dem Aufbau eines Organs und der Leistung, die es erbringt, unmittelbar im Zentrum. Lernende bauen die Denkweise auf, von der Struktur eines Organs auf seine Aufgabe zu schließen und umgekehrt zu fragen, welcher Bau eine bestimmte Funktion ermöglicht.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '0903cb2e-b634-4fd2-a542-c0c4d870f71e' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Die Geschlechtsorgane sind Voraussetzung der Fortpflanzung; das Lernziel nennt jedoch nur Bau und Funktion und geht auf Entwicklungsvorgänge nicht im Einzelnen ein.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Lernziel verlangt, den Bau der Geschlechtsorgane mit ihren jeweiligen Aufgaben zu verbinden, also unmittelbar den Zusammenhang von Bau und Funktion.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Mit der Lupe werden Form und Anordnung der Haken und Schlaufen an Haft- und Klettband erkennbar, und genau diese Gestalt erklärt später das Haften. Das Betrachten liefert damit die Beobachtungsgrundlage für den Zusammenhang von Struktur und Funktion. Die Deutung dieses Zusammenhangs folgt jedoch erst in späteren Schritten und gehört noch nicht zu diesem Lernziel.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '37e0e2e7-1123-43c4-beea-a7cef6ece683' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Mit der Lupe werden Form und Anordnung von Haken und Schlaufen erkennbar, die das Haften erklären; die Deutung des Zusammenhangs folgt erst in späteren Schritten.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug}', $j$[{"begruendung":"Das Lernziel ist fachunabhängig formuliert; ein Evolutionsbezug entsteht erst durch die gewählten Inhalte.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Lernziel beschreibt eine Arbeitsweise und keinen Entwicklungsprozess von Lebewesen.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Lernziel beschreibt eine Arbeitsweise und keinen biologischen Zusammenhang von Bau und Funktion.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Lernziel beschreibt eine Arbeitsweise und keinen Steuerungs- oder Regelungsvorgang.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Lernziel beschreibt eine Arbeitsweise und keinen Stoff- oder Energieumsatz.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Lernziel selbst spricht dieses Basiskonzept nicht an.","basiskonzept_id":"bk_information_komm