unikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}]$j$::jsonb), '{basiskonzepte_primaer}', $j$[]$j$::jsonb), '{basiskonzepte_sekundaer}', $j$[]$j$::jsonb), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '3c647da4-c06a-4e96-8c68-ef3c18e7f38c' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,5,begruendung}' = $t$Es geht um das Umsetzen einer Information von einer Form in eine andere, etwa von Text in Schema; die Nähe zum biologischen Basiskonzept Information und Kommunikation ist nur begrifflich.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die biegsamen Widerhaken der Klettfrucht erklären, warum sie am Fell von Tieren haftet und sich dennoch immer wieder lösen lässt, ohne abzubrechen. Das Lernziel verknüpft die Gestalt der Haken damit unmittelbar mit ihrer Wirkung, wie es das Unterkonzept der morphologischen und anatomischen Angepasstheit beschreibt. Lernende bauen die Denkweise auf, aus der Form eines Merkmals auf seine Leistung zu schließen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '64cb5010-b6ca-4dde-8c1e-8eebff6220bd' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die biegsamen Widerhaken der Klettfrucht erklären, warum sie am Fell haftet und sich wieder lösen lässt: Das Lernziel verknüpft Form und Wirkung unmittelbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Klettfrucht und Klettverschluss haben das Prinzip gemeinsam, dass biegsame Haken sich verhaken und wieder lösen lassen. Der Vergleich zeigt, dass der Zusammenhang von Form und Wirkung bei einem Lebewesen und bei einem technischen Gegenstand derselbe ist, und trifft damit den Kern des Basiskonzepts. Lernende bauen die Denkweise auf, dass gleiche Strukturen gleiche Leistungen ermöglichen, in der Natur wie in der Technik.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '106ef99a-bb82-42a2-b505-b4503b9fbe85' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Gemeinsam ist Klettfrucht und Klettverschluss das Prinzip verhakender, biegsamer Haken; der Vergleich macht den Zusammenhang von Form und Wirkung in zwei Bereichen sichtbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das erkannte Prinzip der biegsamen Haken wird auf Klettverschlüsse für Schuhe und Jacken angewandt, die sich leicht und beliebig häufig öffnen und schließen lassen. Dabei wird der Zusammenhang von Form und Funktion genutzt. Das Erkennen und Erklären dieses Zusammenhangs gehört zu einem früheren Schritt, hier steht die Anwendung auf technische Objekte im Vordergrund.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'ff15ab65-9ac2-4fe8-b4e8-834934e3a85b' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das erkannte Prinzip der biegsamen Haken wird auf neue Anwendungen wie Schuhe und Jacken angewandt; dabei steht die Nutzung des Zusammenhangs von Form und Funktion im Vordergrund.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Im Funktionsmodell aus einem Kunststoffstreifen mit flexiblen Widerhäkchen und einem Streifen mit Schlaufen wird geprüft, wie Form und Material das Haften bestimmen, unter anderem bei Zugbelastung. Damit kommt der Zusammenhang von Struktur und Funktion beim Erproben vor. Der Schwerpunkt liegt auf dem Bauen und Prüfen der technischen Umsetzbarkeit. Das Erklären des Zusammenhangs steht nicht im Mittelpunkt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'ae7ba53f-0e4b-4cce-b3bd-7a9dba4a7de6' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Im Funktionsmodell aus Streifen mit Widerhäkchen und Schlaufen wird geprüft, wie Form und Material das Haften bestimmen; der Schwerpunkt liegt auf dem Bauen und Prüfen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug}', $j$[{"begruendung":"Dieses physikalische Lernziel hat keinen Bezug zur Evolution.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Entwicklungsprozesse von Lebewesen kommen in diesem Lernziel nicht vor.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Lernziel selbst spricht dieses Basiskonzept nicht an.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Steuerungs- oder Regelungsvorgänge sind hier nicht Gegenstand.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Lernziel selbst spricht dieses Basiskonzept nicht an.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Informationsübertragung oder Kommunikation spielt hier keine Rolle.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}]$j$::jsonb), '{basiskonzepte_primaer}', $j$[]$j$::jsonb), '{basiskonzepte_sekundaer}', $j$[]$j$::jsonb), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'c3f43b65-83ad-45ba-81c5-44bf211898d8' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Eigenschaft Abperlen wird aus dem Verhalten der Teilchen und der Oberfläche begründet, ähnlich wie in der Biologie Eigenschaften aus dem Aufbau erklärt werden.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Bienenwaben, Knochen und Palmenblätter erreichen hohe Stabilität bei geringem Materialeinsatz durch ihre Bauweise, zum Beispiel durch Faltung. Das Lernziel verknüpft die Struktur dieser Vorbilder damit unmittelbar mit ihrer Wirkung, wie es das Unterkonzept der morphologischen und anatomischen Angepasstheit beschreibt. Lernende bauen die Denkweise auf, die Festigkeit eines Körpers auch aus seiner Form zu erklären.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '20e3b63e-d0fb-4494-bb1f-212c703aada2' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Bienenwaben, Knochen und Palmenblätter erreichen Stabilität bei wenig Material durch ihre Bauweise, zum Beispiel Faltung; das Lernziel verknüpft Struktur und Wirkung unmittelbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Gemeinsam ist biologischem Vorbild und technischer Umsetzung das Prinzip hoher Stabilität bei geringem Materialeinsatz durch die Form. Der Vergleich macht sichtbar, dass der Zusammenhang von Struktur und Wirkung in der Natur und in der Technik derselbe ist, und trifft damit den Kern des Basiskonzepts. Lernende bauen die Denkweise auf, ein Strukturprinzip in verschiedenen Bereichen wiederzuerkennen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '3547211f-fa6b-41c5-8f2d-309d0de310a7' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Gemeinsam ist Vorbild und Technik das Prinzip hoher Stabilität bei geringem Materialeinsatz durch die Form; der Vergleich macht den Zusammenhang von Struktur und Wirkung sichtbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das erkannte Prinzip stabiler, leichter Strukturen wird auf Brücken, Dächer und Verpackungsmaterialien übertragen. Dabei wird der Zusammenhang von Struktur und Festigkeit für neue technische Objekte genutzt. Das Erkennen und Erklären dieses Zusammenhangs am Vorbild gehört zu einem früheren Schritt, hier steht die Anwendung auf technische Objekte im Vordergrund.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '9bae9d82-d179-4de5-9b40-2b4115660947' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das erkannte Prinzip stabiler, leichter Strukturen wird auf Brücken, Dächer und Verpackungen übertragen; dabei steht die Nutzung des Zusammenhangs von Struktur und Festigkeit im Vordergrund.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Beim Prüfen des Zusammenhangs zwischen Wölb- und Faltungsstrukturen und der Festigkeit unter Druckbelastung wird unmittelbar untersucht, wie die Struktur die Belastbarkeit bestimmt. Die selbstversteifende Wirkung am Funktionsmodell macht den Zusammenhang von Bau und Leistung überprüfbar. Lernende bauen die Denkweise auf, eine Vermutung über die Wirkung einer Form am Modell zu belegen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '62856509-d3db-48d7-a031-052415d71564' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Beim Prüfen des Zusammenhangs zwischen Wölb- und Faltungsstrukturen und Festigkeit wird unmittelbar untersucht, wie die Struktur die Belastbarkeit bestimmt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Stärke und Traubenzucker sind Nährstoffe, die Lebewesen aufnehmen und umwandeln. Ihre Löslichkeit ist eine Stoffeigenschaft, die später für das Verständnis von Verdauung und Stofftransport wichtig wird. Das Lernziel nennt jedoch nur das Experiment zur Löslichkeit. Aufnahme und Umwandlung der Stoffe im Organismus bleiben hier unberührt, der Bezug zum Basiskonzept ist vorbereitend.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '82864b56-e251-42cb-9ad9-c3ab55780559' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Stärke und Traubenzucker sind Nährstoffe; ihre Löslichkeit ist eine Stoffeigenschaft, die später für das Verständnis von Verdauung und Stofftransport wichtig wird, auch wenn das Lernziel nur das Experiment nennt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Wachsnoppen der Blattoberfläche erklären das Abperlen der Wassertropfen, die dabei Schmutzteilchen mitnehmen. Das Lernziel verknüpft die Oberflächenstruktur des Laubblatts damit unmittelbar mit dieser Wirkung, wie es das Unterkonzept der morphologischen und anatomischen Angepasstheit beschreibt. Lernende bauen die Denkweise auf, eine Eigenschaft wie die Selbstreinigung aus der Feinstruktur einer Oberfläche zu erklären.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '8cf4e6fd-47d0-4401-8190-47cbeef4da92' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Wachsnoppen der Blattoberfläche erklären das Abperlen und die Selbstreinigung; das Lernziel verknüpft Oberflächenstruktur und Wirkung unmittelbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Gemeinsam ist Laubblatt und technischer Oberfläche das Prinzip der Noppenstruktur, die das Abperlen bewirkt. Der Vergleich macht sichtbar, dass der Zusammenhang von Struktur und Wirkung in der Natur und in der Technik derselbe ist, und trifft damit den Kern des Basiskonzepts. Lernende bauen die Denkweise auf, aus der Beschaffenheit einer Oberfläche auf ihre Leistung zu schließen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'b4facf84-0b58-4684-ac68-d29e2b010dcd' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Gemeinsam ist Blatt und technischer Oberfläche das Prinzip der Noppenstruktur, die das Abperlen bewirkt; der Vergleich macht den Zusammenhang von Struktur und Wirkung sichtbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das erkannte Prinzip der genoppten Oberfläche wird auf Autolacke, wasserabweisende Zeltplanen, Wetterjacken und Schuhe übertragen. Dabei wird der Zusammenhang von Struktur und Wirkung genutzt. Das Erkennen und Erklären dieses Zusammenhangs am Vorbild gehört zu einem früheren Schritt, hier steht die Anwendung auf technische Objekte im Vordergrund.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '2601b401-10b2-4b62-8064-905a7fdeb104' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das erkannte Prinzip der genoppten Oberfläche wird auf Autolacke, Zeltplanen, Wetterjacken und Schuhe übertragen; dabei steht die Nutzung des Zusammenhangs von Struktur und Wirkung im Vordergrund.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Im Funktionsmodell wird das Verhalten von Wasser auf einer genoppten, wasserabweisenden Oberfläche geprüft, und verschiedene Materialien mit entsprechenden Oberflächen werden verglichen. Dabei zeigt sich, wie die Oberflächenstruktur die Wirkung bestimmt. Der Schwerpunkt liegt auf dem Bauen und Vergleichen der Materialien. Das Erklären des Zusammenhangs von Struktur und Wirkung steht hier nicht im Mittelpunkt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '92510810-6615-45a6-ae87-ec4061070e5a' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Im Funktionsmodell wird das Verhalten von Wasser auf einer genoppten, wasserabweisenden Oberfläche geprüft; der Schwerpunkt liegt auf dem Bauen und Vergleichen verschiedener Materialien.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Elektrische Leitfähigkeit, Löslichkeit, Wärmeleitfähigkeit sowie Schmelz- und Siedetemperatur kennzeichnen Reinstoffe auf der Stoffebene. Schmelzen und Sieden sind Aggregatzustandsänderungen, die Wärmezufuhr brauchen, und die Wärmeleitfähigkeit betrifft die Weitergabe von Energie. Damit berührt das Lernziel Stoff- und Energiezustände. Die Umwandlung von Stoffen im Stoffwechsel von Lebewesen kommt im Lernziel nicht vor.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '65613bb2-2e3b-4b33-a17b-a285a8cc5b23' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Leitfähigkeit, Löslichkeit, Wärmeleitfähigkeit sowie Schmelz- und Siedetemperatur beschreiben Stoffe auf der Stoffebene und berühren Aggregatzustandsänderungen und Wärmeübertragung, also Stoff- und Energiezustände.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Beim Variieren der Maschengröße erfahren Lernende, dass die Bauform eines Netzes bestimmt, wie viel Wasser es aus dem Nebel auffangen kann. Das ist der Kern des Konzepts: Eine Struktur, hier die Maschengröße, hängt mit ihrer Funktion zusammen. Weil das Modell verändert und auf Effizienz untersucht wird, bauen Lernende die Denkweise auf, vom Bau auf die Leistung zu schließen, wie in der Bionik nach biologischem Vorbild.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Das Auffangen von Wasser aus Nebel betrifft Kondensation und Wassertransport, also Stoffbewegung, die beim Untersuchen der Effizienz gemessen und verglichen wird. Damit berührt das Lernziel den Austausch von Stoffen zwischen Luft und Modell. Der Stoffwechsel von Lebewesen und die Umwandlung von Energie spielen beim Modellbau keine Rolle, sodass das Konzept nur am Rand getroffen wird.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '94979035-193d-4048-8c93-e2b6e9695c90' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Beim Variieren der Maschengröße erfahren Lernende, dass die Bauform eines Netzes seine Funktion (Wasser aus Nebel auffangen) bestimmt, ein Struktur-Funktion-Zusammenhang nach biologischem Vorbild.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Das Auffangen von Wasser aus Nebel betrifft Kondensation und Wassertransport, also Stoffbewegung, die gemessen und verglichen wird.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Das Modell zum Verdauungsvorgang macht sichtbar, dass Stärke bei der Verdauung in kleinere Bausteine zerlegt wird. Stärke wird damit in andere Stoffe umgewandelt. Das ist Stoffumwandlung im Sinne des Basiskonzepts, nach dem Lebewesen Stoffe aufnehmen und umwandeln. Lernende bauen die Denkweise auf, Ernährung als Umbau von Nahrungsstoffen im Körper zu verstehen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '9c86523f-3ba0-44f8-853d-48fedcd7263d' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Das Modell macht sichtbar, dass Stärke bei der Verdauung in kleinere Bausteine zerlegt wird, also in andere Stoffe umgewandelt wird, die der Körper aufnehmen kann.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$In den Modellversuchen zeigt sich, dass die Beschaffenheit und Form einer Oberfläche bestimmt, wie Wasser darauf reagiert: wasserliebend oder wasserabweisend, glatt oder genoppt, gewachst oder unbehandelt. Das ist ein Zusammenhang von Struktur und Funktion, wie ihn das Basiskonzept beschreibt. Lernende erfahren, dass sich aus dem Bau einer Oberfläche ihr Verhalten ableiten lässt. Diese Denkweise wird später am biologischen Vorbild genutzt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'f1db87b6-266f-4667-8e99-6cf10eeff82c' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Versuche zeigen, dass die Beschaffenheit und Form einer Oberfläche (glatt, genoppt, gewachst) bestimmt, wie Wasser darauf reagiert, ein Struktur-Funktion-Zusammenhang, der später am biologischen Vorbild genutzt wird.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Die Flügeldecken lassen sich als Angepasstheit des Käfers an seinen trockenen Lebensraum verstehen, also als Merkmal, das sich über viele Generationen in der Population durchgesetzt hat, weil seine Träger in dieser Umwelt häufiger überlebten und sich fortpflanzten. Das Lernziel behandelt den Käfer aber nur als biologisches Vorbild. Wie die Angepasstheit über Variation und Selektion in Populationen entstanden ist, wird nicht angesprochen.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Höcker und Rillen auf den Flügeldecken sind Bauelemente, deren Form und Oberflächeneigenschaft das Lernziel direkt mit einer Funktion verknüpft: Höcker mit vergrößerter Oberfläche lassen Wasserdampf kondensieren, Rillen leiten die Tröpfchen zum Mund. Das entspricht dem Zusammenhang von Gestalt und Leistung einer Struktur. Lernende bauen die Denkweise auf, aus dem Bau eines Merkmals auf seine Funktion zu schließen.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Der Käfer gewinnt Wasser, indem Wasserdampf aus der Luft an den Flügeldecken kondensiert und zum Mund geleitet wird. Das ist eine Stoffaufnahme aus der Umgebung und berührt damit den Stoffaustausch mit der Umwelt. Was der Käfer anschließend mit dem Wasser im Stoffwechsel macht, und welche Energie dafür nötig ist, bleibt im Lernziel offen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'b5baec2f-4d0b-465f-8af2-5a73e39202a1' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Die Flügeldecken lassen sich als Angepasstheit des Käfers an seinen trockenen Lebensraum verstehen, die das Lernziel aber nur als biologisches Vorbild behandelt.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Höcker und Rillen auf den Flügeldecken sind Bauelemente, deren Form und Oberflächeneigenschaft direkt mit der Funktion (Kondensieren und Transportieren von Wasser) verknüpft wird.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Der Käfer gewinnt Wasser durch Kondensation von Wasserdampf und leitet es zum Mund, also eine Stoffaufnahme aus der Umgebung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das am Käfer erkannte Prinzip, eine Fläche zum Kondensieren und Rillen zum Weiterleiten, wird in Netze und Auffangvorrichtungen für Nebelkollektoren übersetzt. Lernende übertragen damit einen Zusammenhang von Bau und Leistung vom Lebewesen auf ein technisches Objekt und nutzen Struktur und Funktion für einen Zweck. Sie bauen die Denkweise auf, dass sich eine Funktion über ihren Bau beschreiben und auf anderes Material übertragen lässt.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Nebelkollektoren gewinnen Trinkwasser durch Kondensation und Auffangen, also durch einen technischen Stofftransport aus der Luft. Das berührt den Austausch von Stoffen mit der Umgebung. Da es um ein technisches Objekt geht, fehlen der Bezug zu lebenden Systemen und die Umwandlung von Stoffen und Energie im Stoffwechsel, die den Kern des Basiskonzepts bilden.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '207e30e7-76a4-4dc7-bdd0-b3cc18e714c3' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das am Käfer erkannte Prinzip (Fläche zum Kondensieren, Rillen zum Weiterleiten) wird in Netze und Auffangvorrichtungen übersetzt, also Struktur und Funktion für einen Zweck genutzt.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Nebelkollektoren gewinnen Trinkwasser durch Kondensation und Auffangen, ein technischer Stofftransport aus der Luft.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Im Funktionsmodell wird geprüft, ob die Gestaltung von Netz und Ablaufrinne die gewünschte Funktion erfüllt, also Wasserdampf zu kondensieren und das Wasser aufzufangen. Die Menge des gewonnenen Wassers wird an verschiedenen Netzen verglichen. So prüfen Lernende, ob der vermutete Zusammenhang von Bau und Wirkung trägt, und bauen die Denkweise auf, Annahmen über Struktur und Funktion am Modell zu testen.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Kondensation von Wasserdampf, Ablaufen und Auffangen sowie das Messen der gewonnenen Wassermenge betreffen Stoffbewegung und Stoffgewinnung aus der Luft. Das Lernziel berührt damit den Stoffaustausch, bleibt aber bei einem technischen Funktionsmodell. Die Umwandlung von Stoffen und Energie in Lebewesen wird nicht thematisiert.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '2e690536-c76e-44fb-8882-fd24dabcae3c' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Im Funktionsmodell wird geprüft, ob die Gestaltung von Netz und Rinne die gewünschte Funktion erfüllt, also ob der Zusammenhang von Bau und Wirkung trägt.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Kondensation von Wasserdampf, Ablaufen und Auffangen sowie das Messen der gewonnenen Wassermenge betreffen Stoffbewegung und Stoffgewinnung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Ob ein Material Flüssigkeit aufsaugt oder dies verhindert, hängt von seiner Struktur ab. Beim Schwamm ermöglichen feine Poren die Kapillarität, bei gebranntem Ton im Bauwesen wird sie verhindert. Das Lernziel verlangt, diesen Zusammenhang von Bau und Wirkung zu begründen. Lernende bauen die Denkweise auf, Eigenschaften und Leistungen eines Materials aus seinem inneren Aufbau abzuleiten.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Das Aufsteigen und Aufnehmen von Flüssigkeit in feinen Hohlräumen ist ein Stofftransport, der durch Kräfte zwischen den Teilchen erklärt wird. Das Lernziel berührt damit die Bewegung eines Stoffes, die hier physikalisch begründet wird. Die Aufnahme, Umwandlung und Abgabe von Stoffen durch Lebewesen und ihr Energieumsatz stehen im Lernziel nicht im Vordergrund.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'e1d39529-ff72-4c16-ada7-b9ac5ae05132' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Ob ein Material Flüssigkeit aufsaugt oder nicht, hängt von seiner Struktur (feine Poren, gebrannter Ton) ab, ein Zusammenhang von Bau und Wirkung.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Das Aufsteigen und Aufnehmen von Flüssigkeit in feinen Hohlräumen ist ein Stofftransport, der durch Kräfte zwischen den Teilchen erklärt wird.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Oberflächenspannung lässt sich auf die Anordnung und Anziehung der Wasserteilchen zurückführen. Das ist ein erster Hinweis darauf, dass der Aufbau eines Stoffes seine Eigenschaft bestimmt. Im Experiment geht es um eine Stoffeigenschaft. Biologische Strukturen und deren Funktion, etwa von Organen oder Körperbau, kommen im Lernziel nicht vor, daher wird der Kern des Konzepts nur angedeutet.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Der zugesetzte Stoff Spülmittel verändert eine Stoffeigenschaft des Wassers, die Oberflächenspannung, und der Tropfen auf der Glasplatte zeigt diese Wirkung sichtbar. Das Experiment macht sie auf der Ebene der Teilchen erklärbar und berührt damit die Stoffebene. Eine Stoffumwandlung oder der Energieumsatz von Lebewesen tritt hier nicht auf.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '40e031a2-cbd6-49b8-93ed-c332fd495515' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Oberflächenspannung lässt sich auf die Anordnung und Anziehung der Wasserteilchen zurückführen, ein erster Hinweis auf den Zusammenhang von Aufbau und Eigenschaft.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Ein zugesetzter Stoff (Spülmittel) verändert eine Stoffeigenschaft des Wassers, hier die Oberflächenspannung, und das Experiment macht diese Wirkung auf der Ebene der Teilchen erklärbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Menstruation und Pollution sind Zeichen der einsetzenden Geschlechtsreife. Sie zeigen, dass sich der Mensch vom Kind zum fortpflanzungsfähigen Menschen entwickelt, und gehören damit zur Pubertät als dem Entwicklungsabschnitt, an dessen Ende die Fortpflanzungsfähigkeit steht. Lernende bauen die Denkweise auf, den eigenen Körper als Ergebnis einer fortlaufenden Entwicklung im Lebenslauf zu verstehen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '09c8a8a6-935c-43ae-86ba-eb111c132f49' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Menstruation und Pollution sind Zeichen der einsetzenden Geschlechtsreife und damit der Entwicklung vom Kind zum fortpflanzungsfähigen Menschen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug}', $j$[{"begruendung":"Vielfalt wird hier gesellschaftlich und persönlich behandelt. Das Lernziel hat keinen Evolutionsbezug.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Lernziel gehört zur Pubertät, in der Jugendliche sich auch in ihrer Identität und Orientierung unterscheiden. Im Mittelpunkt steht die Akzeptanz unterschiedlicher sexueller Orientierungen und Identitäten, also ein Aspekt der Entwicklung im Lebenslauf. Dem Kern fehlt der biologische Entwicklungsvorgang selbst, etwa die körperliche Reifung. Das Unterkonzept Pubertät und Geschlechtsreife wird nur am Rand berührt.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Pubertät und Geschlechtsreife"],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[{"value":"Pubertät und Geschlechtsreife","taxonomyElementId":"7b563161-d555-4a80-b0b4-349b78df86bc"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Bau und Funktion von Organen sind nicht Gegenstand dieses Lernziels.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Steuerung oder Regelung wird hier nicht behandelt.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoff- oder Energieumwandlung hat keinen Bezug zum Lernziel.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Informationsverarbeitung im biologischen Sinn ist hier nicht Thema.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}]$j$::jsonb), '{basiskonzepte_primaer}', $j$["bk_individuelle_entwicklung"]$j$::jsonb), '{basiskonzepte_sekundaer}', $j$[]$j$::jsonb), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '7f64aee4-b2bd-4347-8dd5-f437a10999c1' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Das Lernziel gehört in die Entwicklung in der Pubertät, in der Jugendliche auch ihre eigene Identität und ihre Orientierung entdecken, und stellt die Akzeptanz von Vielfalt in den Mittelpunkt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Veränderungen des Körperbaus und die Ausbildung sekundärer Geschlechtsmerkmale sind der sichtbare Teil der körperlichen Reifung in der Pubertät. Sie verbinden Wachstum, das auf Körperregionen ungleichmäßig verteilt sein kann, mit der Reifung zur Geschlechtsreife. Lernende bauen die Denkweise auf, dass sich ein Mensch über die Lebensphasen hinweg fortlaufend verändert und die Pubertät ein Abschnitt davon ist.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'f5ec6f8a-a0fa-46a7-8801-11c864adf8bb' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Veränderungen des Körperbaus und die Ausbildung sekundärer Geschlechtsmerkmale sind der sichtbare Teil der körperlichen Reifung in der Pubertät.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Beim Betrachten des Querschnitts mit der Lupe erkennen Lernende die Leitgefäße als besondere Bauelemente der Sprossachse. Anordnung und Form der Leitgefäße passen zu ihrer Funktion, Wasser und gelöste Stoffe zu transportieren. So üben Lernende, vom beobachtbaren Bau auf die Leistung eines Organs zu schließen, und verbinden Strukturen kriteriengeleitet mit Funktionen.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Leitgefäße transportieren Wasser und gelöste Stoffe durch die Pflanze, das Lernziel berührt also den Stofftransport. Beobachtet wird jedoch der Bau, die Stoffbewegung selbst wird vorausgesetzt. Die Umwandlung von Stoffen und Energie in der Pflanze ist im Lernziel nicht angesprochen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '0dc76d8a-6551-4c60-873b-275a29306dd9' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Beim Betrachten des Querschnitts werden Leitgefäße als besondere Bauelemente erkannt, deren Anordnung und Form zur Funktion des Transports passt.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Leitgefäße transportieren Wasser und gelöste Stoffe durch die Pflanze, das Lernziel berührt also den Stofftransport.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Luft als Gemisch aus Stickstoff, Sauerstoff und Kohlenstoffdioxid mit dem Kugelteilchenmodell zu erklären, ist Arbeit auf der Stoffebene. Sie legt die Grundlage für spätere Themen wie Atmung und Stoffaustausch, bei denen Lebewesen Gase aus der Umgebung aufnehmen und abgeben. Im Lernziel selbst geht es nur um die Zusammensetzung eines Gemischs ohne Umwandlung der Stoffe und ohne Energieumsatz.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'acb87dd7-8fcb-4602-a322-7f06773e350b' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Luft als Gemisch aus Stickstoff, Sauerstoff und Kohlenstoffdioxid zu erklären, ist Arbeit auf der Stoffebene und legt die Grundlage für spätere Themen wie Atmung und Stoffaustausch.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Eine Ethanol-Wasser-Lösung zeigt als Stoffgemisch, dass sich zwei Reinstoffe vermischen können, ohne dass ein neuer Stoff entsteht. Das Kugelteilchenmodell erklärt diese Verteilung der Teilchen. Das Lernziel arbeitet damit auf der Stoffebene und liefert eine Grundlage für spätere Betrachtungen von Stoffen in Lebewesen. Eine Stoffumwandlung, die zum Kern des Basiskonzepts gehört, findet hier nicht statt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '2279f70e-85a4-4fc0-ae01-28c222c494d8' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Eine Ethanol-Wasser-Lösung zeigt als Stoffgemisch, dass sich zwei Reinstoffe vermischen können, ohne dass ein neuer Stoff entsteht, und das Teilchenmodell erklärt diese Verteilung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Die Lernenden erklären mit dem Kugelteilchenmodell, wie sich Zucker und Wasser als zwei Reinstoffe zu einem Gemisch verbinden. Das ist die stoffliche Grundlage für spätere Betrachtungen von Lösungsvorgängen in Lebewesen, etwa wenn gelöste Stoffe aufgenommen und transportiert werden. Es ist allerdings ein physikalischer Vorgang ohne Stoffumwandlung, sodass der Kern des Konzepts nur vorbereitet wird.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '7567766b-ec0d-45a9-a8bc-2ca80cef68d8' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Die Lernenden erklären, wie sich Zucker und Wasser als zwei Reinstoffe zu einem Gemisch verbinden. Das ist die stoffliche Grundlage für spätere Betrachtungen von Lösungsvorgängen in Lebewesen. Es ist allerdings ein physikalischer Vorgang ohne Stoffumwandlung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Leistung der Sprossachse, Wasser und gelöste Mineralsalze zu den Laubblättern zu transportieren, wird mit ihrem Bau aus dünnen Röhren und der Kapillarität erklärt. Das ist ein unmittelbares Beispiel für den Zusammenhang von innerem Bau und Funktion. Lernende bauen die Denkweise auf, aus dem Bau eines Pflanzenorgans zu begründen, warum es seine Leistung erbringen kann.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Wasser, Mineralsalze und Kohlenstoffdioxid gelangen aus der Umwelt in die Pflanze und zu den Laubblättern. Das Lernziel berührt damit den Stoffaustausch mit der Umwelt, der für offene biologische Systeme kennzeichnend ist. Er steht hier jedoch im Hintergrund, weil der Weg und die Erklärung des Transports in der Sprossachse im Mittelpunkt stehen. Eine Umwandlung der Stoffe kommt nicht vor.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'd3c8cf6e-c534-463d-8a7e-589e0c71ab1e' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Leistung der Sprossachse, Wasser zu transportieren, wird mit ihrem Bau aus dünnen Röhren und der Kapillarität erklärt. Das ist ein unmittelbares Beispiel für den Zusammenhang von Struktur und Funktion.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Wasser, Mineralsalze und Kohlenstoffdioxid gelangen aus der Umwelt in die Pflanze und zu den Laubblättern. Der Stoffaustausch mit der Umwelt steht hier im Hintergrund.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Aus Traubenzucker bildet die Pflanze weitere Stoffe wie Stärke, Fette und Farbstoffe. Das ist eine Stoffumwandlung im Stoffwechsel der Pflanze und gehört zum Kern des Basiskonzepts, nach dem Lebewesen Stoffe aufnehmen und umwandeln. Die Denkweise dahinter: Pflanzen bauen aus einem Grundstoff viele verschiedene Stoffe auf, die sie für Speicherung, Aufbau und Färbung nutzen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '448fc1a5-5b47-4efd-acd4-da3a99d1f6f5' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Aus Traubenzucker bildet die Pflanze weitere Stoffe wie Stärke, Fette und Farbstoffe. Das ist eine Stoffumwandlung im Stoffwechsel der Pflanze und gehört zum Kern des Basiskonzepts.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Kohlenstoffdioxid und Wasser werden im Chlorophyll der Laubblätter mithilfe von Lichtenergie zu Traubenzucker und Sauerstoff umgewandelt. Damit stehen Stoffumwandlung und Energieumwandlung unmittelbar im Kern: Aus Ausgangsstoffen entstehen neue Stoffe, und die aufgenommene Lichtenergie wird in eine andere Form überführt. Lernende bauen die Denkweise auf, Lebensprozesse als Umwandlung von Stoffen unter Energieaufnahme zu beschreiben.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '5421eb40-cc90-4e0c-b9e2-257c090181de' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Kohlenstoffdioxid und Wasser werden mithilfe von Lichtenergie zu Traubenzucker und Sauerstoff umgewandelt. Stoff- und Energieumwandlung stehen hier unmittelbar im Kern.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Zu- oder Abfuhr von Wärme verändert den Zustand des Wassers, das schmilzt, verdampft, kondensiert oder gefriert. Damit verbindet das Lernziel Stoff und Energie, denn Wärme wird aufgenommen oder abgegeben. Es bleibt aber bei einem physikalischen Vorgang ohne neuen Stoff. Der Austausch lebender Systeme mit der Umwelt und die chemische Stoffumwandlung, die den Kern des Basiskonzepts bilden, kommen nicht vor.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '35d5c6e9-2015-4d5b-a5e1-004f4f28baa9' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Zu- oder Abfuhr von Wärme verändert den Zustand des Wassers. Damit verbindet das Lernziel Stoff und Energie, bleibt aber bei einem physikalischen Vorgang ohne neuen Stoff.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Bei der Verbrennung entstehen unter Beteiligung von Sauerstoff neue Stoffe mit anderen Eigenschaften. Das ist die Stoffumwandlung in ihrer einfachsten, sichtbaren Form: Die Ausgangsstoffe werden verbraucht, und die entstandenen Stoffe unterscheiden sich in ihren Eigenschaften deutlich von ihnen. Das Lernziel liegt damit im Kern des Basiskonzepts. Lernende erkennen an veränderten Eigenschaften, dass ein Stoff umgewandelt wurde, und beschreiben Stoffveränderungen als Bildung neuer Stoffe.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'f8c2d84b-ba1f-4af0-83da-f8de15a039f5' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Bei der Verbrennung entstehen unter Beteiligung von Sauerstoff neue Stoffe mit anderen Eigenschaften. Das ist die Stoffumwandlung in ihrer einfachsten, sichtbaren Form.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Bei der Verbrennung wird die in den Stoffen gespeicherte chemische Energie in Wärme und Licht umgewandelt. Das Lernziel beschreibt damit eine Energieumwandlung, bei der Energie von einer Form in andere Formen übergeht und als Wärme und Licht wahrnehmbar wird. Die Energieumwandlung steht unmittelbar im Kern des Lernziels. Lernende bauen die Vorstellung auf, dass Stoffe Energie gespeichert haben und Reaktionen diese Energie in andere Formen überführen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'd7ffc4d0-1afa-4a98-ae6a-b8be4f4200ea' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Chemische Energie der Stoffe wird in Wärme und Licht umgewandelt. Die Energieumwandlung steht unmittelbar im Kern des Lernziels.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Wie Wassertropfen auf einem Laubblatt aussehen, hängt von der Oberflächenbeschaffenheit des Blattes ab. Beim Vergleich etwa von Kohlrabi, Gartenkresse und Erdbeere beobachten die Lernenden unmittelbar, wie die Beschaffenheit einer Blattoberfläche ihr Verhalten gegenüber Wasser bestimmt. Das liegt im Kern des Basiskonzepts. Lernende bauen die Denkweise auf, vom sichtbaren Bau eines Pflanzenorgans auf seine Leistung zu schließen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '9252d9eb-3884-4e58-89e1-f44b3302e4f0' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Wie Wassertropfen auf einem Laubblatt aussehen, hängt von der Oberflächenbeschaffenheit des Blattes ab. Die Lernenden beobachten damit unmittelbar einen Zusammenhang zwischen Struktur und Leistung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Beim Bestimmen des Volumens fester Körper durch Eintauchen in Wasser geht es um Stoffe und ihre messbaren Eigenschaften. Der Bezug zum Basiskonzept ist nur am Rand gegeben. Es findet keine Stoffumwandlung statt, denn die Körper und das Wasser bleiben unverändert. Dem Kern fehlt damit die Bildung neuer Stoffe oder die Umwandlung von Energie.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '96caf4c9-0748-42f5-b13d-6629dfeff3b1' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Die Messung betrifft Stoffe und ihre Eigenschaften, jedoch ohne Umwandlung. Der Bezug zum Basiskonzept ist nur am Rand gegeben.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Der Nachweis, dass Wasser über die Wurzeln aufgenommen wird, verweist auf die Funktion des Organs Wurzel für die Pflanze. Das passt zum Gedanken des Basiskonzepts, dass Organe bestimmte Aufgaben erfüllen. Der Bau der Wurzel wird jedoch nicht untersucht. Dem Kern fehlt damit die Verbindung zwischen der Gestalt der Wurzel und ihrer Leistung bei der Wasseraufnahme.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Der Versuch weist nach, dass die Pflanze Wasser aus ihrer Umgebung aufnimmt. Das ist ein Stoffaustausch mit der Umwelt, wie er für offene biologische Systeme kennzeichnend ist. Der Schwerpunkt liegt auf Versuchsaufbau und Kontrollversuch, doch der Stoffaustausch ist der Sachverhalt, der damit belegt wird. Lernende bauen die Denkweise auf, dass Lebewesen Stoffe aus ihrer Umwelt aufnehmen, und prüfen dies mit einem Versuch.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '80f9eeab-324c-4eb2-9ea2-24a4f1ce2e9f' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Dass Wasser über die Wurzeln aufgenommen wird, verweist auf die Funktion des Organs Wurzel. Der Bau der Wurzel wird jedoch nicht untersucht.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Der Versuch weist nach, dass die Pflanze Wasser aus ihrer Umgebung aufnimmt. Das ist ein Stoffaustausch mit der Umwelt, hier mit Schwerpunkt auf Versuchsaufbau und Kontrollversuch.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Darm und Blut übernehmen unterschiedliche Aufgaben beim Aufnehmen und Verteilen der Nährstoffbausteine. Damit berührt das Lernziel den Gedanken des Basiskonzepts, dass Organe und Organsysteme von ihrer Funktion her zu verstehen sind. Der Zusammenhang von Bau und Leistung wird aber nicht ausdrücklich verlangt. Dem Kern fehlt, wie der Bau von Darm und Blutgefäßen ihre jeweilige Aufgabe möglich macht.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Nährstoffbausteine gehen aus dem Darm ins Blut über und werden im Körper verteilt. Das ist Stoffaustausch und Stofftransport: Stoffe aus der Nahrung treten in den Körper über und gelangen mit dem Blut zu seinen verschiedenen Teilen. Das Lernziel beschreibt damit den Weg der Stoffe durch den Körper und liegt im Kern des Basiskonzepts. Lernende bauen die Vorstellung auf, dass aufgenommene Stoffe im Körper weitergeleitet werden.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'aee81b02-9a6c-496c-a68a-99f0b53adf57' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Darm und Blutkreislauf übernehmen unterschiedliche Aufgaben beim Aufnehmen und Verteilen der Nährstoffbausteine. Der Zusammenhang von Bau und Leistung wird aber nicht ausdrücklich verlangt.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Nährstoffbausteine gehen aus dem Darm ins Blut über und werden im Körper verteilt. Das ist Stoffaustausch und Stofftransport, der den Weg der Stoffe durch den Körper beschreibt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die mechanische Zerkleinerung der Nahrung geschieht mit Organen wie Mund und Zähnen, deren Bau zu dieser Aufgabe passt. Hier liegt ein Beispiel für den Zusammenhang von Bau und Leistung, den das Basiskonzept beschreibt. Das Lernziel nennt diese Organe jedoch nicht ausdrücklich. Dem Kern fehlt damit der Blick darauf, wie der Bau von Mund und Zähnen das Zerkleinern möglich macht.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Die Aufnahme der Nahrung ist der erste Schritt des Stoffaustauschs mit der Umwelt, den das Basiskonzept für Lebewesen als offene Systeme beschreibt. Die mechanische Zerkleinerung bereitet die Verdauung vor und verändert die Nahrung dabei nur mechanisch. Dem Kern fehlt die Umwandlung der Nährstoffe, die erst in den weiteren Schritten auf dem Weg der Nährstoffe folgt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '417587d2-0b4c-4f4c-a357-58baeb172be8' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Zerkleinerung geschieht mit Organen wie Mund und Zähnen, deren Bau zur Aufgabe passt. Das Lernziel nennt diese Organe nicht ausdrücklich.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Die Aufnahme der Nahrung ist der erste Schritt des Stoffaustauschs mit der Umwelt. Die mechanische Zerkleinerung bereitet die Verdauung vor.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Bei der Verdauung wird Stärke in kleinere Bausteine zerlegt. Das ist eine chemische Stoffumwandlung im Körper: Aus dem Nährstoff entstehen kleinere Bausteine, die der Körper aufnehmen kann. Das Lernziel gehört damit zum Kern des Basiskonzepts. Lernende bauen die Vorstellung auf, dass Lebewesen aufgenommene Stoffe chemisch umbauen. Dieser Umbau unterscheidet sich vom mechanischen Zerkleinern, das den Stoff selbst unverändert lässt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'e86ea606-3d9c-446f-adcd-9496d5cfc4b7' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Stärke wird in kleinere Bausteine zerlegt. Das ist eine chemische Stoffumwandlung im Körper und gehört zum Kern des Basiskonzepts.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Als Baustoff dienen die Nährstoffbausteine dem Aufbau von Körpersubstanz. Das ist die stoffliche Grundlage für Wachstum, also für die Zunahme von Zellzahl und Zellgröße im Lauf der individuellen Entwicklung. Das Lernziel nennt Wachstum aber nicht ausdrücklich. Dem Kern fehlt damit die zeitliche Sicht auf einen Körper, der sich über sein Leben hinweg verändert.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Nährstoffbausteine werden in verschiedenen Körperteilen, etwa im Muskel, als Baustoff eingebaut oder zur Energiegewinnung genutzt. Damit stehen Stoff- und Energieumwandlung im Körper unmittelbar im Kern: Stoffe werden zu Körpersubstanz umgebaut, und die in Stoffen gebundene Energie wird für Leistungen des Körpers nutzbar. Lernende bauen die Denkweise auf, dass Nahrung zugleich Material und Energiequelle ist.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'f7743f9d-7098-4684-b3f6-aeb9f8724ffc' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Als Baustoff dienen die Nährstoffbausteine dem Aufbau von Körpersubstanz und damit dem Wachstum. Das Lernziel nennt Wachstum aber nicht ausdrücklich.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Nährstoffbausteine werden als Baustoff eingebaut oder zur Energiegewinnung genutzt. Damit stehen Stoff- und Energieumwandlung im Körper unmittelbar im Kern.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die Widerhaken der Klettfrucht werden mit der Lupe genau betrachtet. Sie gehören zum Zusammenhang von Bau und Haftfunktion, der im Thema Bionik das Naturvorbild liefert. Zunächst steht jedoch das kriteriengeleitete Betrachten im Vordergrund. Dem Kern fehlt, dass die Lernenden den beobachteten Bau der Widerhaken ausdrücklich mit der Haftfunktion verknüpfen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '7f44ae52-71c0-4269-bbd7-c1ef06edaed4' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die Widerhaken der Klettfrucht werden genau betrachtet; sie gehören zum Zusammenhang von Bau und Haftfunktion, der im Thema Bionik das Naturvorbild liefert.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Am Modell wird untersucht, wie der Bau eines Gelenks bestimmte Bewegungen möglich macht. Das ist Struktur-Funktions-Denken, denn aus der Anordnung der Teile folgt, wie beweglich das Gelenk ist. Das Lernziel nennt die Bauteile des Gelenks aber nicht ausdrücklich. Dem Kern fehlt damit die gezielte Verknüpfung einzelner Bauteile mit den Bewegungen, die sie erlauben.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'a38c31ff-e8d6-41dd-a6fc-4ba353e0cbd2' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Am Modell wird untersucht, wie der Bau eines Gelenks bestimmte Bewegungen möglich macht. Das ist Struktur-Funktions-Denken.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Das Pflanzenwachstum der Kresse unter verschiedenen Bedingungen dient als Beobachtungsgröße des Versuchs. Wachstum ist ein Teilprozess der individuellen Entwicklung einer Pflanze, und seine Ausprägung hängt hier von Licht und Wasser ab. Die Entwicklung selbst wird jedoch nicht thematisiert. Dem Kern fehlt der Blick darauf, wie sich die Pflanze über die Zeit verändert.$t$::text)), '{basiskonzeptbezug,3,begruendung}', to_jsonb($t$Die Kressepflanzen reagieren je nach Licht und Wasser unterschiedlich. So kann zur Sprache kommen, dass Lebewesen auf äußere Zustände ihrer Umwelt mit einer angepassten Reaktion antworten. Das ist aber nicht der Kern des Lernziels. Dem Kern fehlt der Blick darauf, wie die Pflanze Veränderungen wahrnimmt und ihre Reaktion steuert.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Licht liefert der Pflanze Energie, und Wasser ist ein Stoff, den sie aufnehmen muss. Der Versuch prüft die Bedeutung beider für die Pflanze, und Kontrollversuche sichern die Aussage. Damit liegt der Austausch von Energie und Stoffen mit der Umwelt im Kern. Lernende bauen die Denkweise auf, dass Lebewesen von Energie und Stoffen aus ihrer Umgebung abhängen, und prüfen diese Abhängigkeit mit gezielt veränderten Bedingungen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '3bf9cd89-5b7b-4f2f-851f-a6bce4dc55cf' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Das Pflanzenwachstum unter verschiedenen Bedingungen dient als Beobachtungsgröße des Versuchs.$t$ AND content #>> '{basiskonzeptbezug,3,begruendung}' = $t$Die Kressepflanzen reagieren je nach Licht und Wasser unterschiedlich; so kann die Reaktion auf äußere Zustände zur Sprache kommen, auch wenn sie nicht Kern ist.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Licht liefert Energie und Wasser ist ein Stoff, den die Pflanze braucht; der Versuch prüft deren Bedeutung und Kontrollversuche sichern die Aussage.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Ob Wasser abperlt, hängt von der Beschaffenheit der Oberfläche (wasserabweisend, rau, genoppt) und von den Kräften zwischen den Teilchen ab. Das Lernziel verbindet damit den Aufbau einer Oberfläche mit ihrem Verhalten gegenüber Wasser und berührt so den Struktur-Funktions-Gedanken. Es bleibt ein physikalisches Beispiel. Dem Kern fehlt der Bezug zu Lebewesen, an denen sich Bau und Leistung biologisch zeigen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '67e19f5d-b8a0-42e3-ac0f-f69f11a611a0' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Ob Wasser abperlt, hängt von der Beschaffenheit der Oberfläche (wasserabweisend, rau, genoppt) und den Kräften zwischen den Teilchen ab; das Lernziel verbindet also Aufbau und Verhalten.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Die fein genoppte Oberfläche und die Materialeigenschaft erklären, warum Outdoorkleidung oder mit Autowachs behandelte Flächen Wasser abweisen. Hier wird eine Struktur mit ihrer Wirkung verknüpft, was dem Gedanken des Basiskonzepts entspricht. Es geschieht allerdings am Beispiel von Gebrauchsgegenständen. Dem Kern fehlt der Bezug zu Lebewesen, an denen sich Bau und Leistung biologisch zeigen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '01a6cf3c-8414-42ce-ac8e-0918e08b93bd' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Die fein genoppte Oberfläche und die Materialeigenschaft erklären, warum Kleidung oder Lack Wasser abweisen. Hier wird eine Struktur mit ihrer Wirkung verknüpft, allerdings am Beispiel von Gebrauchsgegenständen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Verhalten des Wassertropfens hängt davon ab, ob die Oberfläche wasserliebend oder wasserabweisend ist. Das übt den Gedanken ein, dass die Beschaffenheit einer Fläche ihre Eigenschaft bestimmt, und steht damit dem Struktur-Funktions-Denken nahe. Es bleibt aber ein physikalisches Beispiel. Dem Kern fehlt ein Lebewesen oder Organ, an dem dieser Zusammenhang biologisch gedeutet wird.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'd9f64b34-4fc9-4f51-9e72-9a58424d3cf1' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Verhalten des Tropfens hängt von der Beschaffenheit der Oberfläche ab. Das übt den Gedanken ein, dass die Struktur einer Fläche ihre Eigenschaft bestimmt, bleibt aber ein physikalisches Beispiel.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,3,begruendung}', to_jsonb($t$Gleichwarme Tiere halten ihre Körpertemperatur weitgehend konstant, bei wechselwarmen Tieren folgt sie der Umgebung. Das entspricht dem Kern des Basiskonzepts: Ein innerer Zustand wird trotz wechselnder äußerer Bedingungen aufrechterhalten (Homöostase) oder bleibt von ihnen abhängig. Lernende bauen die Denkweise auf, Körpertemperatur als Zustandsgröße zu sehen, die ein Lebewesen in Grenzen hält oder die auf äußere Zustände reagiert.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Gleichwarme Tiere benötigen Energie, um ihre Körpertemperatur zu halten. Dieser Energiebedarf gehört zum Basiskonzept, nach dem alle Lebensprozesse Energie benötigen und Energie mit der Umwelt ausgetauscht wird. Das Lernziel nennt diesen Energieaspekt aber nicht ausdrücklich. Dem Kern fehlt damit der Energiebedarf als Teil des Vergleichs von wechselwarmen und gleichwarmen Tieren.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'd32ed67d-e310-406a-91c2-5003b7a12d05' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,3,begruendung}' = $t$Gleichwarm bedeutet, dass die Körpertemperatur weitgehend konstant gehalten wird, wechselwarm bedeutet, dass sie von der Umgebung abhängt. Das berührt Regelung und Reaktion auf äußere Zustände unmittelbar.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Gleichwarme Tiere benötigen Energie, um ihre Körpertemperatur zu halten. Das Lernziel nennt diesen Energieaspekt aber nicht ausdrücklich.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Zur Abgrenzung von Nichtlebendem gehören üblicherweise Merkmale wie Wachstum und Fortpflanzung. Sie sind Teilprozesse der individuellen Entwicklung, die Steine und Gegenstände nicht zeigen. Das Lernziel nennt diese Merkmale allerdings nicht ausdrücklich. Dem Kern fehlt damit die Betrachtung eines Lebewesens als Individuum, das sich über seine Lebenszeit verändert und Nachkommen hervorbringt.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Auch der Stoffwechsel wird üblicherweise zur Abgrenzung von Nichtlebendem herangezogen: Lebewesen nehmen Stoffe aus der Umwelt auf, wandeln sie um und geben Stoffe wieder ab. Das Lernziel selbst nennt den Stoffwechsel jedoch nicht. Dem Kern fehlt damit der Blick auf den ständigen Stoff- und Energieaustausch als Merkmal des Lebendigen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '3da9a128-ab74-4a57-a909-58d4f95a206c' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Zur Abgrenzung von Nichtlebendem gehören üblicherweise Merkmale wie Wachstum und Fortpflanzung, die das Lernziel allerdings nicht ausdrücklich nennt.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Auch Stoffwechsel wird üblicherweise zur Abgrenzung herangezogen, das Lernziel selbst nennt ihn nicht.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug}', $j$[{"begruendung":"Kein Evolutionsbezug.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Kein Bezug zu Entwicklung von Lebewesen.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stofftrennung nutzt unterschiedliche Stoffeigenschaften, bezieht sich aber nicht auf Bau und Leistung von Organen.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Steuerung oder Regelung ist in diesem Lernziel nicht angesprochen.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Lernziel selbst spricht dieses Basiskonzept nicht an.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Kein Bezug zu Information oder Kommunikation.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}]$j$::jsonb), '{basiskonzepte_primaer}', $j$[]$j$::jsonb), '{basiskonzepte_sekundaer}', $j$[]$j$::jsonb), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'f2fcfe8b-1825-43b3-8029-ad47e048848b' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Gemische in Alltagsbeispielen zu trennen betrifft den Umgang mit Stoffen. Eine Stoffumwandlung findet dabei nicht statt, daher nur ein Bezug am Rand.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Chemische Reaktionen sind hier ausdrücklich als Stoff- und Energieumwandlungen gefasst. Die Lernenden sollen sie von Zustandsänderungen und Mischvorgängen abgrenzen, bei denen kein neuer Stoff entsteht. Das Lernziel liegt damit im Kern des Basiskonzepts. Lernende bauen die Denkweise auf, Vorgänge danach zu unterscheiden, ob neue Stoffe entstehen und Energie umgewandelt wird.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'e04a05b9-50fa-478f-8db9-7136dd589c58' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Chemische Reaktionen sind hier als Stoff- und Energieumwandlungen gefasst. Die Lernenden sollen sie von bloßen Zustandsänderungen und Mischvorgängen abgrenzen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Die unterschiedlichen Blütenformen bei Wind- und Insektenbestäubung sind ein Beispiel für Angepasstheit als Ergebnis von Evolution. Angepasstheit entsteht nach dem Basiskonzept durch evolutive Prozesse in Populationen über viele Generationen. Der Begriff Evolution fällt im Lernziel aber nicht. Dem Kern fehlt die Frage, wie solche Unterschiede in Populationen entstehen.$t$::text)), '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Die Bestäubung, bei der Pollen vom Staubblatt auf die Narbe des Fruchtblattes gelangt, ist ein Schritt der Fortpflanzung der Samenpflanzen und damit Teil ihrer Entwicklung. Sie bereitet die Entstehung neuer Individuen vor. Im Lernziel liegt der Schwerpunkt jedoch auf der Übertragung des Pollens und auf dem Blütenbau. Dem Kern fehlt der Blick auf die weitere Entwicklung nach der Bestäubung.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel verlangt ausdrücklich, den Bau von Blüten (Staubblatt, Narbe, Blütenform) mit der Funktion Bestäubung durch Wind oder Insekten zu verknüpfen. Damit steht der Zusammenhang von Bau und Leistung im Kern: Die Gestalt der Blüte hängt mit der Art der Bestäubung zusammen. Lernende bauen die Denkweise auf, von der Form eines Organs auf seine Aufgabe zu schließen und umgekehrt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '7b3edcdc-c706-4587-a996-c15123368e5f' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Die unterschiedlichen Blütenformen sind ein Beispiel für Angepasstheit als Ergebnis von Evolution. Der Begriff selbst fällt im Lernziel aber nicht.$t$ AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Die Bestäubung ist ein Schritt der Fortpflanzung der Samenpflanzen und damit Teil ihrer Entwicklung.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Lernziel verlangt ausdrücklich, den Bau von Blüten (Staubblatt, Narbe, Blütenform) mit der Funktion Bestäubung durch Wind oder Insekten zu verknüpfen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Befruchtung und Fruchtbildung sind zentrale Schritte im Lebenslauf einer Samenpflanze. Mit der Verschmelzung von Samenzelle und Eizelle beginnt ein neues Individuum, und die Fruchtbildung führt weiter zur Frucht mit Samen. Das entspricht der geschlechtlichen Fortpflanzung und den aufeinanderfolgenden Entwicklungsphasen im Lebenszyklus. Lernende erfassen so Entwicklung als eine Abfolge von Stadien, die von der Blüte bis zur Frucht mit Samen reicht.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'a0c41849-c821-4272-8c75-79b0ccce71e0' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Befruchtung und Fruchtbildung sind zentrale Schritte der Fortpflanzung und der Entwicklung einer Samenpflanze vom Blütenstadium zur Frucht mit Samen.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel verknüpft die Form von Knochen mit ihrer Aufgabe: Röhrenknochen stehen für Stabilität, Plattenknochen für Schutz. Das ist der Zusammenhang zwischen Gestalt oder innerem Bau einer Struktur und ihrer Funktion, den das Unterkonzept morphologische und anatomische Angepasstheit beschreibt. Lernende üben dabei, von der Bauweise eines Körperteils auf seine Leistung zu schließen und umgekehrt. Das ist die Kernidee des Basiskonzepts.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'b59c9fc0-ae0a-4d36-bf68-cc48522f830f' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Lernziel verknüpft Knochenform und Aufgabe, etwa Röhrenknochen mit Stabilität und Plattenknochen mit Schutz.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Schwangerschaftsverhütung greift in den Ablauf der menschlichen Fortpflanzung ein. Wer Möglichkeiten dazu nennt, setzt Wissen über Befruchtung und Schwangerschaft voraus. Damit liegt das Lernziel im Kern des Unterkonzepts Reproduktion und Fortpflanzung, bei dem durch die Verschmelzung von Keimzellen ein neuer Entwicklungszyklus beginnt. Das Lernziel selbst bleibt beim Nennen der Möglichkeiten und behandelt die Entwicklungsvorgänge nicht im Einzelnen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'cd5f7ccf-bb72-497a-a7d6-d80a312a963f' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Schwangerschaftsverhütung greift in den Ablauf der menschlichen Fortpflanzung ein und setzt Wissen über Befruchtung und Schwangerschaft voraus.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Bei der Herstellung von Stoffen wie Glas oder Kunststoffen reagieren Ausgangsstoffe chemisch miteinander, und es entstehen neue Stoffe mit anderen Eigenschaften. Genau das beschreibt das Unterkonzept Stoffumwandlung: Ein Stoff wird chemisch umgewandelt und liegt danach als anderer Stoff vor. Lernende bauen die Denkweise auf, dass sich Stoffe nach einer Reaktion in ihren Eigenschaften unterscheiden und Reaktionen gezielt genutzt werden, um Gebrauchsstoffe herzustellen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'f86bc125-6683-4152-9a3a-8f327b08a9e4' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Bei der Herstellung von Stoffen wie Glas oder Kunststoffen entstehen aus Ausgangsstoffen neue Stoffe mit anderen Eigenschaften. Das ist der Kern von Stoffumwandlung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(content, '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Beim Verbrennen von Holzkohle im Grill wird gespeicherte Energie als Wärme frei, und diese Wärme wird genutzt. Damit liegen zwei Unterkonzepte zugleich vor: Energieumwandlung, weil Energie von einer Form in eine andere überführt wird, und Stoffumwandlung, weil aus der Kohle neue Stoffe entstehen. Lernende sehen an diesem Beispiel, dass sich die bei einer chemischen Reaktion freigesetzte Wärme nutzen lässt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '889eb75c-ac32-45af-a2df-211a93207977' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Bei der Verbrennung von Holzkohle wird gespeicherte Energie als Wärme frei und genutzt. Das ist unmittelbar Energieumwandlung und zugleich Stoffumwandlung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Die äußere Befruchtung des Grasfrosches wird als Angepasstheit an den Lebensraum Wasser betrachtet. Angepasstheit ist im Basiskonzept ein Ergebnis evolutiver Prozesse, daher gibt es einen Anknüpfungspunkt. Dem Kern fehlt die Frage, wie dieses Merkmal über viele Generationen entstanden ist. Das Lernziel erklärt die Angepasstheit nicht als Ergebnis von Evolution. Es beschreibt nur den Zusammenhang zwischen Fortpflanzung und Lebensraum.$t$::text)), '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Fortpflanzung und Entwicklung des Grasfrosches stehen im Mittelpunkt dieses Lernziels, die äußere Befruchtung ist dabei Teil der Fortpflanzung. Das entspricht dem Unterkonzept Reproduktion und Fortpflanzung: Bei geschlechtlicher Fortpflanzung verschmelzen Keimzellen, und damit beginnt ein neuer Entwicklungszyklus. Lernende erkennen, dass Fortpflanzung und Entwicklung eines Tieres zusammengehören und ein Lebewesen von der befruchteten Eizelle an einen eigenen Lebenslauf durchläuft.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'e1cd7611-4629-4e45-9917-d065c7e20812' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Die äußere Befruchtung wird als Angepasstheit an den Lebensraum Wasser betrachtet; als Ergebnis von Evolution wird sie im Lernziel selbst nicht erklärt.$t$ AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Fortpflanzung und Entwicklung des Grasfrosches stehen im Mittelpunkt, hier mit äußerer Befruchtung als Teil der Fortpflanzung.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Schwimmfüße und eingefettetes Gefieder der Graugans sind Angepasstheiten an das Schwimmen, und Angepasstheit ist im Basiskonzept ein Ergebnis der Stammesgeschichte. Damit besteht ein Bezug. Dem Kern fehlt die Frage, wie sich diese Merkmale über Generationen herausgebildet haben. Das Lernziel spricht die Stammesgeschichte nicht an und stellt nur den Zusammenhang zwischen Lebensweise und Körperbau her.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Schwimmfüße und eingefettetes Gefieder der Graugans werden im Lernziel ausdrücklich mit dem Schwimmen verknüpft. Das ist der Zusammenhang zwischen Gestalt eines Körperteils und seiner Funktion in der Umwelt, wie ihn das Unterkonzept morphologische und anatomische Angepasstheit beschreibt. Lernende bauen die Denkweise auf, vom Bau auf die Leistung zu schließen: Welche Funktion haben Schwimmfüße und Gefieder beim Schwimmen?$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '6b5f02c6-5bc1-4b6f-a23a-b87dfbdf2851' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Die Angepasstheit der Graugans an das Schwimmen ist ein Ergebnis der Stammesgeschichte; das Lernziel spricht diese aber nicht an.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Schwimmfüße und eingefettetes Gefieder werden ausdrücklich mit dem Schwimmen verknüpft. Bau und Funktion stehen im Kern.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Dass die Vordergliedmaßen der Graugans als Flügel ausgeprägt sind, berührt Abwandlung und Verwandtschaft der Wirbeltiere. Im Unterkonzept Homologie und Analogie gehen Strukturen auf ein gemeinsames Grundmuster zurück und erfüllen in verschiedenen Gruppen unterschiedliche Aufgaben. Dem Kern fehlt ein solcher Vergleich. Das Lernziel führt diesen Gedanken nicht aus und nennt den Flügel nur als Teil des Fliegens.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Flügel, stromlinienförmiger Körper, Federn und hohle Knochen werden im Lernziel ausdrücklich dem Fliegen zugeordnet. Mehrere Bauelemente sind also mit einer gemeinsamen Funktion verknüpft. Das entspricht dem Unterkonzept morphologische und anatomische Angepasstheit, bei dem von der Gestalt und dem inneren Bau auf die Funktion geschlossen wird. Lernende erkennen, dass ein Körper aus zusammenwirkenden Merkmalen besteht, die gemeinsam eine Leistung wie das Fliegen ermöglichen.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '459588d0-90ff-47d8-90fb-4e86681581ca' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Dass die Vordergliedmaßen als Flügel ausgeprägt sind, berührt Abwandlung und Verwandtschaft der Wirbeltiere. Das Lernziel führt diesen Gedanken aber nicht aus.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Flügel, stromlinienförmiger Körper, Federn und hohle Knochen werden ausdrücklich mit dem Fliegen verknüpft. Bau und Funktion stehen im Kern.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Die Fortbewegung der Ringelnatter an Land mit Bauchmuskeln und Bauchschuppen ist eine Angepasstheit, und Angepasstheit ist im Basiskonzept ein Ergebnis der Stammesgeschichte. Daraus ergibt sich ein Bezug. Dem Kern fehlt die Frage, wie solche Merkmale über Generationen entstanden sind. Das Lernziel spricht die Stammesgeschichte nicht an und bleibt beim Schlängeln als Leistung des Körperbaus.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Bauchmuskeln und Bauchschuppen der Ringelnatter werden im Lernziel unmittelbar mit dem Schlängeln an Land verknüpft. Das ist der Zusammenhang zwischen Körperbau und Fortbewegung, den das Unterkonzept morphologische und anatomische Angepasstheit beschreibt. Aus der Gestalt einer Struktur lässt sich ihre Funktion erschließen. Lernende erklären, welche Bauteile die Bewegung ermöglichen, und lernen damit eine Denkweise kennen, die sich auf andere Tiere anwenden lässt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '2041cbc1-acf4-4946-9748-b62ba711fe17' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Die Angepasstheit der Ringelnatter an das Leben an Land ist ein Ergebnis der Stammesgeschichte; das Lernziel spricht diese aber nicht an.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Bauchmuskeln und Bauchschuppen ermöglichen das Schlängeln. Das Lernziel verknüpft Körperbau und Fortbewegung unmittelbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Trockene Haut mit Hornschuppen als Schutz vor Austrocknung ist eine Angepasstheit der Ringelnatter an das Leben an Land. Angepasstheit ist im Basiskonzept ein Ergebnis von Evolution, daher gibt es einen Bezug. Das Lernziel fragt aber nur nach dem Zusammenhang von Merkmal und Lebensraum. Dem Kern fehlt die Frage, wie das Merkmal über viele Generationen entstanden ist.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Das Lernziel verbindet die Körperbedeckung der Ringelnatter, trockene Haut mit Hornschuppen, mit ihrer Schutzfunktion vor Austrocknung. Gefragt ist damit der Zusammenhang zwischen Bau und Aufgabe einer Struktur, also die morphologische und anatomische Angepasstheit. Lernende üben, aus dem Bau einer Struktur ihre Funktion abzuleiten und zu erklären, wie ein Merkmal den Anforderungen des Lebens an Land entspricht.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Der Schutz vor Austrocknung betrifft den Wasserverlust des Körpers. Damit berührt das Lernziel den Stoffaustausch mit der Umwelt, also die Abgabe von Stoffen wie Wasser an die Umgebung. Dem Kern fehlt der Austausch selbst. Das Lernziel behandelt die Haut als Schutz und geht auf Aufnahme, Abgabe oder Umwandlung von Stoffen nicht weiter ein.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '873a883b-185f-4b71-afa9-cf5cd0540acf' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Angepasstheit an einen Lebensraum ist Ergebnis von Evolution; das Lernziel fragt aber nur nach dem Zusammenhang von Merkmal und Lebensraum und geht auf dessen Entstehung nicht ein.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Lernziel verbindet die Körperbedeckung der Ringelnatter, trockene Haut mit Hornschuppen, mit ihrer Schutzfunktion und behandelt damit unmittelbar Bau und Funktion.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Der Schutz vor Austrocknung betrifft den Wasserverlust des Körpers und damit den Stoffaustausch mit der Umwelt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Das Lernziel nennt Wachstum als eine Verwendung der gebildeten energiereichen Stoffe. Wachstum bedeutet im Basiskonzept die Zunahme von Zellzahl oder Zellgröße über die Zeit, hier gestützt durch Baumaterial aus diesen Stoffen. Das ist jedoch nur ein Teil. Der Kern liegt bei der Bedeutung der Stoffe für Energie und Baumaterial. Die Entwicklung der Pflanze wird nicht weiter behandelt.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Energiereiche Stoffe dienen der Pflanze als Speicher und Lieferant von Energie und als Baumaterial. Das Lernziel behandelt diese Verwendung unmittelbar und verbindet damit Stoffumwandlung mit Energieumwandlung: Stoffe werden aufgenommen, umgewandelt und genutzt, wobei Energie von einer Form in eine andere überführt wird. Lernende bauen die Denkweise auf, Stoffe und Energie in der Pflanze gemeinsam zu betrachten.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'cbf760e4-866e-4d6b-9a51-3c21554ada26' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Das Lernziel nennt Wachstum als eine Verwendung der gebildeten Stoffe; Wachstum ist ein Teil, aber nicht der Kern.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Energiereiche Stoffe sind Speicher und Lieferanten von Energie und Baumaterial für die Pflanze; das Lernziel behandelt die Verwendung dieser Stoffe unmittelbar.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Der Vergleich der Wirbeltierklassen anhand von Kiemen, Haut und Lunge macht Vielfalt und Gemeinsamkeiten zwischen Tiergruppen sichtbar. Das berührt das Unterkonzept Variation und Diversität. Dem Kern fehlt die Behandlung von Evolutionsprozessen. Das Lernziel stellt die Atmungsorgane gegenüber und fragt nicht, wie die Unterschiede entstanden sind.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Kiemen, Haut und Lunge sind unterschiedlich gebaute Atmungsorgane. Das Lernziel lässt sie gegenüberstellen und Vertreter begründet zuordnen. So wird sichtbar, wie der Bau zum Gasaustausch in Wasser oder Luft passt. Das ist der Zusammenhang von Gestalt und Funktion im Sinne der morphologischen und anatomischen Angepasstheit. Lernende erfahren, dass verschiedene Strukturen dieselbe Aufgabe erfüllen können und der Bau jeweils zum Lebensraum gehört.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Atmung ist Gasaustausch mit der Umwelt: Sauerstoff wird aufgenommen, Kohlenstoffdioxid wird abgegeben. Das entspricht dem Unterkonzept Stoffaustausch mit der Umwelt. Im Lernziel steht aber der Vergleich der Atmungsorgane im Vordergrund. Dem Kern fehlt der Stoffaustausch als Vorgang, denn die Aufnahme und Abgabe von Gasen wird dort nicht ausgeführt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'ed224b00-5ab2-4a5d-a536-4f4af9d4052b' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Der Vergleich der Klassen macht Vielfalt und Gemeinsamkeiten zwischen Tiergruppen sichtbar, Evolutionsprozesse selbst werden aber nicht behandelt.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Kiemen, Haut und Lunge sind unterschiedlich gebaute Atmungsorgane. Der Vergleich zeigt, wie der Bau zum Gasaustausch in Wasser oder Luft passt.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Atmung ist Gasaustausch mit der Umwelt (Sauerstoff aufnehmen, Kohlenstoffdioxid abgeben), steht hier aber nicht im Mittelpunkt.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Der Klassenvergleich zeigt verschiedene Fortpflanzungsweisen als Vielfalt innerhalb der Wirbeltiere, etwa äußere und innere Befruchtung. Das berührt das Unterkonzept Variation und Diversität. Dem Kern fehlt die Behandlung von Evolutionsprozessen. Das Lernziel stellt die Unterschiede gegenüber und fragt nicht, wie sie entstanden sind.$t$::text)), '{basiskonzeptbezug,1,begruendung}', to_jsonb($t$Befruchtung und Entwicklung des Embryos gehören zur Fortpflanzung und zur Individualentwicklung. Verglichen wird, ob die Befruchtung außerhalb oder innerhalb des Körpers stattfindet und ob sich der Embryo innerhalb oder außerhalb des Körpers entwickelt. Das entspricht dem Unterkonzept Reproduktion und Fortpflanzung. Lernende erkennen, dass die frühe Entwicklung eines Lebewesens in den Wirbeltierklassen unter unterschiedlichen Bedingungen verläuft.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '4450863c-2bdf-44df-85ca-9b9d19076272' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Der Klassenvergleich zeigt verschiedene Fortpflanzungsweisen als Vielfalt innerhalb der Wirbeltiere, Evolutionsprozesse werden aber nicht behandelt.$t$ AND content #>> '{basiskonzeptbezug,1,begruendung}' = $t$Befruchtung und Entwicklung des Embryos sind Teil der Fortpflanzung und der Individualentwicklung. Verglichen wird die Entwicklung innerhalb und außerhalb des Körpers.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,0,begruendung}', to_jsonb($t$Flossen sind eine Angepasstheit der Fische, und Angepasstheit ist im Basiskonzept ein Ergebnis der Stammesgeschichte. Daher gibt es einen Bezug. Das Modellexperiment untersucht jedoch nur die Funktionsweise der Flossen. Dem Kern fehlt die Frage, wie solche Merkmale über viele Generationen entstanden sind. Evolution wird im Lernziel nicht angesprochen.$t$::text)), '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Am Modell wird untersucht, wie Flossen beim Schwimmen wirken. Das verbindet Gestalt und Leistung eines Körperteils und entspricht dem Unterkonzept morphologische und anatomische Angepasstheit. Das Modell erlaubt Lernenden, den Zusammenhang selbst zu erproben. Sie bauen dabei die Denkweise auf, aus dem Bau einer Struktur ihre Wirkung abzuleiten.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = '0380eb86-72da-4686-bc7b-78343c263d39' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,0,begruendung}' = $t$Das Thema Angepasstheit der Fische berührt Ergebnisse der Stammesgeschichte, das Modellexperiment selbst spricht Evolution aber nicht an.$t$ AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Am Modell wird untersucht, wie Flossen gebaut sind und wie sie beim Schwimmen wirken. Das ist Bau-Funktions-Denken im Kern.$t$;
UPDATE lpm_data_objects SET content = jsonb_set(jsonb_set(jsonb_set(content, '{basiskonzeptbezug,2,begruendung}', to_jsonb($t$Blutkreislauf oder Lunge mit der Modellmethode darzustellen macht die einzelnen Teile und ihr Zusammenwirken sichtbar. Bau und Anordnung der Teile hängen mit der Funktion des Ganzen zusammen, und dieser Zusammenhang von Struktur und Funktion wird im Modell greifbar. Lernende bauen die Denkweise auf, ein Organ oder ein Organsystem als Gefüge zusammenwirkender Teile zu verstehen, deren Aufbau seine Leistung erklärt.$t$::text)), '{basiskonzeptbezug,4,begruendung}', to_jsonb($t$Blutkreislauf und Lunge hängen mit dem Transport und Austausch von Stoffen wie Sauerstoff zusammen. Insofern besteht ein Bezug zum Stoffaustausch mit der Umwelt. Dem Kern fehlt, dass das Lernziel diese Vorgänge nicht ausdrücklich nennt. Verlangt wird die Darstellung des Aufbaus, und der Stofftransport selbst bleibt unbehandelt.$t$::text)), '{ki_entwurf,begruendungen_erweitert}', '"2026-11-02"'::jsonb), updated_at = now() WHERE id = 'a9e92fdd-bed9-46cd-8e90-12d6dca4310d' AND project_id = '128043a8-f25b-415c-9380-31bdec662155' AND content #>> '{basiskonzeptbezug,2,begruendung}' = $t$Das Darstellen von Blutkreislauf oder Lungenaufbau mit der Modellmethode macht die Teile und ihr Zusammenwirken sichtbar.$t$ AND content #>> '{basiskonzeptbezug,4,begruendung}' = $t$Beide Beispiele hängen mit dem Transport und Austausch von Stoffen wie Sauerstoff zusammen, doch das Lernziel nennt diese Vorgänge nicht ausdrücklich.$t$;

DO $$
DECLARE done integer;
BEGIN
  SELECT count(*) INTO done FROM lpm_data_objects o
  WHERE o.project_id IN (SELECT id FROM projects WHERE slug IN ('evomentor-thuringia', 'evomentor-thuringia-sandbox'))
    AND o.content -> 'ki_entwurf' ->> 'begruendungen_erweitert' = '2026-11-02';
  IF done <> 230 THEN
    RAISE EXCEPTION 'migration 218: expected 230 goals with longer explanations (115 per space), found %', done;
  END IF;
END $$;
